    void log_msg(HANDLE hf, const char* tag, const char* fmt, ...);

    bool process_alive_by_pid(uint32_t pid, uint32_t* exit_code_out = nullptr) {
        if (exit_code_out)
            *exit_code_out = 0;
        if (pid == 0)
            return false;
        HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
        if (!h) {
            if (exit_code_out)
                *exit_code_out = GetLastError();
            return false;
        }
        DWORD exit_code = 0;
        const bool ok = GetExitCodeProcess(h, &exit_code) != FALSE;
        CloseHandle(h);
        if (exit_code_out)
            *exit_code_out = ok ? exit_code : GetLastError();
        return ok && exit_code == STILL_ACTIVE;
    }

    void log_cascade_diag_snapshot(HANDLE hf, const char* tag, const char* phase) {
        std::string kernel_session_reason;
        const bool kernel_session_ok = driver_bridge::kernel_session_available(&kernel_session_reason);
        const auto last_diag = driver_bridge::last_remote_call_execution_diag();
        const uint32_t inflight_now = driver_bridge::detail::remote_call_um_inflight_count_global();
        const uint32_t abandoned_now = driver_bridge::detail::remote_call_um_abandoned_count_global();
        log_msg(hf, tag,
            "DIAG -- %s kernel_session_available=%d kernel_session_reason=\"%s\" driver_status=\"%s\" driver_last_error=\"%s\" attached_pid=%u remote_call_inflight=%u remote_call_abandoned=%u last_remote_call_phase=\"%s\" last_remote_call_completion=\"%s\" last_remote_call_completed=%d last_remote_call_gle=%u",
            phase ? phase : "",
            kernel_session_ok ? 1 : 0,
            kernel_session_reason.c_str(),
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str(),
            driver_bridge::attached_pid(),
            inflight_now,
            abandoned_now,
            last_diag.phase.c_str(),
            last_diag.completion_reason.c_str(),
            last_diag.completed ? 1 : 0,
            last_diag.gle);
    }

    bool restore_mcp_target(HANDLE hf, const char* tag) {
        if (g_mcp_target_pid == 0)
            return false;

        const uint32_t target_pid = g_mcp_target_pid;
        const DWORD started = GetTickCount();
        for (int attempt = 1; attempt <= 3; ++attempt) {
            const uint32_t current = driver_bridge::attached_pid();
            bool known = false;
            const auto attached = driver_bridge::attached_pids();
            for (auto p : attached) {
                if (p == target_pid) {
                    known = true;
                    break;
                }
            }

            uint32_t win32_code = 0;
            const bool win32_alive = process_alive_by_pid(target_pid, &win32_code);
            bool ok = current == target_pid;
            const char* method = ok ? "already_active" : "none";
            if (!ok && known) {
                method = "set_active";
                ok = driver_bridge::set_active_pid(target_pid);
            }
            if (!ok) {
                method = "attach_additional";
                ok = driver_bridge::attach_additional(target_pid);
                if (ok) {
                    method = "attach_additional_set_active";
                    ok = driver_bridge::set_active_pid(target_pid);
                }
            }
            if (!ok) {
                method = "attach";
                ok = driver_bridge::attach(target_pid);
            }

            const uint32_t now = driver_bridge::attached_pid();
            uint32_t bridge_code = 0;
            const bool bridge_alive = now == target_pid && driver_bridge::attached_process_alive(&bridge_code);
            log_msg(hf, tag, "%s -- restore MCP target attempt=%d pid=%u from_active=%u known=%d attached_count=%zu method=%s ok=%d now=%u win32_alive=%d win32_code=0x%08X bridge_alive=%d bridge_code=0x%08X status=\"%s\" last_error=\"%s\" elapsed_ms=%lu",
                (ok && bridge_alive) ? "INFO" : "WARN",
                attempt,
                target_pid,
                current,
                known ? 1 : 0,
                attached.size(),
                method,
                ok ? 1 : 0,
                now,
                win32_alive ? 1 : 0,
                win32_code,
                bridge_alive ? 1 : 0,
                bridge_code,
                driver_bridge::status().c_str(),
                driver_bridge::last_error().c_str(),
                static_cast<unsigned long>(GetTickCount() - started));
            if (ok && bridge_alive) {
                uint64_t test_read_addr = 0;
                const auto modules = driver_bridge::enumerate_modules();
                if (!modules.empty())
                    test_read_addr = modules.front().base;
                size_t test_bytes = 0;
                if (test_read_addr != 0) {
                    std::vector<uint8_t> test_buf;
                    const bool test_read_ok = driver_bridge::read_memory(test_read_addr, 16, test_buf);
                    test_bytes = test_read_ok ? test_buf.size() : 0;
                }
                if (test_bytes == 0) {
                    log_msg(hf, tag,
                        "WARN -- restore_mcp_target kernel_ioctl_probe_failed attempt=%d pid=%u test_addr=0x%016llX test_bytes=%zu bridge_alive=%d",
                        attempt,
                        target_pid,
                        static_cast<unsigned long long>(test_read_addr),
                        test_bytes,
                        bridge_alive ? 1 : 0);
                } else {
                    g_mcp_target_unavailable = false;
                    return true;
                }
            }
            Sleep(50);
        }
        std::string kernel_session_reason;
        const bool kernel_session_ok = driver_bridge::kernel_session_available(&kernel_session_reason);
        log_msg(hf, tag,
            "FAIL -- restore_mcp_target_all_attempts_failed pid=%u kernel_session_available=%d kernel_session_reason=\"%s\" driver_status=\"%s\" driver_last_error=\"%s\"",
            target_pid,
            kernel_session_ok ? 1 : 0,
            kernel_session_reason.c_str(),
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str());
        log_cascade_diag_snapshot(hf, tag, "restore_mcp_target_failed");
        return false;
    }

    bool ensure_mcp_target_live(HANDLE hf, const char* tag) {
        if (g_mcp_target_pid == 0) {
            g_mcp_target_unavailable = true;
            log_msg(hf, tag, "SKIP -- no MCP target pid is available");
            return false;
        }

        if (!restore_mcp_target(hf, tag)) {
            g_mcp_target_unavailable = true;
            return false;
        }

        uint32_t exit_code = 0;
        const bool alive = driver_bridge::attached_process_alive(&exit_code);
        if (!alive) {
            g_mcp_target_unavailable = true;
            log_msg(hf, tag, "FAIL -- MCP target pid=%u is no longer alive (exit_code_or_err=0x%08X)",
                g_mcp_target_pid, exit_code);
        } else {
            g_mcp_target_unavailable = false;
        }
        return alive;
    }

