    void record_safe_fail_closed_guard_tool(HANDLE hf, const char* tag, const char* tool_name, const std::string& reason, std::atomic<int>& failed) {
        std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (tool_name_s.empty())
            tool_name_s = mcp_tool_name_from_tag(tag);
        const std::string tool_lc = lower_copy(tool_name_s);
        const bool security_guard = mcp_tool_has_safe_external_guard_exemption(tool_lc);
        if (!tool_name_s.empty()) {
            g_invoked_tools.insert(tool_name_s);
            record_tool_status(tool_name_s, security_guard ? mcp_tool_call_status_t::security_guard_pass : mcp_tool_call_status_t::dependency_blocked);
        }
        log_msg(hf, tag ? tag : "mcp.safe_fail_closed_guard", "%s -- tool=\"%s\" safe_fail_closed=1 dependency_blocked=%d security_guard=%d reason=%s",
            security_guard ? "SECURITY-GUARD-PASS" : "BLOCKED-FAIL",
            tool_name_s.empty() ? "<unknown>" : tool_name_s.c_str(),
            security_guard ? 0 : 1,
            security_guard ? 1 : 0,
            reason.empty() ? "<empty>" : compact_text(reason, 900).c_str());
        if (!security_guard)
            failed.fetch_add(1);
    }

    void convert_last_pass_to_fixture_failure(const char* tool_name, std::atomic<int>& passed, std::atomic<int>& failed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (!tool_name_s.empty())
            convert_tool_pass_to_fail(tool_name_s);
        int current = passed.load(std::memory_order_acquire);
        while (current > 0 && !passed.compare_exchange_weak(current, current - 1, std::memory_order_acq_rel, std::memory_order_acquire)) {
        }
        failed.fetch_add(1, std::memory_order_acq_rel);
    }

    void convert_last_failure_to_fixture_pass(const char* tool_name, std::atomic<int>& passed, std::atomic<int>& failed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (!tool_name_s.empty())
            convert_tool_fail_to_pass(tool_name_s);
        int current = failed.load(std::memory_order_acquire);
        while (current > 0 && !failed.compare_exchange_weak(current, current - 1, std::memory_order_acq_rel, std::memory_order_acquire)) {
        }
        passed.fetch_add(1, std::memory_order_acq_rel);
    }

    void convert_last_accepted_pending_to_fixture_pass(const char* tool_name, std::atomic<int>& passed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        const bool converted = convert_tool_accepted_pending_to_pass(tool_name_s);
        if (!converted && !tool_name_s.empty())
            record_tool_status(tool_name_s, mcp_tool_call_status_t::functional_pass);
        passed.fetch_add(1, std::memory_order_acq_rel);
    }

    void convert_last_accepted_pending_to_fixture_failure(const char* tool_name, std::atomic<int>& failed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        const bool converted = convert_tool_accepted_pending_to_fail(tool_name_s);
        if (!converted && !tool_name_s.empty())
            record_tool_status(tool_name_s, mcp_tool_call_status_t::failed);
        failed.fetch_add(1, std::memory_order_acq_rel);
    }

    void convert_last_pass_to_cascade_blocked(HANDLE hf, const char* tag, const char* tool_name, const std::string& reason, std::atomic<int>& passed, std::atomic<int>& failed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (!tool_name_s.empty())
            convert_tool_pass_to_cascade_blocked(tool_name_s);
        int current = passed.load(std::memory_order_acquire);
        while (current > 0 && !passed.compare_exchange_weak(current, current - 1, std::memory_order_acq_rel, std::memory_order_acquire)) {
        }
        failed.fetch_add(1, std::memory_order_acq_rel);
        log_msg(hf, tag ? tag : "mcp.cascade_blocked", "CASCADE-BLOCKED -- tool=\"%s\" converted_from=functional_pass blocked_by_tool=\"protocol_re_emit_stimulus\" blocked_by_diag_id=\"no_stimulus_packets\" reason=%s",
            tool_name_s.empty() ? "<unknown>" : tool_name_s.c_str(),
            reason.empty() ? "<empty>" : compact_text(reason, 900).c_str());
    }

    void convert_last_failure_to_cascade_blocked(HANDLE hf, const char* tag, const char* tool_name, const std::string& reason) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (!tool_name_s.empty())
            convert_tool_fail_to_cascade_blocked(tool_name_s);
        log_msg(hf, tag ? tag : "mcp.cascade_blocked", "CASCADE-BLOCKED -- tool=\"%s\" converted_from=failed blocked_by_tool=\"protocol_re_emit_stimulus\" blocked_by_diag_id=\"no_stimulus_packets\" reason=%s",
            tool_name_s.empty() ? "<unknown>" : tool_name_s.c_str(),
            reason.empty() ? "<empty>" : compact_text(reason, 900).c_str());
    }

    void record_missing_created_id(HANDLE hf,
                                   const char* tag,
                                   const char* tool_name,
                                   const char* id_name,
                                   const mcp_standalone::tool_result_t& result,
                                   std::atomic<int>& passed,
                                   std::atomic<int>& failed) {
        log_msg(hf, tag, "FAIL -- creator action completed without required %s text=%s data=%s",
            id_name ? id_name : "id",
            compact_text(result.text, 700).c_str(),
            compact_json(result.data, 900).c_str());
        convert_last_pass_to_fixture_failure(tool_name, passed, failed);
    }

    bool skip_dependent_missing_id(HANDLE hf, const char* tag, const char* id_name, std::atomic<int>& failed) {
        const std::string reason = std::string("prerequisite ") + (id_name ? id_name : "id") + " was not produced; dependent action not dispatched";
        record_dependency_blocked_tool(hf, tag, nullptr, reason, failed);
        return true;
    }

    void record_camoufox_bridge_blocked_tool(HANDLE hf, const char* tag, const char* tool_name, const std::string& reason, std::atomic<int>& failed) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        if (tool_name_s.empty()) {
            failed.fetch_add(1);
            return;
        }
        g_invoked_tools.insert(tool_name_s);
        const auto* tool = find_registered_tool(get_server(), tool_name);
        const auto st = aida::burp::camoufox::get_status();
        if (!tool) {
            log_msg(hf, tag, "FAIL -- Camoufox browser tool \"%s\" is not registered while bridge was blocked reason=%s %s",
                tool_name_s.c_str(),
                reason.empty() ? "<empty>" : compact_text(reason, 900).c_str(),
                camoufox_status_compact(st).c_str());
            record_tool_status(tool_name_s, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return;
        }
        if (!tool->handler) {
            log_msg(hf, tag, "FAIL -- Camoufox browser tool \"%s\" has no handler while bridge was blocked reason=%s %s",
                tool_name_s.c_str(),
                reason.empty() ? "<empty>" : compact_text(reason, 900).c_str(),
                camoufox_status_compact(st).c_str());
            record_tool_status(tool_name_s, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return;
        }
        log_msg(hf, tag, "BLOCKED-FAIL -- \"%s\" not dispatched because Camoufox live bridge was not proven reason=%s read_only=%d visibility=%s params=%zu %s",
            tool_name_s.c_str(),
            reason.empty() ? "<empty>" : compact_text(reason, 900).c_str(),
            tool->read_only ? 1 : 0,
            tool_visibility_name(tool->visibility),
            tool->params.size(),
            camoufox_status_compact(st).c_str());
        if (!g_mcp_camoufox_bridge_first_failure_snapshot_logged) {
            g_mcp_camoufox_bridge_first_failure_snapshot_logged = true;
            log_msg(hf, tag, "CAMOUFOX-FIRST-FAILURE-SNAPSHOT -- blocked_tool=%s reason=%s status={%s} last_launch_diagnostics=%s privacy_diagnostics=%s cleanup_diagnostics=%s",
                tool_name_s.c_str(),
                reason.empty() ? "<empty>" : compact_text(reason, 900).c_str(),
                camoufox_status_compact(st).c_str(),
                compact_json(st.last_launch_diagnostics, 1400).c_str(),
                compact_json(st.privacy_diagnostics, 900).c_str(),
                compact_json(st.cleanup_diagnostics, 900).c_str());
        }
        record_tool_status(tool_name_s, mcp_tool_call_status_t::dependency_blocked);
        failed.fetch_add(1);
    }

    bool ensure_mcp_camoufox_bridge_ready_for_tool(HANDLE hf, const char* tag, const char* tool_name, std::atomic<int>& failed, std::string* out_reason = nullptr) {
        const std::string tool_name_s = tool_name ? std::string(tool_name) : std::string();
        std::string reason;
        auto st = aida::burp::camoufox::get_status();
        log_camoufox_live_bridge_status(hf, tag, "preflight_entry", st);
        auto block_sticky_failure = [&](const char* stage, int attempt, const std::string& marker) -> bool {
            reason = std::string("Camoufox sticky setup failure for ") + (tool_name_s.empty() ? std::string("<empty>") : tool_name_s) +
                ": " + (marker.empty() ? std::string("<empty>") : marker) + "; current " + camoufox_status_compact(st);
            g_mcp_camoufox_bridge_ready_proven = false;
            g_mcp_camoufox_bridge_dependency_blocked = true;
            g_mcp_camoufox_bridge_block_reason = reason;
            if (out_reason)
                *out_reason = reason;
            log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- sticky setup failure stage=%s attempt=%d tool=%s reason=%s launch_diag=%s",
                stage ? stage : "<empty>",
                attempt,
                tool_name_s.empty() ? "<empty>" : tool_name_s.c_str(),
                compact_text(reason, 900).c_str(),
                compact_json(st.last_launch_diagnostics, 1400).c_str());
            record_camoufox_bridge_blocked_tool(hf, tag, tool_name, reason, failed);
            return false;
        };

        std::string sticky_marker;
        if (!camoufox_live_bridge_status(st) && camoufox_bridge_sticky_setup_failure(st, sticky_marker))
            return block_sticky_failure("entry", 0, sticky_marker);

        if (!g_mcp_camoufox_bridge_ready_proven &&
            g_mcp_camoufox_bridge_dependency_blocked &&
            !g_mcp_camoufox_bridge_block_reason.empty() &&
            !camoufox_live_bridge_status(st)) {
            reason = std::string("previous Camoufox live bridge proof failed: ") + g_mcp_camoufox_bridge_block_reason +
                "; current " + camoufox_status_compact(st);
            if (out_reason)
                *out_reason = reason;
            record_camoufox_bridge_blocked_tool(hf, tag, tool_name, reason, failed);
            return false;
        }

        if (g_mcp_camoufox_bridge_ready_proven && camoufox_live_bridge_status(st) &&
            (g_mcp_camoufox_bridge_generation == 0 || g_mcp_camoufox_bridge_generation == st.generation)) {
            log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- cached live bridge accepted tool=%s generation=%llu child_pid=%u",
                tool_name_s.empty() ? "<empty>" : tool_name_s.c_str(),
                static_cast<unsigned long long>(st.generation),
                st.child_pid);
            if (out_reason)
                out_reason->clear();
            return true;
        }

        std::string dependency_reason;
        if (!camoufox_dependencies_ready_for_test(hf, tag, dependency_reason)) {
            reason = dependency_reason.empty() ? std::string("Camoufox dependencies are not ready") : dependency_reason;
            g_mcp_camoufox_bridge_ready_proven = false;
            g_mcp_camoufox_bridge_dependency_blocked = true;
            g_mcp_camoufox_bridge_block_reason = reason;
            if (out_reason)
                *out_reason = reason;
            record_camoufox_bridge_blocked_tool(hf, tag, tool_name, reason, failed);
            return false;
        }
        g_mcp_camoufox_bridge_dependency_blocked = false;
        g_mcp_camoufox_bridge_block_reason.clear();

        st = aida::burp::camoufox::get_status();
        if (!camoufox_live_bridge_status(st)) {
            if (st.cleanup_pending) {
                const bool idle = aida::burp::camoufox::wait_until_idle(7000, "testlab.camoufox.preflight_cleanup_wait");
                auto after_idle = aida::burp::camoufox::get_status();
                log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- cleanup wait idle=%d before=%s after=%s",
                    idle ? 1 : 0,
                    camoufox_status_compact(st).c_str(),
                    camoufox_status_compact(after_idle).c_str());
                st = after_idle;
                if (camoufox_bridge_sticky_setup_failure(st, sticky_marker))
                    return block_sticky_failure("after_cleanup_wait", 0, sticky_marker);
            }
        }

        if (!camoufox_live_bridge_status(st)) {
            for (int attempt = 1; attempt <= 2; ++attempt) {
                aida::burp::camoufox::launch_config_t cfg;
                cfg.headless = false;
                cfg.launch_timeout_ms = static_cast<int>(k_camoufox_testlab_launch_timeout_ms);
                cfg.window_width = 1280;
                cfg.window_height = 900;
                cfg.enable_trace = false;
                cfg.testlab_fast_probe = true;
                const DWORD runner_timeout = static_cast<DWORD>(static_cast<long long>(cfg.launch_timeout_ms) + k_camoufox_testlab_launch_watchdog_slack_ms);
                auto launch = bounded_camoufox_start_bridge(hf, tag, cfg, runner_timeout);
                st = launch.status;
                if (launch.completed && launch.ok && camoufox_live_bridge_status(st))
                    break;
                reason = launch.completed
                    ? std::string("Camoufox bridge launch did not produce live ready state for ") + tool_name_s + ": " + camoufox_status_compact(st)
                    : std::string("Camoufox bridge launch runner did not complete for ") + tool_name_s + " status=" + camoufox_status_compact(st);
                log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- launch attempt=%d/%d failed completed=%d ok=%d runner_error=%s reason=%s",
                    attempt,
                    2,
                    launch.completed ? 1 : 0,
                    launch.ok ? 1 : 0,
                    launch.runner_error.empty() ? "<empty>" : compact_text(launch.runner_error, 700).c_str(),
                    compact_text(reason, 900).c_str());
                if (camoufox_bridge_sticky_setup_failure(st, sticky_marker))
                    return block_sticky_failure("launch_attempt", attempt, sticky_marker);
                const std::string runner_error_l = lower_copy(launch.runner_error);
                if (!runner_error_l.empty() && runner_error_l.find("sticky_setup_failure") != std::string::npos)
                    return block_sticky_failure("launch_runner", attempt, compact_text(launch.runner_error, 700));
                if (attempt < 2) {
                    const bool stopped = aida::burp::camoufox::stop_bridge("testlab.camoufox.preflight_retry");
                    const bool idle = aida::burp::camoufox::wait_until_idle(30000, "testlab.camoufox.preflight_retry");
                    auto stopped_status = aida::burp::camoufox::get_status();
                    log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- retry cleanup stopped=%d idle=%d %s",
                        stopped ? 1 : 0,
                        idle ? 1 : 0,
                        camoufox_status_compact(stopped_status).c_str());
                    Sleep(250);
                }
            }
        }

        st = aida::burp::camoufox::get_status();
        if (!camoufox_live_bridge_status(st) &&
            st.state != aida::burp::camoufox::bridge_state_t::starting &&
            !st.child_alive &&
            !st.cleanup_pending) {
            if (reason.empty())
                reason = std::string("Camoufox bridge launch ended without live bridge for ") + tool_name_s + ": " + camoufox_status_compact(st);
            g_mcp_camoufox_bridge_ready_proven = false;
            g_mcp_camoufox_bridge_dependency_blocked = false;
            g_mcp_camoufox_bridge_block_reason.clear();
            if (out_reason)
                *out_reason = reason;
            log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- launch failed without sticky block tool=%s reason=%s %s",
                tool_name_s.empty() ? "<empty>" : tool_name_s.c_str(),
                compact_text(reason, 900).c_str(),
                camoufox_status_compact(st).c_str());
            record_camoufox_bridge_blocked_tool(hf, tag, tool_name, reason, failed);
            return false;
        }

        if (!prove_camoufox_live_bridge(hf, tag, tool_name, reason)) {
            g_mcp_camoufox_bridge_ready_proven = false;
            g_mcp_camoufox_bridge_dependency_blocked = false;
            g_mcp_camoufox_bridge_block_reason.clear();
            if (out_reason)
                *out_reason = reason;
            log_msg(hf, tag, "CAMOUFOX-PREFLIGHT -- proof failed without sticky block tool=%s reason=%s",
                tool_name_s.empty() ? "<empty>" : tool_name_s.c_str(),
                compact_text(reason, 900).c_str());
            record_camoufox_bridge_blocked_tool(hf, tag, tool_name, reason, failed);
            return false;
        }

        if (out_reason)
            out_reason->clear();
        return true;
    }

    std::filesystem::path mcp_scratch_workspace_root() {
        char tmp[MAX_PATH] = {};
        DWORD n = GetTempPathA(static_cast<DWORD>(sizeof(tmp)), tmp);
        std::filesystem::path base = (n > 0 && n < sizeof(tmp)) ? std::filesystem::path(tmp) : std::filesystem::temp_directory_path();
        return base / ("aida_mcp_testlab_workspace_" + std::to_string(GetCurrentProcessId()));
    }

    bool write_text_fixture(const std::filesystem::path& path, const std::string& text) {
        std::error_code ec;
        std::filesystem::create_directories(path.parent_path(), ec);
        if (ec)
            return false;
        std::ofstream ofs(path, std::ios::binary | std::ios::trunc);
        if (!ofs)
            return false;
        ofs << text;
        return ofs.good();
    }

    std::filesystem::path canonical_or_normal_path(const std::filesystem::path& path) {
        std::error_code ec;
        auto canonical = std::filesystem::weakly_canonical(path, ec);
        if (!ec)
            return canonical.lexically_normal();
        return path.lexically_normal();
    }

    std::wstring lower_wstring_copy(std::wstring value) {
        std::transform(value.begin(), value.end(), value.begin(), [](wchar_t c) {
            return static_cast<wchar_t>(std::towlower(c));
        });
        return value;
    }

    std::wstring normalized_path_key(const std::filesystem::path& path) {
        return lower_wstring_copy(canonical_or_normal_path(path).wstring());
    }

    bool normalized_paths_equal(const std::filesystem::path& a, const std::filesystem::path& b) {
        return normalized_path_key(a) == normalized_path_key(b);
    }

    bool path_is_under_root(const std::filesystem::path& root, const std::filesystem::path& candidate) {
        const std::wstring root_key = normalized_path_key(root);
        const std::wstring candidate_key = normalized_path_key(candidate);
        if (root_key.empty() || candidate_key.empty())
            return false;
        if (candidate_key == root_key)
            return true;
        if (candidate_key.size() <= root_key.size())
            return false;
        if (candidate_key.rfind(root_key, 0) != 0)
            return false;
        const wchar_t ch = candidate_key[root_key.size()];
        return ch == L'\\' || ch == L'/';
    }

    bool json_string_matches_workspace_path(const std::string& value, const std::filesystem::path& root, const std::filesystem::path& expected) {
        if (value.empty())
            return false;
        std::filesystem::path parsed = std::filesystem::u8path(value);
        if (!parsed.is_absolute())
            parsed = root / parsed;
        return path_is_under_root(root, parsed) && normalized_paths_equal(parsed, expected);
    }

    bool json_contains_workspace_path(const mcp_standalone::json& value, const std::filesystem::path& root, const std::filesystem::path& expected) {
        if (value.is_string())
            return json_string_matches_workspace_path(value.get<std::string>(), root, expected);
        if (value.is_array()) {
            for (const auto& item : value) {
                if (json_contains_workspace_path(item, root, expected))
                    return true;
            }
            return false;
        }
        if (value.is_object()) {
            for (auto it = value.begin(); it != value.end(); ++it) {
                if (json_contains_workspace_path(it.value(), root, expected))
                    return true;
            }
        }
        return false;
    }

    struct scoped_mcp_workspace_t {
        std::string old_current_dir;
        std::string old_workspace_root;
        std::filesystem::path root;
        bool active = false;

        scoped_mcp_workspace_t(HANDLE hf, const char* tag) {
            old_current_dir = file_browser::current_dir;
            old_workspace_root = g_sa_settings.workspace.root_path;
            root = mcp_scratch_workspace_root();
            std::error_code ec;
            std::filesystem::create_directories(root, ec);
            if (ec) {
                log_msg(hf, tag, "FAIL -- scratch workspace create failed path=%s err=%lu",
                    root.string().c_str(), static_cast<unsigned long>(ec.value()));
                return;
            }
            file_browser::current_dir = root.string();
            g_sa_settings.workspace.root_path = root.string();
            active = true;
            log_msg(hf, tag, "INFO -- scratch workspace active path=%s", file_browser::current_dir.c_str());
        }

        ~scoped_mcp_workspace_t() {
            if (active) {
                file_browser::current_dir = old_current_dir;
                g_sa_settings.workspace.root_path = old_workspace_root;
            }
        }
    };

    bool ensure_mcp_private_bytes(HANDLE hf, const char* tag, uint64_t& addr, size_t size, const std::vector<uint8_t>& bytes) {
        if (!ensure_mcp_target_live(hf, tag))
            return false;
        const uint32_t active_before_alloc = driver_bridge::attached_pid();
        const uint32_t fixture_pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : active_before_alloc;
        const DWORD fixture_start = GetTickCount();
        if (fixture_pid == 0) {
            log_msg(hf, tag, "SKIP -- MCP fixture target pid unavailable size=%zu requested_bytes=%zu active_pid=%u target_pid=%u",
                size,
                bytes.size(),
                active_before_alloc,
                g_mcp_target_pid);
            log_cascade_diag_snapshot(hf, tag, "ensure_mcp_private_bytes_no_target_pid");
            return false;
        }
        if (addr == 0) {
            addr = driver_bridge::allocate_memory(size);
            if (addr == 0) {
                log_msg(hf, tag, "SKIP -- allocate_memory failed for MCP fixture pid=%u size=%zu active_pid=%u target_pid=%u status=\"%s\" last_error=\"%s\" elapsed_ms=%lu",
                    fixture_pid,
                    size,
                    driver_bridge::attached_pid(),
                    g_mcp_target_pid,
                    driver_bridge::status().c_str(),
                    driver_bridge::last_error().c_str(),
                    static_cast<unsigned long>(GetTickCount() - fixture_start));
                log_cascade_diag_snapshot(hf, tag, "ensure_mcp_private_bytes_allocate_zero");
                return false;
            }
            log_msg(hf, tag, "FIXTURE -- allocated addr=0x%016llX size=%zu active_before=%u active_after=%u target_pid=%u fixture_pid=%u elapsed_ms=%lu",
                static_cast<unsigned long long>(addr),
                size,
                active_before_alloc,
                driver_bridge::attached_pid(),
                g_mcp_target_pid,
                fixture_pid,
                static_cast<unsigned long>(GetTickCount() - fixture_start));
        }
        if (driver_bridge::attached_pid() != g_mcp_target_pid && !restore_mcp_target(hf, tag)) {
            log_msg(hf, tag, "SKIP -- unable to restore MCP target before fixture write active_pid=%u target_pid=%u",
                driver_bridge::attached_pid(), g_mcp_target_pid);
            return false;
        }
        uint32_t old_protect = 0;
        const bool protect_ok = driver_bridge::protect_memory_for(fixture_pid, addr, size, PAGE_EXECUTE_READWRITE, &old_protect);
        log_msg(hf, tag, "FIXTURE -- protect addr=0x%016llX size=%zu ok=%d old=0x%08X active_pid=%u target_pid=%u fixture_pid=%u status=\"%s\" last_error=\"%s\" elapsed_ms=%lu",
            static_cast<unsigned long long>(addr),
            size,
            protect_ok ? 1 : 0,
            old_protect,
            driver_bridge::attached_pid(),
            g_mcp_target_pid,
            fixture_pid,
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str(),
            static_cast<unsigned long>(GetTickCount() - fixture_start));
        if (driver_bridge::attached_pid() != g_mcp_target_pid && !restore_mcp_target(hf, tag)) {
            log_msg(hf, tag, "SKIP -- unable to restore MCP target after fixture protect active_pid=%u target_pid=%u",
                driver_bridge::attached_pid(), g_mcp_target_pid);
            driver_bridge::free_memory(addr);
            addr = 0;
            return false;
        }
        if (!bytes.empty() && !driver_bridge::write_memory_for(fixture_pid, addr, bytes)) {
            log_msg(hf, tag, "SKIP -- write_memory failed for MCP fixture addr=0x%016llX bytes=%zu active_pid=%u target_pid=%u fixture_pid=%u status=\"%s\" last_error=\"%s\" elapsed_ms=%lu",
                static_cast<unsigned long long>(addr),
                bytes.size(),
                driver_bridge::attached_pid(),
                g_mcp_target_pid,
                fixture_pid,
                driver_bridge::status().c_str(),
                driver_bridge::last_error().c_str(),
                static_cast<unsigned long>(GetTickCount() - fixture_start));
            driver_bridge::free_memory(addr);
            addr = 0;
            return false;
        }
        if (driver_bridge::attached_pid() != g_mcp_target_pid && !restore_mcp_target(hf, tag)) {
            log_msg(hf, tag, "SKIP -- unable to restore MCP target before fixture readback active_pid=%u target_pid=%u",
                driver_bridge::attached_pid(), g_mcp_target_pid);
            driver_bridge::free_memory(addr);
            addr = 0;
            return false;
        }
        if (!bytes.empty()) {
            std::vector<uint8_t> verify;
            const bool read_ok = driver_bridge::read_memory_for(fixture_pid, addr, bytes.size(), verify);
            const bool match = read_ok &&
                verify.size() >= bytes.size() &&
                std::equal(bytes.begin(), bytes.end(), verify.begin());
            if (!match) {
                log_msg(hf, tag, "SKIP -- MCP fixture readback mismatch addr=0x%016llX wrote=%zu read_ok=%d read=%zu active_pid=%u target_pid=%u fixture_pid=%u status=\"%s\" last_error=\"%s\" elapsed_ms=%lu expected=[%s] actual=[%s]",
                    static_cast<unsigned long long>(addr),
                    bytes.size(),
                    read_ok ? 1 : 0,
                    verify.size(),
                    driver_bridge::attached_pid(),
                    g_mcp_target_pid,
                    fixture_pid,
                    driver_bridge::status().c_str(),
                    driver_bridge::last_error().c_str(),
                    static_cast<unsigned long>(GetTickCount() - fixture_start),
                    hex_preview(bytes).c_str(),
                    hex_preview(verify).c_str());
                driver_bridge::free_memory(addr);
                addr = 0;
                return false;
            }
        }
        return true;
    }

    bool ensure_mcp_private_patch_fixture(HANDLE hf, const char* tag) {
        std::vector<uint8_t> bytes(64, 0x90);
        bytes[0] = 0x48;
        bytes[1] = 0x31;
        bytes[2] = 0xC0;
        bytes[3] = 0xC3;
        return ensure_mcp_private_bytes(hf, tag, g_mcp_patch_addr, bytes.size(), bytes);
    }

    bool ensure_mcp_scanner_pointer_fixture(HANDLE hf, const char* tag) {
        if (!ensure_mcp_private_bytes(hf, tag, g_mcp_scanner_addr, 4096, {0x1A, 0x2B, 0x3C, 0x4D}))
            return false;

        if (g_mcp_scanner_pointer_addr == 0) {
            g_mcp_scanner_pointer_addr = driver_bridge::allocate_memory(4096);
            if (g_mcp_scanner_pointer_addr == 0) {
                log_msg(hf, tag, "SKIP -- allocate_memory failed for scanner pointer slots target=0x%016llX",
                    static_cast<unsigned long long>(g_mcp_scanner_addr));
                return false;
            }
        }

        std::vector<uint8_t> bytes(4096, 0);
        const uint64_t target = g_mcp_scanner_addr;
        for (size_t off = 0; off + sizeof(target) <= bytes.size(); off += 16)
            std::memcpy(bytes.data() + off, &target, sizeof(target));

        if (!driver_bridge::write_memory(g_mcp_scanner_pointer_addr, bytes)) {
            log_msg(hf, tag, "SKIP -- write_memory failed for scanner pointer slots addr=0x%016llX target=0x%016llX",
                static_cast<unsigned long long>(g_mcp_scanner_pointer_addr),
                static_cast<unsigned long long>(g_mcp_scanner_addr));
            driver_bridge::free_memory(g_mcp_scanner_pointer_addr);
            g_mcp_scanner_pointer_addr = 0;
            return false;
        }

        uint32_t old_protect = 0;
        driver_bridge::protect_memory(g_mcp_scanner_pointer_addr, 4096, PAGE_READWRITE, &old_protect);

        std::vector<uint8_t> check;
        const bool read_ok = driver_bridge::read_memory(g_mcp_scanner_pointer_addr, sizeof(target), check);
        uint64_t read_value = 0;
        if (read_ok && check.size() >= sizeof(read_value))
            std::memcpy(&read_value, check.data(), sizeof(read_value));
        const bool ok = read_ok && read_value == target;
        log_msg(hf, tag, "scanner pointer fixture target=0x%016llX slot=0x%016llX read_ok=%d read_value=0x%016llX",
            static_cast<unsigned long long>(target),
            static_cast<unsigned long long>(g_mcp_scanner_pointer_addr),
            read_ok ? 1 : 0,
            static_cast<unsigned long long>(read_value));
        if (!ok) {
            driver_bridge::free_memory(g_mcp_scanner_pointer_addr);
            g_mcp_scanner_pointer_addr = 0;
        }
        return ok;
    }

    bool json_scalar_truthy(const mcp_standalone::json& value) {
        if (value.is_boolean())
            return value.get<bool>();
        if (value.is_number_unsigned())
            return value.get<uint64_t>() != 0;
        if (value.is_number_integer())
            return value.get<int64_t>() != 0;
        if (value.is_number_float())
            return value.get<double>() != 0.0;
        if (value.is_string()) {
            const std::string s = lower_copy(value.get<std::string>());
            return s == "1" || s == "true" || s == "yes" || s == "on";
        }
        return false;
    }

    bool json_scalar_falsey(const mcp_standalone::json& value) {
        if (value.is_boolean())
            return !value.get<bool>();
        if (value.is_number_unsigned())
            return value.get<uint64_t>() == 0;
        if (value.is_number_integer())
            return value.get<int64_t>() == 0;
        if (value.is_number_float())
            return value.get<double>() == 0.0;
        if (value.is_string()) {
            const std::string s = lower_copy(value.get<std::string>());
            return s == "0" || s == "false" || s == "no" || s == "off";
        }
        return false;
    }

    bool key_ends_with(const std::string& key, const char* suffix) {
        if (!suffix)
            return false;
        const std::string suffix_s = suffix;
        return key.size() >= suffix_s.size() &&
            std::equal(suffix_s.rbegin(), suffix_s.rend(), key.rbegin());
    }

    bool inspect_payload_object_failure(const mcp_standalone::json& obj, std::string& reason) {
        if (!obj.is_object())
            return false;

        for (auto it = obj.begin(); it != obj.end(); ++it) {
            if (key_ends_with(it.key(), "_degraded") && json_scalar_truthy(*it)) {
                reason = it.key() + "=true";
                return true;
            }
        }

        auto dependency_available_it = obj.find("dependency_available");
        if (dependency_available_it != obj.end() && json_scalar_falsey(*dependency_available_it)) {
            reason = "dependency_available=false";
            return true;
        }

        auto dependency_unavailable_it = obj.find("dependency_unavailable");
        if (dependency_unavailable_it != obj.end() && json_scalar_truthy(*dependency_unavailable_it)) {
            reason = "dependency_unavailable=true";
            return true;
        }

        auto z3_requested_it = obj.find("z3_requested");
        auto z3_used_it = obj.find("z3_used");
        if (z3_requested_it != obj.end() && z3_used_it != obj.end() &&
            json_scalar_truthy(*z3_requested_it) && json_scalar_falsey(*z3_used_it)) {
            reason = "z3_requested=true_z3_used=false";
            return true;
        }

        auto direct_u64 = [&](const char* key, uint64_t& out) -> bool {
            auto it = obj.find(key);
            if (it == obj.end())
                return false;
            if (it->is_number_unsigned()) {
                out = it->get<uint64_t>();
                return true;
            }
            if (it->is_number_integer()) {
                const auto raw = it->get<int64_t>();
                if (raw >= 0) {
                    out = static_cast<uint64_t>(raw);
                    return true;
                }
            }
            if (it->is_string()) {
                const std::string text = it->get<std::string>();
                const char* s = text.c_str();
                while (*s == ' ' || *s == '\t')
                    ++s;
                if (*s == '\0')
                    return false;
                char* end = nullptr;
                const uint64_t parsed = std::strtoull(s, &end, 0);
                if (end == s)
                    return false;
                while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')
                    ++end;
                if (*end != '\0')
                    return false;
                out = parsed;
                return true;
            }
            return false;
        };

        auto direct_string = [&](const char* key, std::string& out) -> bool {
            auto it = obj.find(key);
            if (it == obj.end() || !it->is_string())
                return false;
            out = it->get<std::string>();
            return true;
        };

        uint64_t transport_failures = 0;
        uint64_t transport_error_code = 0;
        if (direct_u64("transport_failures", transport_failures) && transport_failures > 0) {
            reason = "transport_failures=" + std::to_string(static_cast<unsigned long long>(transport_failures));
            return true;
        }
        if (direct_u64("transport_error_code", transport_error_code) && transport_error_code > 0) {
            reason = "transport_error_code=" + std::to_string(static_cast<unsigned long long>(transport_error_code));
            return true;
        }
        std::string transport_text;
        if (direct_string("last_transport_error", transport_text) && !transport_text.empty()) {
            reason = "last_transport_error=" + transport_text;
            return true;
        }
        if (direct_string("transport_error", transport_text) && !transport_text.empty()) {
            reason = "transport_error=" + transport_text;
            return true;
        }

        auto degraded_string = [&](const char* key) -> bool {
            auto it = obj.find(key);
            if (it != obj.end() && it->is_string() && !it->get<std::string>().empty()) {
                reason = std::string(key) + "=" + it->get<std::string>();
                return true;
            }
            return false;
        };

        auto degraded_true = [&](const char* key) -> bool {
            auto it = obj.find(key);
            if (it != obj.end() && it->is_boolean() && it->get<bool>()) {
                reason = std::string(key) + "=true";
                return true;
            }
            return false;
        };

        if (degraded_string("transport_error") ||
            degraded_true("fixture_transport_fallback") ||
            degraded_true("offline_validated") ||
            degraded_true("fixture_noop") ||
            degraded_true("setup_pending") ||
            degraded_true("noop")) {
            return true;
        }

        auto success_it = obj.find("success");
        if (success_it != obj.end() && success_it->is_boolean() && !success_it->get<bool>()) {
            reason = "success=false";
            auto err = obj.find("error");
            if (err != obj.end() && err->is_string() && !err->get<std::string>().empty())
                reason += ": " + err->get<std::string>();
            return true;
        }

        auto status_it = obj.find("status");
        if (status_it != obj.end() && status_it->is_string()) {
            std::string status = lower_copy(status_it->get<std::string>());
            if (status == "failed" || status == "error") {
                reason = status;
                auto err = obj.find("error");
                if (err != obj.end() && err->is_string() && !err->get<std::string>().empty())
                    reason += ": " + err->get<std::string>();
                return true;
            }
            if (status == "backend_unavailable" || status == "unavailable" ||
                status == "not_applicable" || status == "no_captures" ||
                status == "no-data" || status == "no_data") {
                reason = "status=" + status;
                return true;
            }
        }

        auto ok_it = obj.find("ok");
        if (ok_it != obj.end() && ok_it->is_boolean() && !ok_it->get<bool>()) {
            reason = "ok=false";
            auto err = obj.find("error");
            if (err != obj.end() && err->is_string() && !err->get<std::string>().empty())
                reason += ": " + err->get<std::string>();
            return true;
        }

        auto removed_it = obj.find("removed");
        if (removed_it != obj.end() && removed_it->is_boolean() && !removed_it->get<bool>()) {
            auto validate_only_it = obj.find("validate_only");
            if (validate_only_it != obj.end() && validate_only_it->is_boolean() && validate_only_it->get<bool>())
                return false;
            reason = "removed=false";
            return true;
        }

        auto neutralized_it = obj.find("neutralized");
        if (neutralized_it != obj.end() && neutralized_it->is_boolean() && !neutralized_it->get<bool>()) {
            reason = "neutralized=false";
            return true;
        }

        auto xml_it = obj.find("xml");
        if (xml_it != obj.end() && xml_it->is_string() && xml_it->get<std::string>().empty()) {
            reason = "xml is empty";
            return true;
        }

        auto timed_out_it = obj.find("timed_out");
        if (timed_out_it != obj.end() && timed_out_it->is_boolean() && timed_out_it->get<bool>()) {
            reason = "timed_out=true";
            return true;
        }

        auto value_it = obj.find("value");
        if (value_it != obj.end() && value_it->is_string()) {
            const std::string value = lower_copy(value_it->get<std::string>());
            if (value.find("<read error>") != std::string::npos || value.find("read error") != std::string::npos) {
                reason = "value read error";
                return true;
            }
        }

        return false;
    }

    bool re_or_protected_re_tool_name(const std::string& tool_lc) {
        for (const char* prefix : {
                 "dx_",
                 "rtti_",
                 "encptr_",
                 "struct_",
                 "heap_track_",
                 "drv_",
                 "smc_",
                 "cff_",
                 "vmp_",
                 "seh_"
             }) {
            if (tool_lc.rfind(prefix, 0) == 0)
                return true;
        }
        return false;
    }

    bool re_payload_has_incomplete_bounded_evidence(const std::string& tool_lc,
                                                    const mcp_standalone::json& obj,
                                                    std::string& reason) {
        if (!re_or_protected_re_tool_name(tool_lc) || !obj.is_object())
            return false;
        for (const char* key : {
                 "partial",
                 "partial_result",
                 "deadline_hit",
                 "deadline_expired",
                 "cancelled",
                 "canceled",
                 "timed_out",
                 "truncated",
                 "result_truncated",
                 "blocks_truncated",
                 "il_truncated",
                 "change_rows_truncated",
                 "payload_truncated"
             }) {
            auto it = obj.find(key);
            if (it != obj.end() && json_scalar_truthy(*it)) {
                reason = std::string(key) + "=true";
                return true;
            }
        }
        return false;
    }

    const mcp_standalone::json* find_payload_key_recursive(const mcp_standalone::json& value,
                                                           const char* key) {
        if (!key)
            return nullptr;
        if (value.is_object()) {
            auto it = value.find(key);
            if (it != value.end())
                return &(*it);
            for (auto it2 = value.begin(); it2 != value.end(); ++it2) {
                if (const auto* found = find_payload_key_recursive(*it2, key))
                    return found;
            }
        } else if (value.is_array()) {
            for (const auto& item : value) {
                if (const auto* found = find_payload_key_recursive(item, key))
                    return found;
            }
        }
        return nullptr;
    }

    bool payload_bool_field(const mcp_standalone::json& value, const char* key, bool& out) {
        const auto* found = find_payload_key_recursive(value, key);
        if (!found || !found->is_boolean())
            return false;
        out = found->get<bool>();
        return true;
    }

    bool payload_u64_field(const mcp_standalone::json& value, const char* key, uint64_t& out) {
        const auto* found = find_payload_key_recursive(value, key);
        if (!found)
            return false;
        if (found->is_number_unsigned()) {
            out = found->get<uint64_t>();
            return true;
        }
        if (found->is_number_integer()) {
            const auto v = found->get<int64_t>();
            if (v >= 0) {
                out = static_cast<uint64_t>(v);
                return true;
            }
        }
        return false;
    }

    bool payload_string_field(const mcp_standalone::json& value, const char* key, std::string& out) {
        const auto* found = find_payload_key_recursive(value, key);
        if (!found || !found->is_string())
            return false;
        out = found->get<std::string>();
        return true;
    }

    bool scan_transport_status_recursive(const mcp_standalone::json& value, bool& saw_status, bool& real_failure, std::string& reason) {
        if (value.is_object()) {
            bool local_status = false;
            uint64_t transport_failures = 0;
            uint64_t transport_error_code = 0;
            bool transport_degraded = false;
            std::string last_transport_error;
            std::string transport_error;
            if (payload_u64_field(value, "transport_failures", transport_failures)) {
                local_status = true;
                if (transport_failures > 0) {
                    reason = "transport_failures=" + std::to_string(static_cast<unsigned long long>(transport_failures));
                    saw_status = true;
                    real_failure = true;
                    return true;
                }
            }
            if (payload_u64_field(value, "transport_error_code", transport_error_code)) {
                local_status = true;
                if (transport_error_code > 0) {
                    reason = "transport_error_code=" + std::to_string(static_cast<unsigned long long>(transport_error_code));
                    saw_status = true;
                    real_failure = true;
                    return true;
                }
            }
            if (payload_bool_field(value, "transport_degraded", transport_degraded)) {
                local_status = true;
                if (transport_degraded) {
                    reason = "transport_degraded=true";
                    saw_status = true;
                    real_failure = true;
                    return true;
                }
            }
            if (payload_string_field(value, "last_transport_error", last_transport_error)) {
                local_status = true;
                if (!last_transport_error.empty()) {
                    reason = "last_transport_error=" + compact_text(last_transport_error, 300);
                    saw_status = true;
                    real_failure = true;
                    return true;
                }
            }
            if (payload_string_field(value, "transport_error", transport_error)) {
                local_status = true;
                if (!transport_error.empty()) {
                    reason = "transport_error=" + compact_text(transport_error, 300);
                    saw_status = true;
                    real_failure = true;
                    return true;
                }
            }
            if (local_status)
                saw_status = true;
            for (auto it = value.begin(); it != value.end(); ++it) {
                if ((it->is_object() || it->is_array()) && scan_transport_status_recursive(*it, saw_status, real_failure, reason))
                    return true;
            }
        } else if (value.is_array()) {
            for (const auto& item : value) {
                if ((item.is_object() || item.is_array()) && scan_transport_status_recursive(item, saw_status, real_failure, reason))
                    return true;
            }
        }
        return false;
    }

    bool transport_status_structured_clean(const invoke_result_t& ir, std::string& proof) {
        bool saw_status = false;
        bool real_failure = false;
        std::string reason;
        scan_transport_status_recursive(ir.data, saw_status, real_failure, reason);
        if (real_failure) {
            proof = reason.empty() ? "transport_failure_present" : reason;
            return false;
        }
        if (!saw_status) {
            proof = "transport_status_fields_missing";
            return false;
        }
        proof = "transport_status_clean";
        return true;
    }

    size_t script_entries_in_raw_text(const std::string& raw_text, const std::string& expected_marker, bool& marker_present) {
        marker_present = expected_marker.empty() || lower_copy(raw_text).find(lower_copy(expected_marker)) != std::string::npos;
        size_t count = 0;
        int depth = 0;
        bool in_string = false;
        bool escaped = false;
        size_t object_start = 0;
        for (size_t i = 0; i < raw_text.size(); ++i) {
            const char c = raw_text[i];
            if (in_string) {
                if (escaped) {
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == '"') {
                    in_string = false;
                }
                continue;
            }
            if (c == '"') {
                in_string = true;
                continue;
            }
            if (c == '{') {
                if (depth == 0)
                    object_start = i;
                ++depth;
                continue;
            }
            if (c == '}' && depth > 0) {
                --depth;
                if (depth == 0 && object_start <= i) {
                    const std::string object_text = raw_text.substr(object_start, i - object_start + 1);
                    try {
                        auto parsed = mcp_standalone::json::parse(object_text);
                        if (parsed.is_object() &&
                            (parsed.contains("src") || parsed.contains("inline_length") ||
                             parsed.contains("is_module") || parsed.contains("preview"))) {
                            ++count;
                        }
                    } catch (...) {
                    }
                }
            }
        }
        if (count == 0) {
            const std::string lc = lower_copy(raw_text);
            if (lc.find("\"src\"") != std::string::npos &&
                (lc.find("\"inline_length\"") != std::string::npos || lc.find("\"is_module\"") != std::string::npos))
                count = 1;
        }
        return count;
    }

    bool parse_u64_string_value(const std::string& value, uint64_t& out) {
        const char* s = value.c_str();
        while (*s == ' ' || *s == '\t')
            ++s;
        if (*s == '\0')
            return false;
        char* end = nullptr;
        const uint64_t parsed = std::strtoull(s, &end, 0);
        if (end == s)
            return false;
        while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')
            ++end;
        if (*end != '\0')
            return false;
        out = parsed;
        return true;
    }

    bool payload_u64_or_string_field(const mcp_standalone::json& value, const char* key, uint64_t& out) {
        if (payload_u64_field(value, key, out))
            return true;
        std::string text;
        return payload_string_field(value, key, text) && parse_u64_string_value(text, out);
    }

    bool payload_array_count(const mcp_standalone::json& value, const char* key, size_t& out) {
        const auto* found = find_payload_key_recursive(value, key);
        if (!found || !found->is_array())
            return false;
        out = found->size();
        return true;
    }

    bool payload_number_positive_field(const mcp_standalone::json& value, const char* key, double& out) {
        const auto* found = find_payload_key_recursive(value, key);
        if (!found || !found->is_number())
            return false;
        out = found->get<double>();
        return out > 0.0;
    }

    bool payload_string_field_equals_lc(const mcp_standalone::json& value, const char* key, const char* expected_lc) {
        std::string out;
        if (!payload_string_field(value, key, out))
            return false;
        return lower_copy(out) == (expected_lc ? expected_lc : "");
    }

    bool payload_bool_field_is_false(const mcp_standalone::json& value, const char* key) {
        bool out = true;
        return payload_bool_field(value, key, out) && !out;
    }

    bool args_u64_equals(const mcp_standalone::json* args, const char* key, uint64_t expected) {
        if (!args || !args->is_object())
            return false;
        uint64_t value = 0;
        return payload_u64_field(*args, key, value) && value == expected;
    }

    bool cff_detect_json_proof(const invoke_result_t& ir, std::string& reason) {
        uint64_t block_count = 0;
        double confidence = 0.0;
        if (!payload_u64_field(ir.data, "block_count", block_count) || block_count == 0) {
            reason = "cff_detect block_count missing or zero";
            return false;
        }
        if (!payload_number_positive_field(ir.data, "confidence", confidence)) {
            reason = "cff_detect confidence missing or non-positive";
            return false;
        }
        return true;
    }

    bool cff_recover_cfg_json_proof(const invoke_result_t& ir, std::string& reason) {
        size_t recovered_blocks = 0;
        size_t recovered_edges = 0;
        double confidence = 0.0;
        std::string cfg_dot;
        std::string pseudocode;
        bool partial = false;
        bool deadline_hit = false;
        bool cancelled = false;
        bool result_truncated = false;
        payload_bool_field(ir.data, "partial", partial);
        payload_bool_field(ir.data, "deadline_hit", deadline_hit);
        payload_bool_field(ir.data, "cancelled", cancelled);
        payload_bool_field(ir.data, "result_truncated", result_truncated);
        if (partial || deadline_hit || cancelled || result_truncated) {
            reason = "cff_recover_cfg reported bounded partial/truncated state partial=" +
                std::to_string(partial ? 1 : 0) +
                " deadline_hit=" + std::to_string(deadline_hit ? 1 : 0) +
                " cancelled=" + std::to_string(cancelled ? 1 : 0) +
                " result_truncated=" + std::to_string(result_truncated ? 1 : 0);
            return false;
        }
        if (!payload_array_count(ir.data, "recovered_blocks", recovered_blocks) || recovered_blocks == 0) {
            reason = "cff_recover_cfg recovered_blocks missing or empty";
            return false;
        }
        if (!payload_array_count(ir.data, "recovered_edges", recovered_edges) || recovered_edges == 0) {
            reason = "cff_recover_cfg recovered_edges missing or empty";
            return false;
        }
        if (!payload_number_positive_field(ir.data, "confidence", confidence)) {
            reason = "cff_recover_cfg detection.confidence missing or non-positive";
            return false;
        }
        if (!payload_string_field(ir.data, "cfg_dot", cfg_dot) || cfg_dot.empty()) {
            reason = "cff_recover_cfg cfg_dot missing";
            return false;
        }
        if (cfg_dot.find("->") == std::string::npos) {
            reason = "cff_recover_cfg cfg_dot lacks edge syntax";
            return false;
        }
        if (!payload_string_field(ir.data, "pseudocode", pseudocode) || pseudocode.empty()) {
            reason = "cff_recover_cfg pseudocode missing";
            return false;
        }
        uint64_t decoded = 0;
        uint64_t serialized = 0;
        if (!payload_u64_field(ir.data, "instruction_count_total_decoded", decoded) || decoded == 0 ||
            !payload_u64_field(ir.data, "serialized_instruction_count", serialized) || serialized == 0) {
            reason = "cff_recover_cfg decoded/serialized instruction counts missing";
            return false;
        }
        return true;
    }

    bool drv_find_dispatch_table_structural_json_proof(const invoke_result_t& ir, std::string& reason) {
        uint64_t driver_entry_va = 0;
        uint64_t dispatch_table_va = 0;
        uint64_t accepted_assignment_count = 0;
        size_t assignments = 0;
        std::string dispatch_table_rel;
        if (!payload_u64_or_string_field(ir.data, "driver_entry_va", driver_entry_va) || driver_entry_va == 0) {
            reason = "driver_entry_va missing_or_zero";
            return false;
        }
        if (!payload_u64_field(ir.data, "dispatch_table_va", dispatch_table_va) || dispatch_table_va == 0)
            payload_string_field(ir.data, "dispatch_table_va", dispatch_table_rel);
        if (dispatch_table_va == 0 && dispatch_table_rel.find("driver_object+") == std::string::npos) {
            reason = "dispatch_table_va missing_or_invalid";
            return false;
        }
        if (!payload_u64_field(ir.data, "accepted_assignment_count", accepted_assignment_count) || accepted_assignment_count == 0) {
            reason = "accepted_assignment_count missing_or_zero";
            return false;
        }
        if (!payload_array_count(ir.data, "assignments", assignments) || assignments == 0) {
            reason = "assignments missing_or_empty";
            return false;
        }
        return true;
    }

    bool drv_hook_fail_closed_base_json_proof(const invoke_result_t& ir, bool require_mutation_none, std::string& reason) {
        bool fail_closed_state_only = false;
        if (!payload_bool_field(ir.data, "fail_closed_state_only", fail_closed_state_only) || !fail_closed_state_only) {
            reason = "drv_hook_manage fail_closed_state_only=true missing";
            return false;
        }
        if (!payload_string_field_equals_lc(ir.data, "backend", "fail_closed_state_only")) {
            reason = "drv_hook_manage backend is not fail_closed_state_only";
            return false;
        }
        if (!payload_bool_field_is_false(ir.data, "raw_dispatch_patching_allowed")) {
            reason = "drv_hook_manage raw_dispatch_patching_allowed=false missing";
            return false;
        }
        if (!payload_bool_field_is_false(ir.data, "safe_backend_available")) {
            reason = "drv_hook_manage safe_backend_available=false missing";
            return false;
        }
        if (!payload_string_field_equals_lc(ir.data, "security_contract", "fail_closed_no_kernel_dispatch_mutation")) {
            reason = "drv_hook_manage security_contract mismatch";
            return false;
        }
        if (require_mutation_none) {
            std::string mutation;
            if (!payload_string_field(ir.data, "mutation", mutation) || lower_copy(mutation) != "none") {
                reason = "drv_hook_manage mutation=none missing";
                return false;
            }
        }
        return true;
    }

