    bool driver_kernel_callbacks_structural_proof(const invoke_result_t& ir, std::string& reason) {
        if (!ir.data.is_object()) {
            reason = "kernel callback payload is not an object";
            return false;
        }
        std::string ntos_base;
        uint64_t ntos_size = 0;
        if (!payload_string_field(ir.data, "ntoskrnl_base", ntos_base) || ntos_base.empty() ||
            !payload_u64_field(ir.data, "ntoskrnl_size", ntos_size) || ntos_size == 0) {
            reason = "kernel callback ntoskrnl metadata missing";
            return false;
        }
        const auto it = ir.data.find("callback_types");
        if (it == ir.data.end() || !it->is_array() || it->empty()) {
            reason = "kernel callback_types missing or empty";
            return false;
        }
        size_t structural_types = 0;
        for (const auto& item : *it) {
            if (!item.is_object()) {
                reason = "kernel callback type entry is not an object";
                return false;
            }
            std::string type;
            std::string registration_function;
            if (!payload_string_field(item, "type", type) || type.empty() ||
                !payload_string_field(item, "registration_function", registration_function) || registration_function.empty()) {
                reason = "kernel callback type metadata missing";
                return false;
            }
            const auto arrays_it = item.find("arrays");
            if (arrays_it == item.end() || !arrays_it->is_array()) {
                reason = "kernel callback arrays field missing";
                return false;
            }
            for (const auto& ref : *arrays_it) {
                if (!ref.is_object()) {
                    reason = "kernel callback array ref is not an object";
                    return false;
                }
                std::string array_address;
                uint64_t count = 0;
                size_t callbacks = 0;
                if (!payload_string_field(ref, "array_address", array_address) || array_address.empty() ||
                    !payload_u64_field(ref, "count", count) ||
                    !payload_array_count(ref, "callbacks", callbacks) ||
                    count != callbacks) {
                    reason = "kernel callback array ref structural fields invalid";
                    return false;
                }
            }
            ++structural_types;
        }
        if (structural_types == 0) {
            reason = "kernel callback structural type count is zero";
            return false;
        }
        return true;
    }

    bool driver_kernel_callbacks_live_enumeration_proof(const invoke_result_t& ir, std::string& reason) {
        if (!driver_kernel_callbacks_structural_proof(ir, reason))
            return false;
        uint64_t callbacks_observed = 0;
        payload_u64_field(ir.data, "callbacks_observed", callbacks_observed);
        payload_u64_field(ir.data, "callback_count", callbacks_observed);
        std::size_t callback_entries = 0;
        std::size_t array_refs = 0;
        const auto it = ir.data.find("callback_types");
        if (it != ir.data.end() && it->is_array()) {
            for (const auto& item : *it) {
                const auto arrays_it = item.find("arrays");
                if (arrays_it == item.end() || !arrays_it->is_array())
                    continue;
                for (const auto& ref : *arrays_it) {
                    ++array_refs;
                    std::size_t callbacks = 0;
                    if (payload_array_count(ref, "callbacks", callbacks))
                        callback_entries += callbacks;
                }
            }
        }
        if (callbacks_observed > 0 || callback_entries > 0) {
            reason = "kernel callback live enumeration callbacks_observed=" +
                std::to_string(static_cast<unsigned long long>(callbacks_observed)) +
                " callback_entries=" + std::to_string(callback_entries);
            return true;
        }
        bool zero_is_clean_state = false;
        bool enumeration_ran = false;
        uint64_t callback_array_refs_found = 0;
        uint64_t callback_type_exports_resolved = 0;
        payload_bool_field(ir.data, "zero_is_clean_state", zero_is_clean_state);
        payload_bool_field(ir.data, "enumeration_ran", enumeration_ran);
        payload_u64_field(ir.data, "callback_array_refs_found", callback_array_refs_found);
        payload_u64_field(ir.data, "callback_type_exports_resolved", callback_type_exports_resolved);
        if (zero_is_clean_state &&
            (enumeration_ran || callback_array_refs_found != 0 || array_refs != 0) &&
            (callback_type_exports_resolved != 0 || array_refs != 0)) {
            reason = "kernel callback clean zero enumeration accepted callbacks_observed=0 callback_entries=0 zero_is_clean_state=1 enumeration_ran=" +
                std::to_string(enumeration_ran ? 1 : 0) +
                " callback_array_refs_found=" + std::to_string(static_cast<unsigned long long>(callback_array_refs_found)) +
                " callback_type_exports_resolved=" + std::to_string(static_cast<unsigned long long>(callback_type_exports_resolved)) +
                " array_refs=" + std::to_string(array_refs);
            return true;
        }
        reason = "kernel callback structural metadata only callbacks_observed=0 callback_entries=0 zero_is_clean_state=" +
            std::to_string(zero_is_clean_state ? 1 : 0) +
            " enumeration_ran=" + std::to_string(enumeration_ran ? 1 : 0) +
            " callback_array_refs_found=" + std::to_string(static_cast<unsigned long long>(callback_array_refs_found)) +
            " callback_type_exports_resolved=" + std::to_string(static_cast<unsigned long long>(callback_type_exports_resolved)) +
            " array_refs=" + std::to_string(array_refs);
        return false;
    }

    bool browser_lifecycle_privacy_contract_json_proof(const invoke_result_t& ir, std::string& reason) {
        bool privacy_verified = false;
        bool browser_open = false;
        bool page_verified = false;
        bool cleanup = false;
        payload_bool_field(ir.data, "privacy_verified", privacy_verified);
        payload_bool_field(ir.data, "browser_open", browser_open);
        payload_bool_field(ir.data, "page_verified", page_verified);
        const bool has_cleanup = payload_bool_field(ir.data, "cleanup", cleanup);
        bool webrtc_blocked = false;
        bool leak_detected = true;
        uint64_t ice_candidate_count = 0;
        const bool has_webrtc = payload_bool_field(ir.data, "webrtc_blocked", webrtc_blocked);
        const bool has_leak = payload_bool_field(ir.data, "ice_candidate_leak_detected", leak_detected);
        const bool has_ice_count = payload_u64_field(ir.data, "ice_candidate_count", ice_candidate_count);
        if (!privacy_verified || !browser_open || !page_verified || (has_cleanup && cleanup)) {
            reason = "browser_lifecycle privacy contract missing privacy_verified/browser_open/page_verified or reported cleanup";
            return false;
        }
        if ((has_webrtc && !webrtc_blocked) || (has_leak && leak_detected)) {
            reason = "browser_lifecycle privacy contract reported WebRTC leak state";
            return false;
        }
        if (has_ice_count && ice_candidate_count != 0) {
            reason = "browser_lifecycle privacy contract reported nonzero ICE candidates";
            return false;
        }
        reason = std::string("browser_lifecycle privacy contract privacy_verified=1 browser_open=1 page_verified=1 webrtc_blocked=") +
            std::to_string((has_webrtc && webrtc_blocked) ? 1 : 0) +
            " ice_candidate_count=" + (has_ice_count ? std::to_string(static_cast<unsigned long long>(ice_candidate_count)) : std::string("<missing>"));
        return true;
    }

