    std::string normalize_payload_key(std::string key) {
        key = lower_copy(std::move(key));
        for (char& c : key) {
            if (c == '-' || c == ' ' || c == '.')
                c = '_';
        }
        return key;
    }

    bool zero_sensitive_array_key(const std::string& key) {
        static const std::set<std::string> exact = {
            "results", "captures", "candidates", "breakpoints", "decryptors", "exports",
            "symbols", "pages", "threads", "modules", "handles", "functions",
            "packets", "reads", "matches", "scripts", "cookies", "sessions",
            "detected_packets", "scanned_modules"
        };
        return exact.find(key) != exact.end();
    }

    bool zero_sensitive_count_key(const std::string& key) {
        static const std::set<std::string> exact = {
            "count", "result_count", "results_count", "capture_count", "captures_count",
            "candidate_count", "candidates_count", "breakpoint_count", "breakpoints_count",
            "decryptor_count", "decryptors_count", "export_count", "exports_count",
            "symbol_count", "symbols_count", "page_count", "pages_count", "thread_count",
            "threads_count", "module_count", "modules_count", "handle_count", "handles_count",
            "line_count", "total_reads", "executions_per_second", "packet_count",
            "packets_count", "function_count", "functions_count", "total_results",
            "total_captures", "total_candidates", "total_breakpoints", "total_decryptors",
            "total_exports", "total_symbols", "total_pages", "total_threads",
            "total_modules", "total_handles", "total_functions", "total_packets",
            "decrypted_packets", "decoded_packets", "matched_packets", "total_cookies",
            "ice_candidate_count", "icecandidatecount", "access_count", "scripts_searched",
            "scripts_count", "script_count", "scripts_with_matches", "total_matches",
            "returned_matches", "match_count", "matches_count", "cookie_jar_count",
            "network_set_cookie_count", "js_cookie_log_count", "change_count",
            "field_count", "recorded_packet_count", "attempted_or_sent",
            "session_count", "capture_event_count", "source_size"
        };
        return exact.find(key) != exact.end();
    }

    bool json_zeroish_scalar(const mcp_standalone::json& value) {
        if (value.is_number_unsigned())
            return value.get<uint64_t>() == 0;
        if (value.is_number_integer())
            return value.get<int64_t>() == 0;
        if (value.is_number_float())
            return value.get<double>() == 0.0;
        if (value.is_string()) {
            const std::string s = lower_copy(value.get<std::string>());
            return s == "0" || s == "0.0";
        }
        return false;
    }

    bool scan_zero_output_payload(const mcp_standalone::json& value,
                                  const std::string& path,
                                  const std::string& key,
                                  std::string& reason) {
        const std::string normalized_key = normalize_payload_key(key);
        if (path.empty() && value.is_null()) {
            reason = "top_level_null";
            return true;
        }
        if (value.is_object()) {
            if (path.empty() && value.empty()) {
                reason = "top_level_object_empty";
                return true;
            }
            for (auto it = value.begin(); it != value.end(); ++it) {
                const std::string child_path = path.empty() ? it.key() : path + "." + it.key();
                const std::string child_key = normalize_payload_key(it.key());
                if (it->is_array() && it->empty() && zero_sensitive_array_key(child_key)) {
                    reason = child_path + "=[]";
                    return true;
                }
                if (!it->is_array() && !it->is_object() && zero_sensitive_count_key(child_key) && json_zeroish_scalar(*it)) {
                    reason = child_path + "=0";
                    return true;
                }
                if (scan_zero_output_payload(*it, child_path, it.key(), reason))
                    return true;
            }
            return false;
        }
        if (value.is_array()) {
            if (value.empty() && (path.empty() || zero_sensitive_array_key(normalized_key))) {
                reason = path.empty() ? "top_level_array_empty" : path + "=[]";
                return true;
            }
            for (size_t i = 0; i < value.size(); ++i) {
                std::ostringstream child_path;
                child_path << (path.empty() ? "$" : path) << "[" << i << "]";
                if (scan_zero_output_payload(value[i], child_path.str(), key, reason))
                    return true;
            }
            return false;
        }
        if (!path.empty() && zero_sensitive_count_key(normalized_key) && json_zeroish_scalar(value)) {
            reason = path + "=0";
            return true;
        }
        return false;
    }

    bool payload_truthy_any(const mcp_standalone::json& value, std::initializer_list<const char*> keys) {
        for (const char* key : keys) {
            if (const auto* found = find_payload_key_recursive(value, key)) {
                if (found->is_boolean() && found->get<bool>())
                    return true;
                if (found->is_number_unsigned() && found->get<uint64_t>() != 0)
                    return true;
                if (found->is_number_integer() && found->get<int64_t>() > 0)
                    return true;
                if (found->is_string() && !found->get<std::string>().empty())
                    return true;
            }
        }
        return false;
    }

    bool args_truthy_any(const mcp_standalone::json* args, std::initializer_list<const char*> keys) {
        if (!args || !args->is_object())
            return false;
        for (const char* key : keys) {
            auto it = args->find(key);
            if (it != args->end()) {
                if (it->is_boolean() && it->get<bool>())
                    return true;
                if (it->is_string() && !it->get<std::string>().empty())
                    return true;
                if (it->is_number())
                    return true;
            }
        }
        return false;
    }

    bool action_is_cleanup_semantic(const std::string& action_lc) {
        static const std::set<std::string> cleanup = {
            "cleanup", "clear", "clear_frames", "clear_issues", "clear_rules", "close",
            "close_browser", "close_page", "delete", "delete_file", "remove", "remove_chain",
            "remove_rule", "remove_slot", "reset", "stop", "stop_capture", "stop_keylog",
            "unhook", "unhook_all", "uninstall", "cancel"
        };
        return cleanup.find(action_lc) != cleanup.end();
    }

    bool label_is_negative_semantic(const std::string& label_lc) {
        return label_lc.find("invalid") != std::string::npos ||
               label_lc.find("missing") != std::string::npos ||
               label_lc.find("not_found") != std::string::npos ||
               label_lc.find("not found") != std::string::npos ||
               label_lc.find("unknown") != std::string::npos ||
               label_lc.find("rejected") != std::string::npos ||
               label_lc.find("required") != std::string::npos;
    }

    bool text_has_expected_empty_proof(const invoke_result_t& ir) {
        const std::string text = lower_copy(ir.text + " " + ir.exception_msg);
        static const char* markers[] = {
            "success", "ok", "removed", "cleared", "closed", "stopped", "reset",
            "unhooked", "uninstalled", "deleted", "cancelled", "canceled", "validated",
            "guard", "rejected", "expected", "no-op", "noop"
        };
        for (const char* marker : markers) {
            if (text.find(marker) != std::string::npos)
                return true;
        }
        return false;
    }

    bool harness_json_material(const mcp_standalone::json& value) {
        if (value.is_object() || value.is_array())
            return !value.empty();
        if (value.is_string())
            return !value.get<std::string>().empty();
        if (value.is_boolean())
            return value.get<bool>();
        if (value.is_number_unsigned())
            return value.get<uint64_t>() != 0;
        if (value.is_number_integer())
            return value.get<int64_t>() != 0;
        if (value.is_number_float())
            return value.get<double>() != 0.0;
        return false;
    }

    bool payload_material_key(const mcp_standalone::json& data, const char* key) {
        const auto* found = find_payload_key_recursive(data, key);
        return found && harness_json_material(*found);
    }

    bool payload_nonempty_object_or_array_key(const mcp_standalone::json& data, const char* key, size_t* count_out = nullptr) {
        const auto* found = find_payload_key_recursive(data, key);
        if (!found)
            return false;
        if (found->is_array()) {
            if (count_out)
                *count_out = found->size();
            return !found->empty();
        }
        if (found->is_object()) {
            if (count_out)
                *count_out = found->size();
            return !found->empty();
        }
        return false;
    }

    bool explicit_webrtc_privacy_probe_args(const mcp_standalone::json* args) {
        if (!args || !args->is_object())
            return false;
        std::string expression;
        if (!payload_string_field(*args, "expression", expression))
            return false;
        const std::string expr = lower_copy(expression);
        return expr.find("rtcpeerconnection") != std::string::npos ||
            expr.find("mozrtcpeerconnection") != std::string::npos ||
            expr.find("icecandidate") != std::string::npos ||
            expr.find("ice_candidate") != std::string::npos ||
            expr.find("webrtc") != std::string::npos;
    }

    bool browser_or_script_payload_has_action_proof(const std::string& tool_lc,
                                                    const std::string& action_lc,
                                                    const mcp_standalone::json& data,
                                                    const mcp_standalone::json* args,
                                                    std::string& proof) {
        proof.clear();
        if (tool_lc == "scripts" && (action_lc.empty() || action_lc == "list")) {
            size_t top_level = data.is_array() ? data.size() : 0;
            size_t nested = 0;
            payload_array_count(data, "scripts", nested);
            std::string raw_text;
            bool raw_marker = false;
            const size_t raw_entries = payload_string_field(data, "raw_text", raw_text) ?
                script_entries_in_raw_text(raw_text, std::string(), raw_marker) : 0;
            const size_t count = (std::max)(top_level, (std::max)(nested, raw_entries));
            if (count == 0)
                return false;
            std::string page_id;
            std::string active_page_id;
            payload_string_field(data, "page_id", page_id);
            payload_string_field(data, "active_page_id", active_page_id);
            proof = "scripts list real enumeration count=" + std::to_string(count) +
                " top_level=" + std::to_string(top_level) +
                " nested=" + std::to_string(nested) +
                " raw_entries=" + std::to_string(raw_entries) +
                " page_id=" + compact_text(page_id.empty() ? active_page_id : page_id, 180);
            return true;
        }
        if (tool_lc == "browser_lifecycle") {
            if (action_lc == "new" || action_lc == "new_page" || action_lc == "list" ||
                action_lc == "list_pages" || action_lc == "select" || action_lc == "select_page") {
                std::string id;
                size_t pages = 0;
                uint64_t page_count = 0;
                if (payload_string_field(data, "page_id", id) ||
                    payload_string_field(data, "active_page_id", id) ||
                    payload_array_count(data, "pages", pages) ||
                    payload_u64_field(data, "page_count", page_count)) {
                    proof = "browser_lifecycle page action proof page_id=" + compact_text(id, 180) +
                        " pages=" + std::to_string(pages) +
                        " page_count=" + std::to_string(static_cast<unsigned long long>(page_count));
                    return !id.empty() || pages > 0 || page_count > 0;
                }
            }
            return false;
        }
        if (tool_lc == "browser_navigation") {
            std::string url;
            if ((payload_string_field(data, "url", url) ||
                 payload_string_field(data, "final_url", url) ||
                 payload_string_field(data, "current_url", url) ||
                 payload_string_field(data, "href", url)) &&
                !url.empty() && lower_copy(url) != "about:blank") {
                proof = "browser_navigation url=" + compact_text(url, 240);
                return true;
            }
            bool completed = false;
            if ((payload_bool_field(data, "found", completed) ||
                 payload_bool_field(data, "navigated", completed) ||
                 payload_bool_field(data, "loaded", completed)) && completed) {
                proof = "browser_navigation completion boolean";
                return true;
            }
            return false;
        }
        if (tool_lc == "browser_interaction") {
            if (action_lc == "evaluate" && explicit_webrtc_privacy_probe_args(args))
                return false;
            bool completed = false;
            if ((payload_bool_field(data, "clicked", completed) ||
                 payload_bool_field(data, "typed", completed) ||
                 payload_bool_field(data, "submitted", completed) ||
                 payload_bool_field(data, "evaluated", completed) ||
                 payload_bool_field(data, "element_found", completed) ||
                 payload_bool_field(data, "mutation_observed", completed)) && completed) {
                proof = "browser_interaction completion boolean";
                return true;
            }
            if (payload_material_key(data, "result") ||
                payload_material_key(data, "value") ||
                payload_material_key(data, "selector") ||
                payload_material_key(data, "text")) {
                proof = "browser_interaction material result/value payload";
                return true;
            }
            return false;
        }
        return false;
    }

    bool vm_register_or_dispatch_payload_proves_execution(const std::string& tool_lc,
                                                          const mcp_standalone::json& data,
                                                          const std::string& zero_reason,
                                                          std::string& proof) {
        proof.clear();
        bool timed_out = false;
        if (payload_bool_field(data, "timed_out", timed_out) && timed_out)
            return false;
        if (tool_lc == "vm_trace_bytecode") {
            uint64_t emulated = 0;
            uint64_t memory_reads = 0;
            uint64_t dispatch_windows = 0;
            size_t steps = 0;
            const bool has_emulated = payload_u64_field(data, "emulated_instructions", emulated);
            const bool has_steps = payload_array_count(data, "steps", steps);
            payload_u64_field(data, "memory_reads_total", memory_reads);
            payload_u64_field(data, "dispatch_windows", dispatch_windows);
            const bool register_or_effective =
                payload_material_key(data, "effective_operations") ||
                payload_material_key(data, "register_deltas") ||
                payload_material_key(data, "register_writes");
            if (has_emulated && emulated > 0 && has_steps && steps > 0 &&
                (memory_reads > 0 || dispatch_windows > 0 || register_or_effective)) {
                proof = "vm_trace_bytecode execution proof emulated=" + std::to_string(static_cast<unsigned long long>(emulated)) +
                    " steps=" + std::to_string(steps) +
                    " memory_reads_total=" + std::to_string(static_cast<unsigned long long>(memory_reads)) +
                    " dispatch_windows=" + std::to_string(static_cast<unsigned long long>(dispatch_windows)) +
                    " register_or_effective=" + std::to_string(register_or_effective ? 1 : 0) +
                    " zero_reason=" + zero_reason;
                return true;
            }
            return false;
        }
        if (tool_lc == "vm_classify_handler") {
            std::string semantic;
            double confidence = 0.0;
            const bool has_semantic = payload_string_field(data, "semantic", semantic);
            const bool has_confidence = payload_number_positive_field(data, "confidence", confidence);
            if (has_semantic && !semantic.empty() && lower_copy(semantic) != "unknown" && has_confidence &&
                (payload_material_key(data, "register_deltas") ||
                 payload_material_key(data, "differential_inputs") ||
                 payload_material_key(data, "operand_roles") ||
                 payload_material_key(data, "semantic"))) {
                proof = "vm_classify_handler register-only semantic=" + compact_text(semantic, 80) +
                    " confidence=" + std::to_string(confidence) +
                    " zero_reason=" + zero_reason;
                return true;
            }
            return false;
        }
        if (tool_lc == "vm_build_opcode_map") {
            uint64_t handler_count = 0;
            uint64_t classified_count = 0;
            const bool has_handler_count =
                payload_u64_field(data, "handler_count_read", handler_count) ||
                payload_u64_field(data, "handler_count", handler_count);
            const bool has_classified = payload_u64_field(data, "classified_count", classified_count);
            size_t opcode_map_count = 0;
            if (has_handler_count && handler_count > 0 && has_classified && classified_count > 0 &&
                payload_nonempty_object_or_array_key(data, "opcode_map", &opcode_map_count)) {
                proof = "vm_build_opcode_map handler proof handlers=" + std::to_string(static_cast<unsigned long long>(handler_count)) +
                    " classified=" + std::to_string(static_cast<unsigned long long>(classified_count)) +
                    " opcode_map_entries=" + std::to_string(opcode_map_count) +
                    " zero_reason=" + zero_reason;
                return true;
            }
            return false;
        }
        return false;
    }

    bool pack_detect_no_import_fixture_proof(const mcp_standalone::json& data,
                                             const std::string& zero_reason,
                                             std::string& proof) {
        proof.clear();
        if (zero_reason.find("import_summary.function_count=0") == std::string::npos &&
            zero_reason.find("function_count=0") == std::string::npos &&
            zero_reason.find("functions=[]") == std::string::npos)
            return false;
        bool minimal_iat = false;
        if (!payload_bool_field(data, "minimal_iat", minimal_iat) || !minimal_iat)
            return false;
        std::string minimal_reason;
        if (!payload_string_field(data, "minimal_iat_reason", minimal_reason) ||
            lower_copy(minimal_reason) != "no_import_directory")
            return false;
        const auto* import_summary = find_payload_key_recursive(data, "import_summary");
        if (!import_summary || !import_summary->is_object())
            return false;
        auto dir_it = import_summary->find("directory_present");
        if (dir_it == import_summary->end() || !dir_it->is_boolean() || dir_it->get<bool>())
            return false;
        size_t entropy_entries = 0;
        if (!payload_array_count(data, "entropy_map", entropy_entries) || entropy_entries == 0)
            return false;
        bool likely = false;
        const bool has_likely = payload_bool_field(data, "likely_packed", likely);
        if (!has_likely)
            return false;
        std::string module_base;
        payload_string_field(data, "module_base", module_base);
        proof = "pack_detect synthetic no-import PE proof likely_packed=" +
            std::to_string(likely ? 1 : 0) +
            " entropy_entries=" + std::to_string(entropy_entries) +
            " minimal_iat_reason=no_import_directory module_base=" + compact_text(module_base, 80) +
            " zero_reason=" + zero_reason;
        return true;
    }

    bool payload_webrtc_zero_candidate_expected(const mcp_standalone::json& data, std::string& reason) {
        bool privacy_verified = false;
        bool webrtc_blocked = false;
        bool leak_detected = true;
        bool webrtc_blocked_camel = false;
        bool ice_leak_camel = true;
        std::string rtc_peer_connection;
        std::string moz_rtc_peer_connection;
        std::string rtc_type;
        std::string moz_rtc_type;
        const bool has_privacy = payload_bool_field(data, "privacy_verified", privacy_verified);
        const bool has_webrtc = payload_bool_field(data, "webrtc_blocked", webrtc_blocked);
        const bool has_leak = payload_bool_field(data, "ice_candidate_leak_detected", leak_detected);
        const bool has_webrtc_camel = payload_bool_field(data, "webrtcBlocked", webrtc_blocked_camel);
        const bool has_ice_leak_camel = payload_bool_field(data, "iceLeak", ice_leak_camel);
        payload_string_field(data, "rtc_peer_connection", rtc_peer_connection);
        payload_string_field(data, "moz_rtc_peer_connection", moz_rtc_peer_connection);
        payload_string_field(data, "rtcType", rtc_type);
        payload_string_field(data, "mozRtcType", moz_rtc_type);
        const bool snake_absent =
            lower_copy(rtc_peer_connection) == "undefined" &&
            lower_copy(moz_rtc_peer_connection) == "undefined";
        const bool camel_absent =
            lower_copy(rtc_type) == "undefined" &&
            lower_copy(moz_rtc_type) == "undefined";
        const bool blocked = (has_webrtc && webrtc_blocked) || (has_webrtc_camel && webrtc_blocked_camel);
        const bool no_leak = (has_leak && !leak_detected) || (has_ice_leak_camel && !ice_leak_camel);
        if (((has_privacy && privacy_verified) || blocked) && blocked && (snake_absent || camel_absent) && no_leak) {
            reason = "privacy_webrtc_block_zero_candidate_expected constructors_absent=1 leak=0";
            return true;
        }
        reason = "privacy_webrtc_zero_candidate_unproven privacy_verified=" + std::to_string(privacy_verified ? 1 : 0) +
            " blocked=" + std::to_string(blocked ? 1 : 0) +
            " constructors_absent=" + std::to_string((snake_absent || camel_absent) ? 1 : 0) +
            " leak_free=" + std::to_string(no_leak ? 1 : 0);
        return false;
    }

    bool json_direct_bool_field(const mcp_standalone::json& value, const char* key, bool& out) {
        if (!key || !value.is_object())
            return false;
        auto it = value.find(key);
        if (it == value.end() || !it->is_boolean())
            return false;
        out = it->get<bool>();
        return true;
    }

    bool json_direct_u64_field(const mcp_standalone::json& value, const char* key, uint64_t& out) {
        if (!key || !value.is_object())
            return false;
        auto it = value.find(key);
        if (it == value.end())
            return false;
        if (it->is_number_unsigned()) {
            out = it->get<uint64_t>();
            return true;
        }
        if (it->is_number_integer()) {
            const auto v = it->get<int64_t>();
            if (v >= 0) {
                out = static_cast<uint64_t>(v);
                return true;
            }
        }
        return false;
    }

    bool json_direct_string_field(const mcp_standalone::json& value, const char* key, std::string& out) {
        if (!key || !value.is_object())
            return false;
        auto it = value.find(key);
        if (it == value.end() || !it->is_string())
            return false;
        out = it->get<std::string>();
        return true;
    }

    bool json_direct_array_empty(const mcp_standalone::json& value, const char* key, bool& present) {
        present = false;
        if (!key || !value.is_object())
            return false;
        auto it = value.find(key);
        if (it == value.end() || !it->is_array())
            return false;
        present = true;
        return it->empty();
    }

    bool compare_env_requested_properties_present(const mcp_standalone::json& data,
                                                  const mcp_standalone::json* args,
                                                  std::string& reason) {
        reason.clear();
        if (!args || !args->is_object())
            return true;
        auto prop_it = args->find("properties");
        if (prop_it == args->end() || !prop_it->is_array() || prop_it->empty())
            return true;
        if (!data.is_object()) {
            reason = "compare_env_payload_not_object";
            return false;
        }
        auto custom_it = data.find("custom");
        if (custom_it == data.end() || !custom_it->is_object()) {
            reason = "compare_env_custom_missing";
            return false;
        }
        for (const auto& prop : *prop_it) {
            if (!prop.is_string())
                continue;
            const std::string name = prop.get<std::string>();
            auto value_it = custom_it->find(name);
            if (value_it == custom_it->end() || !value_it->is_object()) {
                reason = "compare_env_custom_property_missing=" + name;
                return false;
            }
            if (value_it->contains("error") && !value_it->contains("value")) {
                reason = "compare_env_custom_property_error=" + name;
                return false;
            }
        }
        return true;
    }

    bool compare_env_functional_json_proof(const mcp_standalone::json& data,
                                           const mcp_standalone::json* args,
                                           std::string& proof) {
        proof.clear();
        if (!data.is_object())
            return false;
        std::string instrumentation_status;
        if (!json_direct_string_field(data, "instrumentation_status", instrumentation_status) ||
            lower_copy(instrumentation_status) != "complete")
            return false;
        bool partial = true;
        if (json_direct_bool_field(data, "partial_result", partial) && partial)
            return false;
        if (data.contains("timeout_status"))
            return false;
        bool timeouts_present = false;
        bool failures_present = false;
        if (!json_direct_array_empty(data, "chunk_timeouts", timeouts_present) || !timeouts_present)
            return false;
        if (!json_direct_array_empty(data, "chunk_failures", failures_present) || !failures_present)
            return false;
        uint64_t result_property_count = 0;
        if (!json_direct_u64_field(data, "result_property_count", result_property_count) || result_property_count == 0)
            return false;
        uint64_t requested_property_count = 0;
        json_direct_u64_field(data, "requested_property_count", requested_property_count);
        if (args && args->is_object()) {
            auto prop_it = args->find("properties");
            if (prop_it != args->end() && prop_it->is_array() && requested_property_count < prop_it->size())
                return false;
        }
        std::string custom_reason;
        if (!compare_env_requested_properties_present(data, args, custom_reason))
            return false;
        std::string privacy_reason;
        if (!payload_webrtc_zero_candidate_expected(data, privacy_reason))
            return false;
        proof = "compare_env functional result_property_count=" + std::to_string(static_cast<unsigned long long>(result_property_count)) +
            " requested_property_count=" + std::to_string(static_cast<unsigned long long>(requested_property_count)) +
            " chunk_failures=0 chunk_timeouts=0 " + privacy_reason;
        return true;
    }

    bool check_environment_functional_json_proof(const mcp_standalone::json& data, std::string& proof) {
        proof.clear();
        if (!data.is_object())
            return false;
        std::string status;
        bool overall_ok = false;
        if (!json_direct_string_field(data, "status", status) || lower_copy(status) != "ok")
            return false;
        if (!json_direct_bool_field(data, "overall_ok", overall_ok) || !overall_ok)
            return false;
        if (data.contains("timeout_status"))
            return false;
        auto mcp_it = data.find("mcp");
        bool version_ok = false;
        if (mcp_it == data.end() || !mcp_it->is_object() || !json_direct_bool_field(*mcp_it, "version_ok", version_ok) || !version_ok)
            return false;
        auto deps_it = data.find("deps");
        if (deps_it == data.end() || !deps_it->is_object() || deps_it->empty())
            return false;
        size_t deps_ok = 0;
        for (auto it = deps_it->begin(); it != deps_it->end(); ++it) {
            if (!it->is_object())
                return false;
            bool installed = false;
            bool ok = false;
            if (!json_direct_bool_field(*it, "installed", installed) || !installed ||
                !json_direct_bool_field(*it, "ok", ok) || !ok)
                return false;
            ++deps_ok;
        }
        auto browser_it = data.find("browser");
        bool browser_running = false;
        uint64_t page_count = 0;
        if (browser_it == data.end() || !browser_it->is_object() ||
            !json_direct_bool_field(*browser_it, "running", browser_running) || !browser_running ||
            !json_direct_u64_field(*browser_it, "page_count", page_count) || page_count == 0)
            return false;
        std::string privacy_reason;
        if (!payload_webrtc_zero_candidate_expected(data, privacy_reason))
            return false;
        proof = "check_environment functional overall_ok=1 status=ok version_ok=1 deps_ok=" +
            std::to_string(static_cast<unsigned long long>(deps_ok)) +
            " browser_running=1 page_count=" + std::to_string(static_cast<unsigned long long>(page_count)) +
            " " + privacy_reason;
        return true;
    }

    bool protocol_detect_action(const std::string& tool_lc, const std::string& action_lc) {
        return (tool_lc == "quic_manage" && action_lc == "detect_connections") ||
            (tool_lc == "dtls_manage" && action_lc == "detect_sessions");
    }

    bool protocol_parser_state_contract_payload(const std::string& tool_lc,
                                                const std::string& action_lc,
                                                const mcp_standalone::json& data,
                                                std::string& proof) {
        proof.clear();
        if (!protocol_detect_action(tool_lc, action_lc) || !data.is_object())
            return false;
        bool parser_only = false;
        bool state_contract_only = false;
        bool functional_evidence = true;
        bool capture_evidence = true;
        bool target_pid_correlated = true;
        bool tuple_correlated = true;
        bool payload_hash_correlated = true;
        bool nonce_correlated = true;
        uint64_t parser_count = 0;
        uint64_t functional_count = 1;
        uint64_t count = 1;
        uint64_t capture_delta = 1;
        size_t parser_items = 0;
        const char* parser_array = tool_lc == "quic_manage" ? "parser_connections" : "parser_sessions";
        const bool ok =
            payload_bool_field(data, "parser_only", parser_only) && parser_only &&
            payload_bool_field(data, "state_contract_only", state_contract_only) && state_contract_only &&
            payload_bool_field(data, "functional_evidence", functional_evidence) && !functional_evidence &&
            payload_bool_field(data, "capture_evidence", capture_evidence) && !capture_evidence &&
            payload_bool_field(data, "target_pid_correlated", target_pid_correlated) && !target_pid_correlated &&
            payload_bool_field(data, "tuple_correlated", tuple_correlated) && !tuple_correlated &&
            payload_bool_field(data, "payload_hash_correlated", payload_hash_correlated) && !payload_hash_correlated &&
            payload_bool_field(data, "nonce_correlated", nonce_correlated) && !nonce_correlated &&
            payload_u64_field(data, "parser_count", parser_count) && parser_count > 0 &&
            payload_u64_field(data, "functional_count", functional_count) && functional_count == 0 &&
            payload_u64_field(data, "count", count) && count == 0 &&
            payload_u64_field(data, "capture_counter_delta", capture_delta) && capture_delta == 0 &&
            payload_array_count(data, parser_array, parser_items) && parser_items > 0;
        proof = std::string(tool_lc == "quic_manage" ? "quic" : "dtls") +
            "_parser_only_state_contract parser_count=" + std::to_string(static_cast<unsigned long long>(parser_count)) +
            " parser_items=" + std::to_string(parser_items) +
            " functional_count=" + std::to_string(static_cast<unsigned long long>(functional_count)) +
            " capture_counter_delta=" + std::to_string(static_cast<unsigned long long>(capture_delta));
        return ok;
    }

