    bool test_coverage_domains_1_8_schema(HANDLE hf,
                                      const char* tag,
                                      const char* tool_name,
                                      bool expected_read_only,
                                      std::initializer_list<test_coverage_domains_1_8_param_t> params,
                                      std::atomic<int>& passed,
                                      std::atomic<int>& failed) {
        const std::string tool = tool_name ? std::string(tool_name) : std::string();
        if (tool.empty())
            return false;
        g_invoked_tools.insert(tool);
        const auto* def = find_registered_tool(get_server(), tool.c_str());
        if (!def) {
            log_msg(hf, tag, "FAIL -- schema tool=\"%s\" not registered", tool.c_str());
            record_tool_status(tool, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return false;
        }
        if (def->read_only != expected_read_only) {
            log_msg(hf, tag, "FAIL -- schema tool=\"%s\" read_only=%d expected=%d",
                tool.c_str(), def->read_only ? 1 : 0, expected_read_only ? 1 : 0);
            record_tool_status(tool, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return false;
        }
        for (const auto& param : params) {
            bool required = false;
            if (!tool_has_param(*def, param.name, &required) || required != param.required) {
                log_msg(hf, tag, "FAIL -- schema tool=\"%s\" param=%s required=%d expected=%d",
                    tool.c_str(), param.name ? param.name : "<null>", required ? 1 : 0, param.required ? 1 : 0);
                record_tool_status(tool, mcp_tool_call_status_t::failed);
                failed.fetch_add(1);
                return false;
            }
        }
        log_msg(hf, tag, "SCHEMA-PASS -- tool=\"%s\" read_only=%d params=%zu functional_run=0",
            tool.c_str(), def->read_only ? 1 : 0, def->params.size());
        record_tool_status(tool, mcp_tool_call_status_t::schema_pass);
        passed.fetch_add(1);
        return true;
    }

    bool test_coverage_domains_1_8_case(HANDLE hf,
                                    const char* tag,
                                    const char* tool_name,
                                    const char* case_name,
                                    mcp_standalone::json args,
                                    long long timeout_ms,
                                    const test_coverage_domains_1_8_validator_t& validator,
                                    std::atomic<int>& passed,
                                    std::atomic<int>& failed,
                                    invoke_result_t* out_result = nullptr) {
        const std::string tool = tool_name ? std::string(tool_name) : std::string();
        if (tool.empty())
            return false;
        if (!args.is_object())
            args = mcp_standalone::json::object();
        g_invoked_tools.insert(tool);
        const int seq = g_mcp_tool_sequence.fetch_add(1, std::memory_order_acq_rel) + 1;
        char step[256];
        _snprintf_s(step, sizeof(step), _TRUNCATE, "mcp coverage domains 1-8 #%d: %s", seq, tool.c_str());
        set_progress_step(step);
        if (!tool_registered(get_server(), tool.c_str())) {
            log_msg(hf, tag, "FAIL -- case=%s tool=\"%s\" not registered", case_name ? case_name : "<null>", tool.c_str());
            record_tool_status(tool, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return false;
        }
        log_msg(hf, tag, "START -- case=%s tool=\"%s\" seq=%d timeout_ms=%lld args=%s",
            case_name ? case_name : "<null>", tool.c_str(), seq, timeout_ms, compact_json(args, 900).c_str());
        auto timed = invoke_tool_bounded(get_server(), tool, args, timeout_ms, hf, tag, seq);
        invoke_result_t ir = std::move(timed.result);
        if (out_result)
            *out_result = ir;
        log_mcp_result_detail("coverage_domains_1_8", seq, tool, args, ir, timed.elapsed_ms, case_name ? case_name : "");
        auto fail_case = [&](const std::string& why, mcp_tool_call_status_t status = mcp_tool_call_status_t::failed) {
            log_msg(hf, tag, "FAIL -- case=%s tool=\"%s\" seq=%d reason=%s elapsed_ms=%lld success=%d data=%s",
                case_name ? case_name : "<null>",
                tool.c_str(),
                seq,
                compact_text(why, 700).c_str(),
                timed.elapsed_ms,
                ir.success ? 1 : 0,
                compact_json(ir.data, 900).c_str());
            record_tool_status(tool, status);
            failed.fetch_add(1);
            if (g_mcp_target_pid != 0)
                restore_mcp_target(hf, tag);
            return false;
        };
        if (timed.timed_out) {
            cancel_timed_out_tool(hf, tag, tool, args);
            return fail_case("watchdog timeout", mcp_tool_call_status_t::timed_out);
        }
        if (!ir.found)
            return fail_case("tool not found during dispatch");
        std::string busy_reason;
        std::string busy_blocked_by_tool;
        std::string busy_blocked_by_seq;
        std::string busy_blocked_by_diag_id;
        if (mcp_active_session_busy_result(ir, busy_reason, busy_blocked_by_tool, busy_blocked_by_seq, busy_blocked_by_diag_id)) {
            log_msg(hf, tag, "CASCADE-BLOCKED -- case=%s tool=\"%s\" seq=%d active-session owner_tool=\"%s\" owner_seq=\"%s\" owner_diag_id=\"%s\" reason=%s elapsed_ms=%lld data=%s",
                case_name ? case_name : "<null>",
                tool.c_str(),
                seq,
                busy_blocked_by_tool.empty() ? "<unknown>" : busy_blocked_by_tool.c_str(),
                busy_blocked_by_seq.empty() ? "<unknown>" : busy_blocked_by_seq.c_str(),
                busy_blocked_by_diag_id.empty() ? "<unknown>" : busy_blocked_by_diag_id.c_str(),
                compact_text(busy_reason, 700).c_str(),
                timed.elapsed_ms,
                compact_json(ir.data, 900).c_str());
            log_mcp_call_classification(hf, tag, seq, tool, args, mcp_tool_call_status_t::cascade_blocked, ir,
                "", busy_reason);
            record_cascade_blocked_tool(hf, tag, tool.c_str(), busy_reason, busy_blocked_by_tool, busy_blocked_by_seq, busy_blocked_by_diag_id, failed);
            if (g_mcp_target_pid != 0)
                restore_mcp_target(hf, tag);
            return false;
        }
        if (ir.threw)
            return fail_case("handler threw: " + ir.exception_msg);
        std::string reason;
        if (!validator(ir, reason))
            return fail_case(reason.empty() ? "validator rejected result" : reason);
        std::string expected_empty_proof;
        if (ir.success) {
            std::string payload_failure;
            mcp_tool_call_status_t expected_empty_status = mcp_tool_call_status_t::functional_pass;
            const std::string semantic_action = semantic_action_from_args(args);
            if (tool_payload_failure_reason(tool, ir, payload_failure, semantic_action, &args, &expected_empty_proof, &expected_empty_status, hf, tag)) {
                if (is_zero_output_failure_reason(payload_failure))
                    record_mcp_zero_output_suspect(tool, payload_failure);
                if (payload_failure_is_dependency_blocked_reason(payload_failure)) {
                    record_dependency_blocked_tool(hf, tag, tool.c_str(), payload_failure, failed);
                    if (g_mcp_target_pid != 0)
                        restore_mcp_target(hf, tag);
                    return false;
                }
                return fail_case("payload semantic validation failed: " + payload_failure);
            }
            if (expected_empty_status != mcp_tool_call_status_t::functional_pass) {
                if (mcp_status_records_expected_empty_audit(expected_empty_status))
                    record_mcp_expected_empty_nonfunctional(tool, expected_empty_proof);
                log_msg(hf, tag, "%s -- case=%s tool=\"%s\" seq=%d success=1 elapsed_ms=%lld functional_run=0 expected_empty_proof=%s data=%s",
                    pass_status_prefix(expected_empty_status),
                    case_name ? case_name : "<null>",
                    tool.c_str(),
                    seq,
                    timed.elapsed_ms,
                    expected_empty_proof.empty() ? "<empty>" : compact_text(expected_empty_proof, 700).c_str(),
                    mcp_payload_summary(ir.data).c_str());
                log_mcp_call_classification(hf, tag, seq, tool, args, expected_empty_status, ir,
                    "", expected_empty_proof);
                record_tool_status(tool, expected_empty_status);
                if (g_mcp_target_pid != 0)
                    restore_mcp_target(hf, tag);
                return true;
            }
        }
        std::string classification_evidence;
        const mcp_tool_call_status_t pass_status = ir.success
            ? classify_successful_mcp_call(tool, args, ir, classification_evidence)
            : classify_expected_false_pass(tool, case_name, args);
        if (ir.success && mcp_status_is_functional(pass_status) && !expected_empty_proof.empty())
            classification_evidence = expected_empty_proof;
        log_msg(hf, tag, "%s -- case=%s tool=\"%s\" seq=%d success=%d elapsed_ms=%lld functional_run=%d data=%s",
            pass_status_prefix(pass_status),
            case_name ? case_name : "<null>",
            tool.c_str(),
            seq,
            ir.success ? 1 : 0,
            timed.elapsed_ms,
            mcp_status_is_functional(pass_status) ? 1 : 0,
            mcp_payload_summary(ir.data).c_str());
        log_mcp_call_classification(hf, tag, seq, tool, args, pass_status, ir,
            classification_evidence, ir.success ? expected_empty_proof : std::string("expected_false_pass"));
        record_tool_status(tool, pass_status);
        if (mcp_status_is_functional(pass_status))
            passed.fetch_add(1);
        if (g_mcp_target_pid != 0)
            restore_mcp_target(hf, tag);
        return true;
    }

