    bool test_coverage_domains_1_8_read_descriptor_at(std::uint32_t pid,
                                                  std::uint64_t va,
                                                  test_coverage_domains_1_8_re_descriptor_t& out,
                                                  std::string& reason) {
        std::vector<std::uint8_t> bytes;
        if (!driver_bridge::read_memory_for(pid, va, sizeof(out), bytes) || bytes.size() < sizeof(out)) {
            reason = "read_memory_for descriptor failed va=" + test_coverage_domains_1_8_hex_ptr(va) + " status=" + driver_bridge::status() + " error=" + driver_bridge::last_error();
            return false;
        }
        std::memcpy(&out, bytes.data(), sizeof(out));
        if (out.magic != 0x41494452u || out.version != 1 || out.size < 128 || out.descriptor_va == 0) {
            reason = "descriptor validation failed va=" + test_coverage_domains_1_8_hex_ptr(va) +
                " magic=" + std::to_string(out.magic) +
                " version=" + std::to_string(out.version) +
                " size=" + std::to_string(out.size) +
                " descriptor_va=" + test_coverage_domains_1_8_hex_ptr(out.descriptor_va);
            return false;
        }
        return true;
    }

    bool test_coverage_domains_1_8_find_re_descriptor(HANDLE hf,
                                                  const char* tag,
                                                  test_coverage_domains_1_8_re_descriptor_t& out,
                                                  std::string& reason) {
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        if (pid == 0) {
            reason = "no current MCP target PID";
            return false;
        }
        if (g_mcp_target_pid != 0 && driver_bridge::attached_pid() != g_mcp_target_pid && !restore_mcp_target(hf, tag)) {
            reason = "failed to restore MCP target before descriptor lookup";
            return false;
        }
        const auto modules = driver_bridge::enumerate_modules_for(pid);
        std::string first_export_error;
        for (const auto& mod : modules) {
            if (mod.base == 0)
                continue;
            std::string export_reason;
            const std::uint64_t descriptor_va = testlab_resolve_export_for_pid(pid, mod.base, mod.size, "aida_test_re_descriptor", export_reason);
            if (descriptor_va == 0) {
                const std::string module_label = mod.name.empty() ? mod.path : mod.name;
                const bool target_module = lower_copy(module_label).find("aida_test") != std::string::npos;
                if (target_module || first_export_error.empty())
                    first_export_error = "module=" + module_label +
                        " base=" + hex_u64(mod.base) +
                        " size=" + std::to_string(mod.size) +
                        " reason=" + export_reason;
                continue;
            }
            test_coverage_domains_1_8_re_descriptor_t candidate{};
            std::string read_reason;
            if (test_coverage_domains_1_8_read_descriptor_at(pid, descriptor_va, candidate, read_reason)) {
                out = candidate;
                log_msg(hf, tag, "FIXTURE -- re descriptor resolved module=%s base=0x%016llX descriptor=0x%016llX matrix=0x%016llX resource=0x%016llX struct=0x%016llX rtti_vtable=0x%016llX heap_fn=0x%016llX window=0x%016llX d3d11=0x%016llX dxgi=0x%016llX dx_static_vtable=0x%016llX dx_static_slots=%u dx_static_names=0x%016llX dx_static_addresses=0x%016llX analysis_branch=0x%016llX analysis_callgraph=0x%016llX analysis_dispatch=0x%016llX analysis_exports=%u",
                    mod.name.c_str(),
                    static_cast<unsigned long long>(mod.base),
                    static_cast<unsigned long long>(candidate.descriptor_va),
                    static_cast<unsigned long long>(candidate.matrix_buffer_va),
                    static_cast<unsigned long long>(candidate.resource_object_va),
                    static_cast<unsigned long long>(candidate.struct_array_va ? candidate.struct_array_va : candidate.struct_base_va),
                    static_cast<unsigned long long>(candidate.rtti_vtable_va),
                    static_cast<unsigned long long>(candidate.heap_burst_fn_va),
                    static_cast<unsigned long long>(candidate.window_hwnd),
                    static_cast<unsigned long long>(candidate.d3d11_module_va),
                    static_cast<unsigned long long>(candidate.dxgi_module_va),
                    static_cast<unsigned long long>(candidate.dx_static_vtable_va),
                    candidate.dx_static_slot_count,
                    static_cast<unsigned long long>(candidate.dx_static_slot_names_va),
                    static_cast<unsigned long long>(candidate.dx_static_slot_addresses_va),
                    static_cast<unsigned long long>(candidate.analysis_branch_fn_va),
                    static_cast<unsigned long long>(candidate.analysis_callgraph_fn_va),
                    static_cast<unsigned long long>(candidate.analysis_dispatch_fn_va),
                    candidate.analysis_export_count);
                return true;
            }
            if (first_export_error.empty())
                first_export_error = read_reason;
        }
        reason = modules.empty() ? "module enumeration returned no modules for target PID " + std::to_string(pid) :
            "export aida_test_re_descriptor was not resolved in target modules pid=" + std::to_string(pid) +
            " attached_pid=" + std::to_string(driver_bridge::attached_pid()) +
            " modules=" + std::to_string(modules.size());
        if (!first_export_error.empty())
            reason += "; first_export_error=" + first_export_error;
        return false;
    }

    bool test_coverage_domains_1_8_refresh_re_descriptor(HANDLE hf,
                                                     const char* tag,
                                                     test_coverage_domains_1_8_re_descriptor_t& desc) {
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        std::string reason;
        test_coverage_domains_1_8_re_descriptor_t refreshed{};
        if (pid == 0 || desc.descriptor_va == 0 || !test_coverage_domains_1_8_read_descriptor_at(pid, desc.descriptor_va, refreshed, reason)) {
            log_msg(hf, tag, "WARN -- descriptor refresh failed reason=%s", compact_text(reason, 700).c_str());
            return false;
        }
        desc = refreshed;
        return true;
    }

    mcp_standalone::json test_coverage_domains_1_8_safe_args() {
        mcp_standalone::json args = mcp_standalone::json::object();
        args["confirm_unsafe"] = true;
        args["allow_unsafe"] = true;
        args[k_test_lab_safe_fixture_flag] = true;
        return args;
    }

    bool test_coverage_domains_1_8_json_has_resolved_dx_slot(const mcp_standalone::json& obj) {
        if (!obj.is_object())
            return false;
        if (obj.contains("slot_map") && obj["slot_map"].is_object()) {
            for (auto it = obj["slot_map"].begin(); it != obj["slot_map"].end(); ++it) {
                const auto& slot = it.value();
                if (slot.is_object() && slot.contains("address") && slot["address"].is_string() && !slot["address"].get<std::string>().empty())
                    return true;
            }
        }
        if (obj.contains("apis") && obj["apis"].is_array()) {
            for (const auto& api : obj["apis"]) {
                if (test_coverage_domains_1_8_json_has_resolved_dx_slot(api))
                    return true;
            }
        }
        return false;
    }

    bool test_coverage_domains_1_8_first_array_item(const mcp_standalone::json& data, const char* key, mcp_standalone::json& out) {
        if (!data.is_object() || !key || !data.contains(key) || !data[key].is_array() || data[key].empty())
            return false;
        out = data[key][0];
        return true;
    }

    void test_coverage_domains_1_8_dx_tools(HANDLE hf,
                                        const test_coverage_domains_1_8_re_descriptor_t& desc,
                                        bool have_desc,
                                        const std::string& descriptor_reason,
                                        std::atomic<int>& passed,
                                        std::atomic<int>& failed,
                                        bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.dx";
        set_progress_step("mcp coverage domains 1-8: dx tools");
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();

        {
            const bool have_static_dx_fixture = have_desc &&
                desc.dx_static_vtable_va != 0 &&
                desc.dx_static_slot_names_va != 0 &&
                desc.dx_static_slot_addresses_va != 0 &&
                desc.dx_static_slot_count != 0;
            if (!have_static_dx_fixture) {
                log_msg(hf, tag, "FAIL -- dx_find_device_vtable static fixture descriptor missing have_desc=%d descriptor_reason=%s vtable=0x%016llX slot_names=0x%016llX slot_addresses=0x%016llX slot_count=%u",
                    have_desc ? 1 : 0,
                    descriptor_reason.empty() ? "<empty>" : compact_text(descriptor_reason, 900).c_str(),
                    static_cast<unsigned long long>(desc.dx_static_vtable_va),
                    static_cast<unsigned long long>(desc.dx_static_slot_names_va),
                    static_cast<unsigned long long>(desc.dx_static_slot_addresses_va),
                    desc.dx_static_slot_count);
                record_fixture_failed_tool("dx_find_device_vtable", failed);
            } else {
                mcp_standalone::json args;
                args["process_id"] = pid;
                args["api"] = "d3d11";
                args["fixture_vtable_va"] = test_coverage_domains_1_8_hex_ptr(desc.dx_static_vtable_va);
                args["fixture_slot_names_va"] = test_coverage_domains_1_8_hex_ptr(desc.dx_static_slot_names_va);
                args["fixture_slot_addresses_va"] = test_coverage_domains_1_8_hex_ptr(desc.dx_static_slot_addresses_va);
                args["fixture_slot_count"] = desc.dx_static_slot_count;
                args["fixture_kind"] = "static_dummy";
                test_coverage_domains_1_8_case(hf, tag, "dx_find_device_vtable", "find_device_vtable_static_fixture_resolves_target_slot", args, 6000,
                [hf, tag, desc](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "expected DX static fixture discovery success text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!test_coverage_domains_1_8_json_has_resolved_dx_slot(ir.data)) {
                        reason = "DX static fixture discovery returned no resolved target slot data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    const std::string combined = lower_copy(ir.text + " " + compact_json(ir.data, 2200));
                    if (combined.find("static_dummy") == std::string::npos &&
                        combined.find("static_fixture") == std::string::npos &&
                        combined.find("fixture_kind") == std::string::npos) {
                        reason = "DX discovery did not label static fixture evidence data=" + compact_json(ir.data, 900);
                        return false;
                    }
                    log_msg(hf, tag, "STATIC-FIXTURE-PROOF -- tool=dx_find_device_vtable fixture_kind=static_dummy vtable=0x%016llX slot_names=0x%016llX slot_addresses=0x%016llX slot_count=%u",
                        static_cast<unsigned long long>(desc.dx_static_vtable_va),
                        static_cast<unsigned long long>(desc.dx_static_slot_names_va),
                        static_cast<unsigned long long>(desc.dx_static_slot_addresses_va),
                        desc.dx_static_slot_count);
                    return true;
                }, passed, failed);
            }
        }

        {
            mcp_standalone::json args;
            args["action"] = "present";
            args["process_id"] = pid;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_hook_manage", "present_hook_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "present";
            args["process_id"] = pid;
            args["api"] = "d3d11";
            args["callback_mode"] = "snapshot";
            args["max_captures"] = 2;
            if (have_desc && desc.matrix_buffer_va != 0)
                args["matrix_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_hook_manage", "present_hook_snapshot_rejected", args, 7000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"snapshot", "polling", "cannot install"}, reason);
                }, passed, failed);
        }

        {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "draw";
            args["process_id"] = pid;
            args["api"] = "d3d11";
            args["callback_mode"] = "snapshot";
            args["max_captures"] = 2;
            args["capture_cbuffers"] = true;
            if (have_desc && desc.matrix_buffer_va != 0)
                args["matrix_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_hook_manage", "draw_hook_snapshot_rejected", args, 7000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"snapshot", "polling", "cannot install"}, reason);
                }, passed, failed);
        }

        if (have_desc && desc.matrix_buffer_va != 0) {
        {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["api"] = "d3d11";
            args["include_snapshot_fallback"] = false;
            args["matrix_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_list_bound_cbuffers", "list_bound_cbuffers_live_bound_context", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "list_bound_cbuffers failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!dx_list_bound_cbuffers_functional_evidence(ir.data, reason))
                        return false;
                    return true;
                }, passed, failed);
        }
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_list_bound_cbuffers", "RE descriptor missing matrix_buffer_va: " + descriptor_reason, failed);
        }

        if (have_desc && desc.matrix_buffer_va != 0 && desc.matrix_count >= 4 && desc.matrix_stride != 0) {
            mcp_standalone::json bone_args;
            bone_args["process_id"] = pid;
            bone_args["min_bones"] = 4;
            bone_args["max_bones"] = std::max<std::uint32_t>(desc.matrix_count, 4);
            bone_args["allow_memory_fallback"] = false;
            bone_args["matrix_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_identify_bone_buffer", "identify_fixture_matrix_buffer", bone_args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "bone buffer scan failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count))
                        count = ir.data.contains("candidates") && ir.data["candidates"].is_array() ? static_cast<uint64_t>(ir.data["candidates"].size()) : 0;
                    if (count == 0 && (!ir.data.contains("best") || ir.data["best"].is_null())) {
                        reason = "fixture matrix buffer was not identified data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    bool found = false;
                    if (!payload_bool_field(ir.data, "found", found) || !found) {
                        reason = "matrix-run candidate found flag missing or false data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    bool proven_skeleton = true;
                    if (!payload_bool_field(ir.data, "proven_skeleton", proven_skeleton) || proven_skeleton) {
                        reason = "matrix-run evidence was incorrectly reported as a proven skeleton data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    std::string semantics;
                    if (!payload_string_field(ir.data, "finding_semantics", semantics) || semantics != "matrix_run_candidate_only") {
                        reason = "matrix-run evidence semantics missing data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);

            mcp_standalone::json matrix_args;
            matrix_args["process_id"] = pid;
            matrix_args["scan_cbuffers_only"] = true;
            matrix_args["allow_memory_fallback"] = false;
            matrix_args["matrix_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va + desc.matrix_stride);
            test_coverage_domains_1_8_case(hf, tag, "dx_find_view_matrix", "find_fixture_view_matrix", matrix_args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "view matrix scan failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0) {
                        reason = "view matrix count missing or zero data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    std::string semantics;
                    if (!payload_string_field(ir.data, "finding_semantics", semantics) || semantics != "matrix_candidate_evidence_not_camera_object") {
                        reason = "view-matrix evidence semantics missing data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_identify_bone_buffer", "RE descriptor missing matrix_buffer_va: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_find_view_matrix", "RE descriptor missing matrix_buffer_va: " + descriptor_reason, failed);
        }

        if (have_desc && desc.resource_object_va != 0 && desc.resource_backing_va != 0) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["resource_handle"] = test_coverage_domains_1_8_hex_ptr(desc.resource_object_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_map_resource_to_va", "map_fixture_resource_backing_va", args, 4000,
                [expected = desc.resource_backing_va](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "resource mapping failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!test_coverage_domains_1_8_payload_has_any(ir, {test_coverage_domains_1_8_hex_ptr(expected).c_str()})) {
                        uint64_t count = 0;
                        if (!payload_u64_field(ir.data, "count", count))
                            count = ir.data.contains("candidates") && ir.data["candidates"].is_array() ? static_cast<uint64_t>(ir.data["candidates"].size()) : 0;
                        if (count == 0) {
                            reason = "resource mapping returned no readable pointer candidates data=" + compact_json(ir.data, 700);
                            return false;
                        }
                    }
                    return true;
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_map_resource_to_va", "RE descriptor missing resource_object_va/resource_backing_va: " + descriptor_reason, failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 dx map resource", 3000);

        scoped_coverage_domains_1_8_temp_file_t render_path("aida_coverage_dx_render.rgba");
        {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["format"] = "rgba";
            args["output_path"] = render_path.path;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_dump_render_targets", "dump_render_targets_requires_confirm", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }
        {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["process_id"] = pid;
            args["format"] = "rgba";
            args["output_path"] = render_path.path;
            test_coverage_domains_1_8_case(hf, tag, "dx_dump_render_targets", "dump_render_targets_kernel_only_fail_closed", args, 7000,
                [&render_path](const invoke_result_t& ir, std::string& reason) {
                    if (ir.success) {
                        reason = "render target dump unexpectedly succeeded data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    bool captured = false;
                    std::string source;
                    if (!payload_bool_field(ir.data, "captured", captured) || captured ||
                        !payload_string_field(ir.data, "source", source) ||
                        lower_copy(source) != "gpu_render_target_readback" ||
                        file_exists_narrow(render_path.path)) {
                        reason = "render target fail-closed payload missing captured=false/source or wrote fallback file data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        {
            mcp_standalone::json cleanup = test_coverage_domains_1_8_safe_args();
            cleanup["action"] = "remove";
            cleanup["process_id"] = pid;
            test_coverage_domains_1_8_case(hf, tag, "dx_hook_manage", "remove_after_fail_closed_snapshot_hooks", cleanup, 5000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "DX hook remove failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t removed = 0;
                    if (!payload_u64_field(ir.data, "removed_count", removed)) {
                        reason = "removed_count missing";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        {
            mcp_standalone::json cleanup = test_coverage_domains_1_8_safe_args();
            cleanup["action"] = "remove";
            cleanup["process_id"] = pid;
            bounded_finalizer_call(hf, "coverage_dx_hook_remove", 5000, [&]() {
                auto timed = invoke_tool_bounded(get_server(), "dx_hook_manage", cleanup, 5000, hf, tag, 0);
                return !timed.timed_out && timed.result.found && !timed.result.threw && timed.result.success;
            });
        }

        if (have_desc && desc.matrix_buffer_va != 0) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["matrix_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            test_coverage_domains_1_8_case(hf, tag, "dx_verify_view_matrix", "verify_fixture_matrix_projection", args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "dx_verify_view_matrix failed without eval_reason diagnostic text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    return dx_verify_view_matrix_functional_evidence(ir.data, reason);
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_verify_view_matrix", "RE descriptor missing matrix_buffer_va: " + descriptor_reason, failed);
        }

        if (have_desc && desc.matrix_buffer_va != 0 && desc.matrix_stride != 0) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["bone_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            args["view_matrix_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va + desc.matrix_stride);
            test_coverage_domains_1_8_case(hf, tag, "dx_project_bones", "project_fixture_bones_diagnostic", args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        if (ir.data.contains("eval_reason") || ir.text.find("eval_reason") != std::string::npos ||
                            ir.text.find("view matrix") != std::string::npos) {
                            return true;
                        }
                        reason = "dx_project_bones failed without diagnostic text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (ir.data.contains("projected") && ir.data["projected"].is_array())
                        return true;
                    uint64_t projected = 0;
                    if (payload_u64_field(ir.data, "projected", projected))
                        return true;
                    if (ir.data.contains("projected_count") && ir.data["projected_count"].is_number())
                        return true;
                    if (ir.data.contains("bones") && ir.data["bones"].is_array())
                        return true;
                    reason = "dx_project_bones missing projected field data=" + compact_json(ir.data, 700);
                    return false;
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_project_bones", "RE descriptor missing matrix_buffer_va/matrix_stride: " + descriptor_reason, failed);
        }

        {
            mcp_standalone::json args;
            args["action"] = "trace";
            args["process_id"] = pid;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_trace_decryption", "trace_requires_confirm", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "list";
            args["process_id"] = pid;
            test_coverage_domains_1_8_case(hf, tag, "dx_trace_decryption", "trace_list_empty_or_diagnostic", args, 5000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "dx_trace_decryption list failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (ir.data.contains("traces") && ir.data["traces"].is_array())
                        return true;
                    if (ir.data.contains("trace_count") || ir.data.contains("active_traces"))
                        return true;
                    reason = "dx_trace_decryption list missing traces array data=" + compact_json(ir.data, 700);
                    return false;
                }, passed, failed);
        }

        if (have_desc && desc.matrix_buffer_va != 0) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_read_gpu_buffer", "read_gpu_buffer_requires_confirm", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "dx_read_gpu_buffer", "RE descriptor missing matrix_buffer_va: " + descriptor_reason, failed);
        }

        {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_auto_narrow", "auto_narrow_requires_confirm", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["process_id"] = pid;
            test_coverage_domains_1_8_case(hf, tag, "dx_auto_narrow", "auto_narrow_kernel_unavailable_fail_closed", args, 7000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (ir.success) {
                        reason = "dx_auto_narrow unexpectedly succeeded data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    if (ir.data.contains("capability") && ir.data["capability"].is_object()) {
                        bool available = true;
                        if (payload_bool_field(ir.data["capability"], "available", available) && !available)
                            return true;
                    }
                    reason = "dx_auto_narrow fail-closed payload missing capability.available=false data=" + compact_json(ir.data, 700);
                    return false;
                }, passed, failed);
        }

        {
            mcp_standalone::json args;
            args["process_id"] = pid;
            if (have_desc && desc.matrix_buffer_va != 0) {
                args["view_matrix_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
                args["bone_buffer_va"] = test_coverage_domains_1_8_hex_ptr(desc.matrix_buffer_va);
            }
            test_coverage_domains_1_8_case(hf, tag, "dx_correlate_results", "correlate_results_empty_frame_batches", args, 5000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "dx_correlate_results failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (ir.data.contains("frame_matches") && ir.data["frame_matches"].is_array())
                        return true;
                    if (ir.data.contains("frame_match_count"))
                        return true;
                    reason = "dx_correlate_results missing frame_matches array data=" + compact_json(ir.data, 700);
                    return false;
                }, passed, failed);
        }

        {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["latest"] = true;
            test_coverage_domains_1_8_case(hf, tag, "dx_get_frame_summary", "get_frame_summary_captured_batches", args, 5000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "dx_get_frame_summary failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    return dx_get_frame_summary_functional_evidence(ir.data, reason);
                }, passed, failed);
        }

        (void)cancelled;
    }

    bool test_coverage_domains_1_8_signature_pattern_for_va(std::uint32_t pid,
                                                             std::uint64_t va,
                                                             std::string& pattern) {
        pattern.clear();
        if (pid == 0 || va == 0)
            return false;
        std::vector<std::uint8_t> bytes;
        if (!driver_bridge::read_memory_for(pid, va, 8, bytes) || bytes.size() < 4)
            return false;
        bytes.resize(std::min<std::size_t>(bytes.size(), 8));
        pattern = hex_preview(bytes, bytes.size());
        return !pattern.empty();
    }

    bool test_coverage_domains_1_8_prepare_vmt_fixture(HANDLE hf,
                                                   const char* tag,
                                                   scoped_coverage_domains_1_8_remote_region_t& code,
                                                   scoped_coverage_domains_1_8_remote_region_t& table,
                                                   scoped_coverage_domains_1_8_remote_region_t& object,
                                                   std::uint64_t preferred_fn0,
                                                   std::uint64_t preferred_fn1,
                                                   std::uint64_t& fn0_va,
                                                   std::uint64_t& fn1_va,
                                                   std::string& slot0_pattern,
                                                   std::string& reason) {
        fn0_va = 0;
        fn1_va = 0;
        slot0_pattern.clear();
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        std::vector<std::uint8_t> code_bytes(4096, 0x90);
        const std::uint8_t fn0[] = {0x48, 0x31, 0xC0, 0xC3};
        const std::uint8_t fn1[] = {0x48, 0x83, 0xC0, 0x01, 0xC3};
        if (preferred_fn0 != 0 && preferred_fn1 != 0 && preferred_fn0 != preferred_fn1 &&
            test_coverage_domains_1_8_signature_pattern_for_va(pid, preferred_fn0, slot0_pattern)) {
            fn0_va = preferred_fn0;
            fn1_va = preferred_fn1;
        } else {
            std::memcpy(code_bytes.data(), fn0, sizeof(fn0));
            std::memcpy(code_bytes.data() + 0x20, fn1, sizeof(fn1));
            if (!code.allocate(code_bytes, code_bytes.size(), PAGE_EXECUTE_READWRITE)) {
                reason = "failed to allocate executable VMT code fixture";
                return false;
            }
            fn0_va = code.addr;
            fn1_va = code.addr + 0x20;
            slot0_pattern = "48 31 C0 C3";
        }
        std::vector<std::uint8_t> table_bytes(4096, 0);
        std::memcpy(table_bytes.data(), &fn0_va, sizeof(fn0_va));
        std::memcpy(table_bytes.data() + 8, &fn1_va, sizeof(fn1_va));
        if (!table.allocate(table_bytes, table_bytes.size(), PAGE_READWRITE)) {
            reason = "failed to allocate VMT table fixture";
            return false;
        }
        std::vector<std::uint8_t> object_bytes(4096, 0);
        std::memcpy(object_bytes.data(), &table.addr, sizeof(table.addr));
        if (!object.allocate(object_bytes, object_bytes.size(), PAGE_READWRITE)) {
            reason = "failed to allocate VMT object fixture";
            return false;
        }
        log_msg(hf, tag, "FIXTURE -- vmt object=0x%016llX table=0x%016llX fn0=0x%016llX fn1=0x%016llX pattern=%s source=%s",
            static_cast<unsigned long long>(object.addr),
            static_cast<unsigned long long>(table.addr),
            static_cast<unsigned long long>(fn0_va),
            static_cast<unsigned long long>(fn1_va),
            slot0_pattern.c_str(),
            code.addr == 0 ? "target_exports" : "remote_code");
        return true;
    }

    void test_coverage_domains_1_8_cleanup_vmt_hook(HANDLE hf, const char* tag, const std::string& hook_id) {
        if (hook_id.empty())
            return;
        mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
        args["action"] = "remove";
        args["hook_id"] = hook_id;
        bounded_finalizer_call(hf, "coverage_vmt_hook_remove", 5000, [&]() {
            auto timed = invoke_tool_bounded(get_server(), "vmt_hook_manage", args, 5000, hf, tag, 0);
            return !timed.timed_out && timed.result.found && !timed.result.threw && timed.result.success;
        });
    }

    void test_coverage_domains_1_8_vmt_tools(HANDLE hf,
                                          const test_coverage_domains_1_8_re_descriptor_t& desc,
                                          bool have_desc,
                                          std::atomic<int>& passed,
                                          std::atomic<int>& failed,
                                          bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.vmt";
        set_progress_step("mcp coverage domains 1-8: vmt tools");
        scoped_coverage_domains_1_8_remote_region_t code(hf, tag);
        scoped_coverage_domains_1_8_remote_region_t table(hf, tag);
        scoped_coverage_domains_1_8_remote_region_t object(hf, tag);
        std::string fixture_reason;
        std::uint64_t preferred_fn0 = 0;
        std::uint64_t preferred_fn1 = 0;
        if (have_desc) {
            const std::uint64_t candidates[] = {
                desc.analysis_branch_fn_va,
                desc.analysis_callgraph_fn_va,
                desc.analysis_dispatch_fn_va,
                desc.heap_burst_fn_va,
                desc.frame_tick_fn_va
            };
            for (std::uint64_t candidate : candidates) {
                if (candidate == 0)
                    continue;
                if (preferred_fn0 == 0)
                    preferred_fn0 = candidate;
                else if (candidate != preferred_fn0) {
                    preferred_fn1 = candidate;
                    break;
                }
            }
        }
        std::uint64_t fixture_fn0 = 0;
        std::uint64_t fixture_fn1 = 0;
        std::string fixture_slot0_pattern;
        if (!test_coverage_domains_1_8_prepare_vmt_fixture(hf, tag, code, table, object, preferred_fn0, preferred_fn1, fixture_fn0, fixture_fn1, fixture_slot0_pattern, fixture_reason)) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "vmt_read", fixture_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "vmt_hook_manage", fixture_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "vmt_copy", fixture_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "vmt_find_slot_by_signature", fixture_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "vmt_scan_objects", fixture_reason, failed);
            return;
        }
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["address"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["max_slots"] = 2;
            test_coverage_domains_1_8_case(hf, tag, "vmt_read", "read_synthetic_object_vtable", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt_read failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t returned = 0;
                    if (!payload_u64_field(ir.data, "returned", returned) || returned < 2) {
                        reason = "returned slots missing or <2";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["vtable_va"] = test_coverage_domains_1_8_hex_ptr(table.addr);
            args["pattern"] = fixture_slot0_pattern;
            args["max_slots"] = 2;
            test_coverage_domains_1_8_case(hf, tag, "vmt_find_slot_by_signature", "find_slot_by_fixture_prologue", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt_find_slot_by_signature failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t slot = 99;
                    if (!payload_u64_field(ir.data, "slot", slot) || slot != 0) {
                        reason = "expected slot 0 match data=" + compact_json(ir.data, 500);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["vtable_va"] = test_coverage_domains_1_8_hex_ptr(table.addr);
            args["object_va"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["range_base"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["range_size"] = 0x1000;
            args["max_results"] = 8;
            test_coverage_domains_1_8_case(hf, tag, "vmt_scan_objects", "scan_object_pointing_to_fixture_vtable", args, 4000,
                [object_va = object.addr](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt_scan_objects failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!test_coverage_domains_1_8_payload_has_any(ir, {test_coverage_domains_1_8_hex_ptr(object_va).c_str()})) {
                        reason = "object address not present in scan results data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "install";
            args["process_id"] = pid;
            args["object_va"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["vtable_va"] = test_coverage_domains_1_8_hex_ptr(table.addr);
            args["callback_va"] = test_coverage_domains_1_8_hex_ptr(fixture_fn1);
            args["slot"] = 0;
            args["method"] = "patch_object";
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "vmt_hook_manage", "install_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        std::string installed_hook_id;
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "install";
            args["process_id"] = pid;
            args["object_va"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["vtable_va"] = test_coverage_domains_1_8_hex_ptr(table.addr);
            args["callback_va"] = test_coverage_domains_1_8_hex_ptr(fixture_fn1);
            args["slot"] = 0;
            args["method"] = "patch_object";
            invoke_result_t out;
            test_coverage_domains_1_8_case(hf, tag, "vmt_hook_manage", "install_patch_object_safe_fixture", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt hook install failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string hook_id;
                    if (!payload_string_field(ir.data, "hook_id", hook_id) || hook_id.empty()) {
                        reason = "hook_id missing";
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            if (out.success)
                payload_string_field(out.data, "hook_id", installed_hook_id);
        }

        if (!installed_hook_id.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args;
            args["action"] = "list";
            args["process_id"] = pid;
            test_coverage_domains_1_8_case(hf, tag, "vmt_hook_manage", "list_installed_hook_safe_fixture", args, 3000,
                [installed_hook_id](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt hook list failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!payload_text_contains(ir, lower_copy(installed_hook_id))) {
                        reason = "installed hook_id missing from list data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (installed_hook_id.empty()) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "vmt_hook_manage", "install did not produce hook_id for list", "vmt_hook_manage.install", "missing_hook_id_for_list", failed);
        }

        if (!installed_hook_id.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "remove";
            args["hook_id"] = installed_hook_id;
            const std::string removing_hook_id = installed_hook_id;
            const bool removed = test_coverage_domains_1_8_case(hf, tag, "vmt_hook_manage", "remove_installed_hook_safe_fixture", args, 4000,
                [removing_hook_id](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt hook remove failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    bool restored = false;
                    if (!payload_bool_field(ir.data, "restored", restored) || !restored || !payload_text_contains(ir, lower_copy(removing_hook_id))) {
                        reason = "remove response missing restored=true or hook_id data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
            if (removed)
                installed_hook_id.clear();
        } else if (installed_hook_id.empty()) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "vmt_hook_manage", "install did not produce hook_id for remove", "vmt_hook_manage.install", "missing_hook_id_for_remove", failed);
        }
        test_coverage_domains_1_8_cleanup_vmt_hook(hf, tag, installed_hook_id);

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["object_va"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "vmt_copy", "copy_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        std::string copy_hook_id;
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["process_id"] = pid;
            args["object_va"] = test_coverage_domains_1_8_hex_ptr(object.addr);
            args["max_slots"] = 2;
            invoke_result_t out;
            test_coverage_domains_1_8_case(hf, tag, "vmt_copy", "copy_object_vtable_safe_fixture", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "vmt_copy failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string hook_id;
                    uint64_t slots = 0;
                    if (!payload_string_field(ir.data, "hook_id", hook_id) || hook_id.empty() ||
                        !payload_u64_field(ir.data, "slots_copied", slots) || slots == 0) {
                        reason = "hook_id or slots_copied missing";
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            if (out.success)
                payload_string_field(out.data, "hook_id", copy_hook_id);
        }
        test_coverage_domains_1_8_cleanup_vmt_hook(hf, tag, copy_hook_id);
    }

    void test_coverage_domains_1_8_rtti_tools(HANDLE hf,
                                          const test_coverage_domains_1_8_re_descriptor_t& desc,
                                          bool have_desc,
                                          const std::string& descriptor_reason,
                                          std::atomic<int>& passed,
                                          std::atomic<int>& failed,
                                          bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.rtti";
        set_progress_step("mcp coverage domains 1-8: rtti tools");
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        if (!have_desc || desc.rtti_vtable_va == 0) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "rtti_scan", "RE descriptor missing RTTI fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "rtti_find_type", "RE descriptor missing RTTI fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "rtti_list_hierarchy", "RE descriptor missing RTTI fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "rtti_find_constructor", "RE descriptor missing RTTI fixture: " + descriptor_reason, failed);
            return;
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["filter"] = "fixture_rtti";
            args["max_results"] = 16;
            test_coverage_domains_1_8_add_rtti_exact_args(args, desc);
            test_coverage_domains_1_8_case(hf, tag, "rtti_scan", "scan_fixture_rtti_types", args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "rtti_scan failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t returned = 0;
                    if (!payload_u64_field(ir.data, "returned", returned) || returned == 0 || !payload_text_contains(ir, "fixture_rtti")) {
                        reason = "fixture RTTI type not returned data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["pattern"] = "fixture_rtti_entity";
            test_coverage_domains_1_8_add_rtti_exact_args(args, desc);
            test_coverage_domains_1_8_case(hf, tag, "rtti_find_type", "find_fixture_rtti_entity", args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "rtti_find_type failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !payload_text_contains(ir, "fixture_rtti_entity")) {
                        reason = "fixture_rtti_entity match missing data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["type_name_or_va"] = "fixture_rtti_entity";
            test_coverage_domains_1_8_add_rtti_exact_args(args, desc);
            test_coverage_domains_1_8_case(hf, tag, "rtti_list_hierarchy", "list_fixture_rtti_hierarchy", args, 6000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "rtti_list_hierarchy failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    if (!ir.data.contains("hierarchy") || !ir.data["hierarchy"].is_array()) {
                        reason = "hierarchy array missing data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["max_scan_bytes"] = 4ull * 1024ull * 1024ull;
            test_coverage_domains_1_8_add_rtti_exact_args(args, desc);
            test_coverage_domains_1_8_case(hf, tag, "rtti_find_constructor", "find_fixture_rtti_constructor_refs", args, 7000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "rtti_find_constructor failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0) {
                        reason = "constructor candidate count is zero data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 rtti tools", 3000);
    }

    void test_coverage_domains_1_8_encptr_tools(HANDLE hf,
                                            std::atomic<int>& passed,
                                            std::atomic<int>& failed,
                                            bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.encptr";
        set_progress_step("mcp coverage domains 1-8: encoded pointer tools");
        scoped_coverage_domains_1_8_remote_region_t target(hf, tag);
        scoped_coverage_domains_1_8_remote_region_t source(hf, tag);
        std::vector<std::uint8_t> target_bytes(4096, 0x41);
        if (!target.allocate(target_bytes, target_bytes.size(), PAGE_READWRITE)) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_scan_chain", "failed to allocate target pointer fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_detect_transform", "failed to allocate target pointer fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_emit_resolver", "failed to allocate target pointer fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_verify_stable", "failed to allocate target pointer fixture", failed);
            return;
        }
        const std::uint64_t key = 0xA1DA55AA33CC7700ull;
        const std::uint64_t raw = target.addr ^ key;
        std::vector<std::uint8_t> source_bytes(4096, 0);
        std::memcpy(source_bytes.data(), &raw, sizeof(raw));
        if (!source.allocate(source_bytes, source_bytes.size(), PAGE_READWRITE)) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_scan_chain", "failed to allocate encoded source fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_detect_transform", "failed to allocate encoded source fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_emit_resolver", "failed to allocate encoded source fixture", failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "encptr_verify_stable", "failed to allocate encoded source fixture", failed);
            return;
        }
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["raw_value"] = test_coverage_domains_1_8_hex_ptr(raw);
            args["expected_next"] = test_coverage_domains_1_8_hex_ptr(target.addr);
            args["test_xor"] = true;
            args["test_rol"] = false;
            args["test_add"] = false;
            args["allow_derived_keys"] = true;
            args["auto_derive"] = true;
            const std::string expected_next_hex = test_coverage_domains_1_8_hex_ptr(target.addr);
            test_coverage_domains_1_8_case(hf, tag, "encptr_detect_transform", "detect_known_xor_transform", args, 2500,
                [expected_next_hex](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "detect_transform failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string type;
                    std::string expected;
                    if (payload_string_field(ir.data, "transform_type", type) && type == "xor" &&
                        payload_string_field(ir.data, "expected_next", expected) && lower_copy(expected) == lower_copy(expected_next_hex)) {
                        return true;
                    }
                    const auto candidates = ir.data.find("candidates");
                    if (candidates != ir.data.end() && candidates->is_array()) {
                        for (const auto& item : *candidates) {
                            type.clear();
                            expected.clear();
                            if (item.is_object() &&
                                payload_string_field(item, "transform_type", type) && type == "xor" &&
                                payload_string_field(item, "expected_next", expected) && lower_copy(expected) == lower_copy(expected_next_hex)) {
                                return true;
                            }
                        }
                    }
                    reason = "expected constrained xor transform candidate data=" + compact_json(ir.data, 700);
                    return false;
                }, passed, failed);
        }

        mcp_standalone::json chain;
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["source_va"] = test_coverage_domains_1_8_hex_ptr(source.addr);
            args["target_va"] = test_coverage_domains_1_8_hex_ptr(target.addr);
            args["max_hops"] = 1;
            args["max_offset"] = 0;
            args["max_results"] = 1;
            args["test_xor"] = true;
            args["test_rol"] = false;
            args["test_add"] = false;
            args["xor_keys"] = mcp_standalone::json::array({test_coverage_domains_1_8_hex_ptr(key)});
            invoke_result_t out;
            test_coverage_domains_1_8_case(hf, tag, "encptr_scan_chain", "scan_known_xor_chain", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "scan_chain failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0) {
                        reason = "chain count missing or zero data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            if (out.success)
                test_coverage_domains_1_8_first_array_item(out.data, "paths", chain);
        }

        if (chain.is_object() && (!cancelled || !cancelled())) {
            mcp_standalone::json args;
            args["chain"] = chain;
            args["function_name"] = "resolve_aida_coverage_xor_chain";
            args["base_symbol"] = "module_base";
            test_coverage_domains_1_8_case(hf, tag, "encptr_emit_resolver", "emit_resolver_for_scanned_chain", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "emit_resolver failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string source;
                    if (!payload_string_field(ir.data, "cpp_source", source) || source.find("resolve_aida_coverage_xor_chain") == std::string::npos || source.find("read64") == std::string::npos) {
                        reason = "resolver source missing function/read64 evidence";
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "encptr_emit_resolver", "scan_chain did not return a usable chain", "encptr_scan_chain", "missing_chain_for_emit_resolver", failed);
        }

        if (chain.is_object() && (!cancelled || !cancelled())) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["chain"] = chain;
            args["samples"] = 3;
            args["interval_ms"] = 0;
            test_coverage_domains_1_8_case(hf, tag, "encptr_verify_stable", "verify_scanned_chain_stability", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "verify_stable failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t ok = 0;
                    std::string stability;
                    if (!payload_u64_field(ir.data, "samples_ok", ok) || ok < 3 ||
                        !payload_string_field(ir.data, "stability", stability) || stability != "always_same") {
                        reason = "expected samples_ok=3 and always_same data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "encptr_verify_stable", "scan_chain did not return a usable chain", "encptr_scan_chain", "missing_chain_for_verify_stable", failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 encptr tools", 3000);
    }

    void test_coverage_domains_1_8_offsets_and_sigs(HANDLE hf,
                                                const test_coverage_domains_1_8_re_descriptor_t& desc,
                                                bool have_desc,
                                                const std::string& descriptor_reason,
                                                std::atomic<int>& passed,
                                                std::atomic<int>& failed,
                                                bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.persist";
        set_progress_step("mcp coverage domains 1-8: offsets and signatures");
        scoped_coverage_domains_1_8_file_restore_t offsets_restore(hf, tag, ::re::appdata_re_dir() / "offsets.json");
        scoped_coverage_domains_1_8_file_restore_t sigs_restore(hf, tag, ::re::appdata_re_dir() / "signatures.json");
        scoped_coverage_domains_1_8_temp_file_t offsets_export("aida_coverage_offsets_export.hpp");
        scoped_coverage_domains_1_8_temp_file_t sigs_export("aida_coverage_sigs_export.json");
        scoped_coverage_domains_1_8_remote_region_t fallback_region(hf, tag);
        scoped_coverage_domains_1_8_remote_region_t sig_region(hf, tag);
        const std::vector<std::uint8_t> sig_bytes = {0x41, 0x69, 0x44, 0x41, 0xD1, 0x08, 0x44, 0x22, 0x19, 0x88, 0x33, 0x77, 0x55, 0xAA, 0x10, 0x40};
        std::uint64_t fixture_va = have_desc ? desc.matrix_buffer_va : 0;
        if (fixture_va == 0) {
            if (fallback_region.allocate(sig_bytes, 4096, PAGE_READWRITE))
                fixture_va = fallback_region.addr;
        }
        if (fixture_va == 0) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "offsets_manage", "no descriptor matrix buffer and synthetic fallback allocation failed: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "sigs_manage", "no descriptor matrix buffer and synthetic fallback allocation failed: " + descriptor_reason, failed);
            return;
        }
        const bool sig_region_ready = sig_region.allocate(sig_bytes, 4096, PAGE_READWRITE);
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        const std::string category = "aida_coverage_domains_1_8";
        const std::string offset_name = "aida_coverage_fixture_matrix";
        const std::string sig_name = "aida_coverage_fixture_pattern";

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "record";
            args["process_id"] = pid;
            args["name"] = offset_name;
            args["category"] = category;
            args["va"] = test_coverage_domains_1_8_hex_ptr(fixture_va);
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "record_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        std::string offset_id;
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "record";
            args["process_id"] = pid;
            args["name"] = offset_name;
            args["category"] = category;
            args["notes"] = "testlab_domains_1_8";
            args["rtti_path"] = "fixture_rtti_entity.matrix";
            args["xref_context"] = "aida_test_re_descriptor.matrix_buffer_va";
            args["va"] = test_coverage_domains_1_8_hex_ptr(fixture_va);
            invoke_result_t out;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "record_fixture_offset", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "offset record failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string id;
                    if (!payload_string_field(ir.data, "offset_id", id) || id.empty()) {
                        reason = "offset_id missing";
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            if (out.success)
                payload_string_field(out.data, "offset_id", offset_id);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "list";
            args["category"] = category;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "list_fixture_offset", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "offset list failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !payload_text_contains(ir, "aida_coverage_fixture_matrix")) {
                        reason = "recorded offset not present in list data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!offset_id.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "reverify";
            args["process_id"] = pid;
            args["offset_id"] = offset_id;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "reverify_fixture_offset", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "offset reverify failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    size_t valid = 0;
                    if (!payload_array_count(ir.data, "valid", valid) || valid == 0) {
                        reason = "valid array missing or empty data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (offset_id.empty()) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "offsets_manage", "offset record did not produce offset_id for reverify", "offsets_manage.record", "missing_offset_id_for_reverify", failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 offsets reverify", 3000);

        if (!offset_id.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "rebase";
            args["process_id"] = pid;
            args["offset_id"] = offset_id;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "rebase_recorded_fixture_offset", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "offset rebase failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    bool rebased = false;
                    size_t valid = 0;
                    size_t broken = 0;
                    size_t shifted = 0;
                    size_t ambiguous = 0;
                    size_t skipped = 0;
                    payload_array_count(ir.data, "valid", valid);
                    payload_array_count(ir.data, "broken", broken);
                    payload_array_count(ir.data, "shifted", shifted);
                    payload_array_count(ir.data, "ambiguous", ambiguous);
                    payload_array_count(ir.data, "skipped", skipped);
                    if (!payload_bool_field(ir.data, "rebased", rebased) || !rebased ||
                        (valid + broken + shifted + ambiguous + skipped) == 0) {
                        reason = "rebase response missing rebased=true or scoped offset row data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (offset_id.empty()) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "offsets_manage", "offset record did not produce offset_id for rebase", "offsets_manage.record", "missing_offset_id_for_rebase", failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "export";
            args["output_path"] = offsets_export.path;
            args["namespace_name"] = "AiDATodoOffsets";
            args["use_rva"] = false;
            test_coverage_domains_1_8_case(hf, tag, "offsets_manage", "export_fixture_offsets_to_temp", args, 3000,
                [&offsets_export](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "offset export failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !file_exists_narrow(offsets_export.path)) {
                        reason = "export count missing/zero or output file missing";
                        return false;
                    }
                    std::ifstream in(offsets_export.path, std::ios::binary);
                    const std::string body((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
                    if (body.find("aida_coverage_fixture_matrix") == std::string::npos) {
                        reason = "export output missing fixture offset symbol";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!sig_region_ready) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "sigs_manage", "failed to allocate synthetic signature pattern region", failed);
            return;
        }

        const std::string pattern = "41 69 44 41 D1 08 44 22 19 88 33 77 55 AA 10 40";
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "save";
            args["name"] = sig_name;
            args["pattern"] = pattern;
            args["category"] = category;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "save_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "save";
            args["name"] = sig_name;
            args["pattern"] = pattern;
            args["category"] = category;
            args["notes"] = "testlab_domains_1_8";
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "save_fixture_signature", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "signature save failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string id;
                    if (!payload_string_field(ir.data, "id", id) || id.empty()) {
                        reason = "signature id missing";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "list";
            args["category"] = category;
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "list_fixture_signature", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "signature list failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !payload_text_contains(ir, "aida_coverage_fixture_pattern")) {
                        reason = "saved signature not present in list data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "scan_all";
            args["process_id"] = pid;
            args["scan_start_va"] = test_coverage_domains_1_8_hex_ptr(sig_region.addr);
            args["scan_size"] = 4096;
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "scan_all_fixture_signature", args, 5000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "signature scan_all failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !payload_text_contains(ir, "aida_coverage_fixture_pattern")) {
                        reason = "scan results missing fixture signature evidence data=" + compact_json(ir.data, 900);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 sigs scan", 3000);

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "export";
            args["output_path"] = sigs_export.path;
            args["format"] = "json";
            args["category"] = category;
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "export_fixture_signatures_to_temp", args, 3000,
                [&sigs_export](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "signature export failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t count = 0;
                    if (!payload_u64_field(ir.data, "count", count) || count == 0 || !file_exists_narrow(sigs_export.path)) {
                        reason = "signature export count missing/zero or output file missing";
                        return false;
                    }
                    std::ifstream in(sigs_export.path, std::ios::binary);
                    const std::string body((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
                    if (body.find("aida_coverage_fixture_pattern") == std::string::npos) {
                        reason = "signature export output missing fixture signature";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (file_exists_narrow(sigs_export.path) && (!cancelled || !cancelled())) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "import";
            args["source"] = sigs_export.path;
            args["format"] = "json";
            test_coverage_domains_1_8_case(hf, tag, "sigs_manage", "import_fixture_signatures_from_temp_export", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "signature import failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t imported = 0;
                    if (!payload_u64_field(ir.data, "imported", imported) || imported == 0) {
                        reason = "signature import count missing or zero data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (!file_exists_narrow(sigs_export.path)) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "sigs_manage", "signature export did not produce temp JSON file for import", "sigs_manage.export", "missing_signature_export_file_for_import", failed);
        }
    }

    void test_coverage_domains_1_8_heap_tools(HANDLE hf,
                                          test_coverage_domains_1_8_re_descriptor_t& desc,
                                          bool have_desc,
                                          const std::string& descriptor_reason,
                                          std::atomic<int>& passed,
                                          std::atomic<int>& failed,
                                          bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.heap";
        set_progress_step("mcp coverage domains 1-8: heap tracking");
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["action"] = "start";
            args["process_id"] = pid;
            args["backend"] = "event";
            args["max_captures"] = 32;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "heap_track_manage", "start_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        if (!have_desc || desc.heap_burst_fn_va == 0) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "heap_track_manage", "RE descriptor missing heap_burst_fn_va: " + descriptor_reason, failed);
            return;
        }

        std::string session_id;
        if (!cancelled || !cancelled()) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "start";
            args["process_id"] = pid;
            args["backend"] = "event";
            args["min_size"] = 64;
            args["max_size"] = 4096;
            args["max_captures"] = 64;
            args["skip_initial_snapshot"] = true;
            invoke_result_t out;
            test_coverage_domains_1_8_case(hf, tag, "heap_track_manage", "start_event_safe_fixture", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "heap start failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string id;
                    if (!payload_string_field(ir.data, "session_id", id) || id.empty()) {
                        reason = "session_id missing";
                        return false;
                    }
                    bool event_active = false;
                    if (!payload_string_field_equals_lc(ir.data, "capture_backend", "kernel_context_hwbp_rtlallocateheap_return_poll") ||
                        !payload_string_field_equals_lc(ir.data, "backend", "kernel_context_hwbp_rtlallocateheap_return_poll") ||
                        !payload_bool_field(ir.data, "event_capture_active", event_active) ||
                        !event_active) {
                        reason = "heap event backend proof missing data=" + compact_json(ir.data, 900);
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            if (out.success)
                payload_string_field(out.data, "session_id", session_id);
            log_msg(hf, tag, "HEAP-SESSION -- phase=start status_success=%d session_id=%s args=%s data=%s",
                out.success ? 1 : 0,
                session_id.empty() ? "<empty>" : session_id.c_str(),
                compact_json(args, 900).c_str(),
                compact_json(out.data, 900).c_str());
        }

        bool heap_stimulus_ok = false;
        if (!session_id.empty()) {
            const std::uint64_t first = page_guard_engine::remote_thread_call(pid, desc.heap_burst_fn_va, 12, 160, 0, 0, 5000, "aida_test_re_heap_burst");
            const bool refreshed = test_coverage_domains_1_8_refresh_re_descriptor(hf, tag, desc);
            heap_stimulus_ok = first != 0 && refreshed && desc.heap_burst_first_va != 0 && desc.heap_burst_count > 0;
            log_msg(hf, tag, "FIXTURE -- heap_burst result=0x%016llX fn=0x%016llX",
                static_cast<unsigned long long>(first),
                static_cast<unsigned long long>(desc.heap_burst_fn_va));
            log_msg(hf, tag, "FIXTURE -- heap_burst_readback ok=%d refreshed=%d first_va=0x%016llX count=%u stride=%u",
                heap_stimulus_ok ? 1 : 0,
                refreshed ? 1 : 0,
                static_cast<unsigned long long>(desc.heap_burst_first_va),
                desc.heap_burst_count,
                desc.heap_burst_stride);
        }

        if (!session_id.empty() && heap_stimulus_ok && (!cancelled || !cancelled())) {
            mcp_standalone::json args;
            args["action"] = "results";
            args["session_id"] = session_id;
            args["limit"] = 64;
            args["focus_only"] = true;
            if (desc.heap_burst_first_va != 0) {
                args["focus_va"] = test_coverage_domains_1_8_hex_ptr(desc.heap_burst_first_va);
                args["focus_count"] = std::max<std::uint32_t>(desc.heap_burst_count, 1);
                args["focus_stride"] = desc.heap_burst_stride != 0 ? desc.heap_burst_stride : 160;
                args["focus_size"] = desc.heap_burst_stride != 0 ? desc.heap_burst_stride : 160;
            }
            log_msg(hf, tag, "HEAP-SESSION -- phase=results session_id=%s active_pid=%u heap_first_va=0x%016llX heap_count=%u heap_stride=%u args=%s",
                session_id.c_str(),
                pid,
                static_cast<unsigned long long>(desc.heap_burst_first_va),
                desc.heap_burst_count,
                desc.heap_burst_stride,
                compact_json(args, 900).c_str());
            test_coverage_domains_1_8_case(hf, tag, "heap_track_manage", "results_after_fixture_heap_burst", args, 4000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "heap results failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t returned = 0;
                    if (!payload_u64_field(ir.data, "returned", returned) || returned == 0) {
                        reason = "heap results returned zero allocation events; fixture heap burst did not appear in tracker data=" + compact_json(ir.data, 900);
                        return false;
                    }
                    bool functional_event = false;
                    if (!payload_bool_field(ir.data, "functional_event_evidence", functional_event) || !functional_event ||
                        !payload_string_field_equals_lc(ir.data, "backend", "kernel_context_hwbp_rtlallocateheap_return_poll")) {
                        reason = "heap results missing functional event backend proof data=" + compact_json(ir.data, 900);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (!session_id.empty() && !heap_stimulus_ok) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "heap_track_manage",
                "heap burst stimulus/readback failed first_va=" + hex_u64(desc.heap_burst_first_va) +
                " count=" + std::to_string(desc.heap_burst_count) +
                " stride=" + std::to_string(desc.heap_burst_stride),
                "heap_burst_stimulus", "heap_stimulus_or_readback_failed", failed);
        } else if (session_id.empty()) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "heap_track_manage", "heap start did not produce session_id for results", "heap_track_manage.start", "missing_heap_session_id_for_results", failed);
        }

        if (!session_id.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["action"] = "stop";
            args["session_id"] = session_id;
            log_msg(hf, tag, "HEAP-SESSION -- phase=stop session_id=%s args=%s",
                session_id.c_str(),
                compact_json(args, 900).c_str());
            test_coverage_domains_1_8_case(hf, tag, "heap_track_manage", "stop_heap_session_safe_fixture", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "heap stop failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    bool stopped = false;
                    if (!payload_bool_field(ir.data, "stopped", stopped) || !stopped) {
                        reason = "stopped=true missing";
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!session_id.empty()) {
            mcp_standalone::json cleanup = test_coverage_domains_1_8_safe_args();
            cleanup["action"] = "stop";
            cleanup["session_id"] = session_id;
            bounded_finalizer_call(hf, "coverage_heap_stop", 4000, [&]() {
                auto timed = invoke_tool_bounded(get_server(), "heap_track_manage", cleanup, 4000, hf, tag, 0);
                return timed.timed_out || !timed.result.found || timed.result.threw || timed.result.success || timed.result.text.find("Unknown heap tracking session") != std::string::npos;
            });
        }
        if (desc.heap_burst_fn_va != 0)
            page_guard_engine::remote_thread_call(pid, desc.heap_burst_fn_va, 1, 64, 0, 0, 3000, "aida_test_re_heap_burst_cleanup");
    }

    void test_coverage_domains_1_8_struct_tools(HANDLE hf,
                                            test_coverage_domains_1_8_re_descriptor_t& desc,
                                            bool have_desc,
                                            const std::string& descriptor_reason,
                                            std::atomic<int>& passed,
                                            std::atomic<int>& failed,
                                            bool(*cancelled)()) {
        const char* tag = "mcp.coverage.domains_1_8.struct";
        set_progress_step("mcp coverage domains 1-8: struct tools");
        const std::uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        if (!have_desc || desc.struct_base_va == 0 || desc.struct_array_va == 0 || desc.struct_size == 0 || desc.struct_count < 3 || desc.mutate_struct_fn_va == 0) {
            test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_observe", "RE descriptor missing struct fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_correlate", "RE descriptor missing struct fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_array_detect", "RE descriptor missing struct fixture: " + descriptor_reason, failed);
            test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_compare_snapshots", "RE descriptor missing struct fixture: " + descriptor_reason, failed);
            return;
        }
        const std::uint64_t observed_struct_va = desc.struct_array_va;
        auto wait_struct_monitor_idle = [&](const char* phase, std::uint64_t timeout_ms) {
            const std::uint64_t started = GetTickCount64();
            while (struct_recon::g_state.monitoring.load(std::memory_order_acquire) &&
                GetTickCount64() - started < timeout_ms) {
                Sleep(20);
            }
            const bool idle = !struct_recon::g_state.monitoring.load(std::memory_order_acquire);
            log_msg(hf, tag, "STRUCT-IDLE-WAIT -- phase=%s idle=%d elapsed_ms=%llu timeout_ms=%llu",
                phase ? phase : "<empty>",
                idle ? 1 : 0,
                static_cast<unsigned long long>(GetTickCount64() - started),
                static_cast<unsigned long long>(timeout_ms));
            return idle;
        };
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 struct preflight", 3000);

        std::vector<std::uint8_t> preflight_before;
        std::vector<std::uint8_t> preflight_after;
        std::string preflight_before_reason;
        std::string preflight_after_reason;
        const std::size_t struct_preflight_read_size = std::min<std::size_t>(static_cast<std::size_t>(desc.struct_size), 128);
        driver_bridge::memory_region_t preflight_region_before{};
        const bool preflight_region_before_ok = driver_bridge::query_memory_for(pid, observed_struct_va, preflight_region_before);
        const std::string preflight_region_before_error = preflight_region_before_ok ? std::string() : driver_bridge::last_error();
        const bool preflight_before_ok = testlab_read_remote_exact(pid, observed_struct_va, struct_preflight_read_size, preflight_before, preflight_before_reason);
        test_coverage_domains_1_8_struct_mutation_diag_t preflight_diag_before{};
        test_coverage_domains_1_8_struct_mutation_diag_t preflight_diag_after{};
        std::string preflight_diag_before_reason;
        std::string preflight_diag_after_reason;
        const bool preflight_diag_before_ok = test_coverage_domains_1_8_read_struct_mutation_diag(pid, desc, preflight_diag_before, preflight_diag_before_reason);
        const std::uint64_t preflight_started = GetTickCount64();
        std::uint64_t preflight_result = 0;
        for (int preflight_attempt = 0; preflight_attempt < 3; ++preflight_attempt) {
            preflight_result = page_guard_engine::remote_thread_call(pid, desc.mutate_struct_fn_va, 0, 5, 0, 0, 3000, "aida_test_re_mutate_struct_preflight", true);
            log_msg(hf, tag, "STRUCT-MUTATION-PREFLIGHT -- attempt=%d result=0x%016llX elapsed_ms=%llu status=\"%s\" last_error=\"%s\"",
                preflight_attempt + 1,
                static_cast<unsigned long long>(preflight_result),
                static_cast<unsigned long long>(GetTickCount64() - preflight_started),
                driver_bridge::status().c_str(),
                driver_bridge::last_error().c_str());
            if (preflight_result != 0)
                break;
            if (preflight_attempt + 1 < 3)
                Sleep(100);
        }
        const std::uint64_t preflight_elapsed = GetTickCount64() - preflight_started;
        const bool preflight_after_ok = testlab_read_remote_exact(pid, observed_struct_va, struct_preflight_read_size, preflight_after, preflight_after_reason);
        driver_bridge::memory_region_t preflight_region_after{};
        const bool preflight_region_after_ok = driver_bridge::query_memory_for(pid, observed_struct_va, preflight_region_after);
        const std::string preflight_region_after_error = preflight_region_after_ok ? std::string() : driver_bridge::last_error();
        const bool preflight_diag_after_ok = test_coverage_domains_1_8_read_struct_mutation_diag(pid, desc, preflight_diag_after, preflight_diag_after_reason);
        const bool struct_mutation_preflight_ok =
            preflight_result != 0 &&
            preflight_before_ok &&
            preflight_after_ok &&
            preflight_before != preflight_after;
        log_msg(hf, tag, "STRUCT-MUTATION-PREFLIGHT -- ok=%d pid=%u active_pid=%u fn=0x%016llX result=0x%016llX elapsed_ms=%llu before_ok=%d after_ok=%d changed=%d read_size=%zu status=\"%s\" last_error=\"%s\" before_reason=%s after_reason=%s",
            struct_mutation_preflight_ok ? 1 : 0,
            pid,
            driver_bridge::attached_pid(),
            static_cast<unsigned long long>(desc.mutate_struct_fn_va),
            static_cast<unsigned long long>(preflight_result),
            static_cast<unsigned long long>(preflight_elapsed),
            preflight_before_ok ? 1 : 0,
            preflight_after_ok ? 1 : 0,
            preflight_before != preflight_after ? 1 : 0,
            struct_preflight_read_size,
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str(),
            preflight_before_reason.empty() ? "<empty>" : compact_text(preflight_before_reason, 500).c_str(),
            preflight_after_reason.empty() ? "<empty>" : compact_text(preflight_after_reason, 500).c_str());
        log_msg(hf, tag, "STRUCT-MUTATION-PREFLIGHT-DIAG -- pid=%u active_pid=%u diag_va=0x%016llX diag_size=%llu before_diag_ok=%d after_diag_ok=%d before_call_count=%u after_call_count=%u last_index=%u last_delta=%u struct_array=0x%016llX selected=0x%016llX result=0x%016llX before_hash=0x%016llX after_hash=0x%016llX null_array=%u out_of_range=%u last_error_code=%u expected_result=0x%016llX result_matches=%d region_before_ok=%d region_before_base=0x%016llX region_before_size=0x%016llX region_before_state=0x%08X region_before_protect=0x%08X region_after_ok=%d region_after_base=0x%016llX region_after_size=0x%016llX region_after_state=0x%08X region_after_protect=0x%08X byte_before=%s byte_after=%s before_reason=%s after_reason=%s region_before_error=%s region_after_error=%s",
            pid,
            driver_bridge::attached_pid(),
            static_cast<unsigned long long>(desc.reserved[0]),
            static_cast<unsigned long long>(desc.reserved[1]),
            preflight_diag_before_ok ? 1 : 0,
            preflight_diag_after_ok ? 1 : 0,
            preflight_diag_before.call_count,
            preflight_diag_after.call_count,
            preflight_diag_after.last_index,
            preflight_diag_after.last_delta,
            static_cast<unsigned long long>(preflight_diag_after.struct_array_va),
            static_cast<unsigned long long>(preflight_diag_after.selected_struct_va),
            static_cast<unsigned long long>(preflight_diag_after.result_va),
            static_cast<unsigned long long>(preflight_diag_after.before_hash),
            static_cast<unsigned long long>(preflight_diag_after.after_hash),
            preflight_diag_after.null_array,
            preflight_diag_after.out_of_range,
            preflight_diag_after.last_error_code,
            static_cast<unsigned long long>(observed_struct_va),
            preflight_diag_after.result_va == observed_struct_va ? 1 : 0,
            preflight_region_before_ok ? 1 : 0,
            static_cast<unsigned long long>(preflight_region_before.base),
            static_cast<unsigned long long>(preflight_region_before.size),
            preflight_region_before.state,
            preflight_region_before.protect,
            preflight_region_after_ok ? 1 : 0,
            static_cast<unsigned long long>(preflight_region_after.base),
            static_cast<unsigned long long>(preflight_region_after.size),
            preflight_region_after.state,
            preflight_region_after.protect,
            hex_preview(preflight_before, 64).c_str(),
            hex_preview(preflight_after, 64).c_str(),
            preflight_diag_before_reason.empty() ? "<empty>" : compact_text(preflight_diag_before_reason, 500).c_str(),
            preflight_diag_after_reason.empty() ? "<empty>" : compact_text(preflight_diag_after_reason, 500).c_str(),
            preflight_region_before_error.empty() ? "<empty>" : compact_text(preflight_region_before_error, 500).c_str(),
            preflight_region_after_error.empty() ? "<empty>" : compact_text(preflight_region_after_error, 500).c_str());

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["base_va"] = test_coverage_domains_1_8_hex_ptr(observed_struct_va);
            args["size"] = desc.struct_size;
            args["duration_sec"] = 1;
            args[k_test_lab_safe_fixture_flag] = true;
            test_coverage_domains_1_8_case(hf, tag, "struct_observe", "observe_requires_confirm", args, 2500,
                [](const invoke_result_t& ir, std::string& reason) {
                    return test_coverage_domains_1_8_expect_error_any(ir, {"confirm_unsafe", "Unsafe operation"}, reason);
                }, passed, failed);
        }

        auto observe_case = [&](const char* case_name, std::uint32_t index, std::uint32_t delta, std::string& snapshot_id) {
            if (cancelled && cancelled())
                return;
            auto stim_done = std::make_shared<std::atomic<bool>>(false);
            auto stim_calls = std::make_shared<std::atomic<std::uint32_t>>(0);
            auto stim_failures = std::make_shared<std::atomic<std::uint32_t>>(0);
            const std::string stim_case = case_name ? case_name : "";
            bool stim_posted = false;
            try {
                aida::infra::executor::submission_t sub;
                sub.owner_subsystem = "testlab_mcp";
                sub.label = "testlab.struct_observe.stimulus";
                sub.thread_class = "bounded_task";
                sub.domain = aida::infra::executor::domain_t::feature_worker;
                sub.priority = 3;
                sub.failure_policy = "reject_not_started";
                sub.shutdown_policy = "drain";
                sub.body = [pid, fn = desc.mutate_struct_fn_va, index, delta, stim_case, stim_done, stim_calls, stim_failures]() {
                    try {
                        for (std::uint32_t i = 0; i < 5; ++i) {
                            Sleep(100);
                            if (fn != 0) {
                                const uint64_t result = page_guard_engine::remote_thread_call(pid, fn, index, delta + i, 0, 0, 3000, "aida_test_re_mutate_struct_observe");
                                stim_calls->fetch_add(1, std::memory_order_relaxed);
                                if (result == 0)
                                    stim_failures->fetch_add(1, std::memory_order_relaxed);
                            }
                        }
                    } catch (const std::exception& ex) {
                        stim_failures->fetch_add(1, std::memory_order_relaxed);
                        diag::log_tagged_fmt("test_all_mcp", "struct_observe stimulus exception case=%s err=%s", stim_case.c_str(), ex.what());
                    } catch (...) {
                        stim_failures->fetch_add(1, std::memory_order_relaxed);
                        diag::log_tagged_fmt("test_all_mcp", "struct_observe stimulus exception case=%s err=<unknown>", stim_case.c_str());
                    }
                    stim_done->store(true, std::memory_order_release);
                };
                stim_posted = aida::infra::executor::submit(std::move(sub)).submitted;
            } catch (const std::exception& ex) {
                log_msg(hf, tag, "FAIL -- struct_observe stimulus post threw case=%s err=%s", case_name ? case_name : "", ex.what());
            } catch (...) {
                log_msg(hf, tag, "FAIL -- struct_observe stimulus post threw case=%s err=<unknown>", case_name ? case_name : "");
            }
            if (!stim_posted) {
                test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_observe", "stimulus worker unavailable for fixture mutation", failed);
                return;
            }
            if (!wait_struct_monitor_idle((stim_case + "_pre").c_str(), 10000)) {
                test_coverage_domains_1_8_fixture_fail(hf, tag, "struct_observe", "previous struct monitor remained active before case " + stim_case, failed);
                stim_done->store(true, std::memory_order_release);
                return;
            }
            mcp_standalone::json args = test_coverage_domains_1_8_safe_args();
            args["process_id"] = pid;
            args["base_va"] = test_coverage_domains_1_8_hex_ptr(observed_struct_va);
            args["size"] = desc.struct_size;
            args["duration_sec"] = 1;
            args["timeout_ms"] = 15000;
            invoke_result_t out;
            const int pass_before = passed.load(std::memory_order_acquire);
            test_coverage_domains_1_8_case(hf, tag, "struct_observe", case_name, args, 17000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "struct_observe failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    std::string id;
                    uint64_t fields = 0;
                    if (!payload_string_field(ir.data, "snapshot_id", id) || id.empty()) {
                        reason = "snapshot_id missing";
                        return false;
                    }
                    if (!payload_u64_field(ir.data, "field_count", fields) || fields == 0) {
                        reason = "field_count missing or zero; fixture access stimulus did not produce inferred fields data=" + compact_json(ir.data, 800);
                        return false;
                    }
                    return true;
                }, passed, failed, &out);
            const int pass_after = passed.load(std::memory_order_acquire);
            const uint64_t wait_started_ms = GetTickCount64();
            while (!stim_done->load(std::memory_order_acquire) && GetTickCount64() - wait_started_ms < 6000)
                Sleep(10);
            const bool stimulus_valid =
                stim_done->load(std::memory_order_acquire) &&
                stim_calls->load(std::memory_order_relaxed) > 0 &&
                stim_failures->load(std::memory_order_relaxed) < stim_calls->load(std::memory_order_relaxed);
            log_msg(hf, tag, "struct_observe stimulus case=%s done=%d calls=%u failures=%u wait_ms=%llu",
                case_name ? case_name : "",
                stim_done->load(std::memory_order_acquire) ? 1 : 0,
                stim_calls->load(std::memory_order_relaxed),
                stim_failures->load(std::memory_order_relaxed),
                static_cast<unsigned long long>(GetTickCount64() - wait_started_ms));
            wait_struct_monitor_idle((stim_case + "_post").c_str(), 12000);
            if (!stimulus_valid && pass_after > pass_before) {
                log_msg(hf, tag, "FAIL -- struct_observe functional pass invalidated by stimulus evidence case=%s done=%d calls=%u failures=%u",
                    case_name ? case_name : "",
                    stim_done->load(std::memory_order_acquire) ? 1 : 0,
                    stim_calls->load(std::memory_order_relaxed),
                    stim_failures->load(std::memory_order_relaxed));
                convert_last_pass_to_fixture_failure("struct_observe", passed, failed);
                return;
            }
            if (out.success)
                payload_string_field(out.data, "snapshot_id", snapshot_id);
        };

        std::string snapshot_a;
        std::string snapshot_b;
        bool struct_mutation_readback_ok = false;
        if (struct_mutation_preflight_ok) {
            observe_case("observe_fixture_struct_before_mutation", 0, 3, snapshot_a);
            std::vector<std::uint8_t> struct_before;
            std::vector<std::uint8_t> struct_after;
            std::string struct_read_reason;
            const std::size_t struct_read_size = std::min<std::size_t>(static_cast<std::size_t>(desc.struct_size), 128);
            const bool struct_before_ok = testlab_read_remote_exact(pid, observed_struct_va, struct_read_size, struct_before, struct_read_reason);
            const std::uint64_t mutate_between_result = page_guard_engine::remote_thread_call(pid, desc.mutate_struct_fn_va, 0, 9, 0, 0, 3000, "aida_test_re_mutate_struct_between_snapshots");
            std::string struct_after_reason;
            const bool struct_after_ok = testlab_read_remote_exact(pid, observed_struct_va, struct_read_size, struct_after, struct_after_reason);
            struct_mutation_readback_ok = mutate_between_result != 0 && struct_before_ok && struct_after_ok && struct_before != struct_after;
            log_msg(hf, tag, "STRUCT-MUTATION-READBACK -- result=0x%016llX before_ok=%d after_ok=%d changed=%d read_size=%zu before_reason=%s after_reason=%s",
                static_cast<unsigned long long>(mutate_between_result),
                struct_before_ok ? 1 : 0,
                struct_after_ok ? 1 : 0,
                struct_mutation_readback_ok ? 1 : 0,
                struct_read_size,
                struct_read_reason.empty() ? "<empty>" : compact_text(struct_read_reason, 500).c_str(),
                struct_after_reason.empty() ? "<empty>" : compact_text(struct_after_reason, 500).c_str());
            if (!struct_mutation_readback_ok) {
                test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "struct_compare_snapshots",
                    "mutate_struct readback failed result=" + hex_u64(mutate_between_result) +
                    " before_ok=" + std::to_string(struct_before_ok ? 1 : 0) +
                    " after_ok=" + std::to_string(struct_after_ok ? 1 : 0) +
                    " changed=0",
                    "struct_observe", "struct_snapshot_mutation_readback_failed", failed);
            }
            observe_case("observe_fixture_struct_after_mutation", 0, 11, snapshot_b);
        } else {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "struct_observe",
                "mutate_struct preflight failed result=" + hex_u64(preflight_result) +
                " before_ok=" + std::to_string(preflight_before_ok ? 1 : 0) +
                " after_ok=" + std::to_string(preflight_after_ok ? 1 : 0) +
                " changed=0",
                "struct_mutation_preflight", "struct_mutation_preflight_failed", failed);
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "struct_compare_snapshots",
                "mutate_struct preflight failed result=" + hex_u64(preflight_result) +
                " before_ok=" + std::to_string(preflight_before_ok ? 1 : 0) +
                " after_ok=" + std::to_string(preflight_after_ok ? 1 : 0) +
                " changed=0",
                "struct_mutation_preflight", "struct_mutation_preflight_failed", failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["max_span"] = desc.struct_size;
            args["field_addresses"] = mcp_standalone::json::array({
                mcp_standalone::json{{"name", "id"}, {"va", test_coverage_domains_1_8_hex_ptr(observed_struct_va)}},
                mcp_standalone::json{{"name", "owner"}, {"va", test_coverage_domains_1_8_hex_ptr(observed_struct_va + 8)}},
                mcp_standalone::json{{"name", "health"}, {"va", test_coverage_domains_1_8_hex_ptr(observed_struct_va + 40)}},
                mcp_standalone::json{{"name", "name"}, {"va", test_coverage_domains_1_8_hex_ptr(observed_struct_va + 48)}}
            });
            test_coverage_domains_1_8_case(hf, tag, "struct_correlate", "correlate_fixture_field_addresses", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "struct_correlate failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    size_t fields = 0;
                    if (!payload_array_count(ir.data, "fields", fields) || fields < 4) {
                        reason = "fields array missing or too small data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (!cancelled || !cancelled()) {
            mcp_standalone::json args;
            args["process_id"] = pid;
            args["base_va"] = test_coverage_domains_1_8_hex_ptr(desc.struct_array_va);
            args["suspected_size"] = desc.struct_size;
            args["max_elements"] = std::min<std::uint32_t>(desc.struct_count, 16);
            test_coverage_domains_1_8_case(hf, tag, "struct_array_detect", "detect_fixture_struct_array", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "struct_array_detect failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    bool is_array = false;
                    uint64_t elements = 0;
                    if (!payload_bool_field(ir.data, "is_array", is_array) || !is_array ||
                        !payload_u64_field(ir.data, "element_count", elements) || elements < 3) {
                        reason = "expected is_array=true and element_count>=3 data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        }

        if (struct_mutation_readback_ok && !snapshot_a.empty() && !snapshot_b.empty() && (!cancelled || !cancelled())) {
            mcp_standalone::json args;
            args["snapshot_a_id"] = snapshot_a;
            args["snapshot_b_id"] = snapshot_b;
            args["base_va"] = test_coverage_domains_1_8_hex_ptr(observed_struct_va);
            args["struct_size"] = desc.struct_size;
            test_coverage_domains_1_8_case(hf, tag, "struct_compare_snapshots", "compare_fixture_struct_snapshots", args, 3000,
                [](const invoke_result_t& ir, std::string& reason) {
                    if (!ir.success) {
                        reason = "struct_compare_snapshots failed text=" + compact_text(ir.text, 300);
                        return false;
                    }
                    uint64_t changes = 0;
                    if (!payload_u64_field(ir.data, "change_count", changes) || changes == 0) {
                        reason = "change_count missing or zero data=" + compact_json(ir.data, 700);
                        return false;
                    }
                    return true;
                }, passed, failed);
        } else if (struct_mutation_readback_ok) {
            test_coverage_domains_1_8_fixture_blocked_by(hf, tag, "struct_compare_snapshots", "struct_observe did not return two snapshot IDs", "struct_observe", "missing_two_struct_snapshot_ids", failed);
        }
        wait_timed_out_invocation_drain(hf, "coverage domains 1-8 struct postflight", 3000);
    }

