    void test_mcp_tool_schemas(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        (void)skipped;
        const char* tag = "mcp.tool_schemas";
        auto* srv = get_server();
        if (!srv) {
            log_msg(hf, tag, "SKIP -- no server instance");
            failed.fetch_add(1);
            return;
        }
        try {
            const auto& tools = srv->get_tools();
            int valid = 0;
            int hidden = 0;
            std::map<std::string, const mcp_standalone::tool_def_t*> by_name;
            for (const auto& tool : tools) {
                if (tool.visibility == mcp_standalone::tool_visibility_t::ide_chat_only) {
                    ++hidden;
                    continue;
                }
                if (tool.name.empty() || tool.description.empty() ||
                    (!tool.handler && !tool.workspace_handler))
                    throw std::runtime_error("general MCP definition is incomplete: " + tool.name);
                if (!by_name.emplace(tool.name, &tool).second)
                    throw std::runtime_error("duplicate MCP definition: " + tool.name);
                ++valid;
            }

            if (mcp_contract_compat::contract_count() !=
                    mcp_contract_compat::k_archive_tool_count ||
                mcp_contract_compat::k_archive_tool_count +
                    mcp_contract_compat::k_aida_extension_count !=
                    mcp_contract_compat::k_union_tool_count)
                throw std::runtime_error("generated MCP contract cardinality mismatch");
            const auto* descriptors = mcp_contract_compat::contracts();
            if (!descriptors)
                throw std::runtime_error("generated MCP descriptors are unavailable");
            std::set<std::string> union_names;
            for (std::size_t index = 0;
                 index < mcp_contract_compat::contract_count(); ++index) {
                const auto& descriptor = descriptors[index];
                const std::string name(descriptor.name);
                if (!union_names.emplace(name).second)
                    throw std::runtime_error("duplicate generated MCP contract: " + name);
                const auto found = by_name.find(name);
                if (found == by_name.end())
                    throw std::runtime_error("missing generated MCP registration: " + name);
                const auto input_schema = mcp_standalone::json::parse(
                    descriptor.input_schema_json.begin(), descriptor.input_schema_json.end());
                const auto output_schema = mcp_standalone::json::parse(
                    descriptor.output_schema_json.begin(), descriptor.output_schema_json.end());
                const auto annotations = mcp_standalone::json::parse(
                    descriptor.annotations_json.begin(), descriptor.annotations_json.end());
                const auto& tool = *found->second;
                if (tool.input_schema != input_schema ||
                    tool.output_schema != output_schema ||
                    tool.annotations != annotations ||
                    tool.read_only != descriptor.read_only ||
                    tool.visibility != mcp_standalone::tool_visibility_t::external_visible ||
                    tool.target_independent == descriptor.target_dependent ||
                    static_cast<bool>(tool.workspace_handler) != descriptor.target_dependent ||
                    static_cast<bool>(tool.handler) == descriptor.target_dependent)
                    throw std::runtime_error("generated MCP definition mismatch: " + name);
            }
            for (const auto extension : mcp_contract_compat::k_aida_extension_names) {
                const std::string name(extension);
                if (!union_names.emplace(name).second || by_name.count(name) != 1)
                    throw std::runtime_error("MCP extension registration mismatch: " + name);
                const auto& tool = *by_name.at(name);
                if (tool.input_schema.is_null() || tool.output_schema.is_null() ||
                    tool.annotations.is_null())
                    throw std::runtime_error("MCP extension definition is incomplete: " + name);
            }
            if (union_names.size() != mcp_contract_compat::k_union_tool_count ||
                by_name.count("py_eval") != 0 || by_name.at("infer_types")->read_only ||
                by_name.at("analyze_funcs")->read_only)
                throw std::runtime_error("excluded tool or mutation classification mismatch");

            const auto rejection = srv->call_registered_tool("int_convert",
                mcp_standalone::json{{"unexpected", true}}, true);
            if (rejection.success || rejection.error_code != "MCP_TOOL_INPUT_SCHEMA_INVALID")
                throw std::runtime_error("int_convert pre-dispatch schema validation failed");
            const auto conversion = srv->call_registered_tool("int_convert",
                mcp_standalone::json{{"inputs", mcp_standalone::json{{"text", "42"}}}}, true);
            if (!conversion.success || !conversion.data.is_object() ||
                conversion.data.contains("_meta") ||
                !conversion.data.contains("result") ||
                !conversion.data["result"].is_array() ||
                conversion.data["result"].size() != 1 ||
                conversion.data["result"][0].value("input", std::string()) != "42" ||
                conversion.data["result"][0]["result"].value(
                    "decimal", std::string()) != "42" ||
                !conversion.meta.contains("aida"))
                throw std::runtime_error("int_convert production handler failed");
            const mcp_standalone::json calculation = {
                {"expression", "(1 << 65) + 3"}, {"format", "decimal"}
            };
            const auto calculator = srv->call_registered_tool("calculator", calculation, true);
            const auto calculate = srv->call_registered_tool("calculate", calculation, true);
            if (!calculator.success || !calculate.success || calculator.data != calculate.data ||
                calculator.data.value("value", std::string()) != "36893488147419103235")
                throw std::runtime_error("calculator alias production handlers diverged");
            const auto scalar = srv->call_registered_tool("calculator", mcp_standalone::json{
                {"items", mcp_standalone::json{{"id", "scalar"},
                                                {"expression", "6 * 7"},
                                                {"format", "decimal"}}}
            }, true);
            if (!scalar.success || scalar.data.value("count", 0u) != 1 ||
                !scalar.data["results"].is_array() || scalar.data["results"].size() != 1 ||
                scalar.data["results"][0].value("id", std::string()) != "scalar" ||
                !scalar.data["results"][0].value("success", false))
                throw std::runtime_error("calculator scalar item normalization failed");
            const auto instances = srv->call_registered_tool("list_instances",
                mcp_standalone::json::object(), true);
            if (!instances.success || !instances.data.contains("instances") ||
                !instances.data["instances"].is_array() ||
                instances.data.contains("count") || instances.data.contains("_meta") ||
                std::any_of(instances.data["instances"].begin(),
                    instances.data["instances"].end(), [](const auto& instance) {
                        return !instance.is_object() || instance.size() != 2 ||
                            !instance.contains("pid") || !instance.contains("bin_name");
                    }))
                throw std::runtime_error("list_instances production handler failed");

            log_msg(hf, tag,
                "PASS -- general=%d hidden=%d generated=%zu extensions=%zu union=%zu exact_input_output_annotations=true handler_smoke=int_convert,list_instances,calculator,calculate",
                valid, hidden, mcp_contract_compat::k_archive_tool_count,
                mcp_contract_compat::k_aida_extension_count,
                mcp_contract_compat::k_union_tool_count);
            passed.fetch_add(1);
        } catch (const std::exception& ex) {
            log_msg(hf, tag, "FAIL -- %s", ex.what());
            failed.fetch_add(1);
        }
    }

    void test_mcp_duplicate_tool_names(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        const char* tag = "mcp.duplicate_tool_names";
        auto* srv = get_server();
        if (!srv) {
            log_msg(hf, tag, "SKIP -- no server instance");
            failed.fetch_add(1);
            return;
        }

        std::map<std::string, int> counts;
        int hidden = 0;
        for (const auto& t : srv->get_tools()) {
            if (t.visibility == mcp_standalone::tool_visibility_t::ide_chat_only) {
                ++hidden;
                continue;
            }
            counts[t.name]++;
        }

        int duplicates = 0;
        for (const auto& kv : counts) {
            if (kv.second > 1) {
                duplicates += kv.second - 1;
                log_msg(hf, tag, "DUPLICATE -- tool \"%s\" registered %d times; direct tests exercise only the first handler",
                    kv.first.c_str(), kv.second);
            }
        }

        if (duplicates == 0) {
            log_msg(hf, tag, "PASS -- %zu general MCP tool names are unique ide_chat_only_hidden=%d", counts.size(), hidden);
            passed.fetch_add(1);
        } else {
            log_msg(hf, tag, "FAIL -- %d duplicate MCP tool registration(s) across %zu unique names ide_chat_only_hidden=%d",
                duplicates, counts.size(), hidden);
            failed.fetch_add(1);
        }
    }

    void test_mcp_jsonrpc_smoke(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        const char* tag = "mcp.jsonrpc_smoke";
        auto* srv = get_server();
        if (!srv) {
            log_msg(hf, tag, "SKIP -- no server instance");
            failed.fetch_add(1);
            return;
        }
        std::string lifecycle_reason;
        if (!srv->is_running() || !mcp_standalone::lifecycle_authorized(&lifecycle_reason)) {
            log_msg(hf, tag, "FAIL -- JSON-RPC smoke requires running authorized MCP server running=%d reason=%s",
                srv->is_running() ? 1 : 0,
                lifecycle_reason.empty() ? "unknown" : lifecycle_reason.c_str());
            failed.fetch_add(1);
            return;
        }

        try {
            mcp_standalone::json init_req = {
                {"jsonrpc", "2.0"},
                {"id", 1},
                {"method", "initialize"},
                {"params", mcp_standalone::json::object()}
            };
            auto init_resp = mcp_standalone::json::parse(mcp_standalone::handle_body(srv, init_req.dump()));
            if (!init_resp.contains("result") || !init_resp["result"].contains("serverInfo")) {
                log_msg(hf, tag, "FAIL -- initialize response missing result.serverInfo");
                failed.fetch_add(1);
                return;
            }

            mcp_standalone::json list_req = {
                {"jsonrpc", "2.0"},
                {"id", 2},
                {"method", "tools/list"},
                {"params", {{"detail", "full"}}}
            };
            auto list_resp = mcp_standalone::json::parse(mcp_standalone::handle_body(srv, list_req.dump()));
            if (!list_resp.contains("result") || !list_resp["result"].contains("tools") ||
                !list_resp["result"]["tools"].is_array() ||
                list_resp["result"]["_meta"].value("aidaToolListMode", std::string()) != "full") {
                log_msg(hf, tag, "FAIL -- tools/list response missing result.tools array");
                failed.fetch_add(1);
                return;
            }
            std::map<std::string, mcp_standalone::json> listed_tools;
            for (const auto& tool : list_resp["result"]["tools"]) {
                if (!tool.contains("name") || !tool["name"].is_string())
                    continue;
                const std::string listed_name = tool["name"].get<std::string>();
                if (!listed_tools.emplace(listed_name, tool).second) {
                    log_msg(hf, tag, "FAIL -- tools/list returned duplicate tool \"%s\"",
                        listed_name.c_str());
                    failed.fetch_add(1);
                    return;
                }
                if (listed_name == "py_eval") {
                    log_msg(hf, tag, "FAIL -- tools/list exposed excluded py_eval");
                    failed.fetch_add(1);
                    return;
                }
                if (is_ai_related_mcp_tool(listed_name)) {
                    log_msg(hf, tag, "FAIL -- tools/list exposed internal AI/workflow tool \"%s\"",
                        listed_name.c_str());
                    failed.fetch_add(1);
                    return;
                }
                if (!tool.contains("description") || !tool["description"].is_string() ||
                    tool["description"].get<std::string>().empty()) {
                    log_msg(hf, tag, "FAIL -- tools/list exposed tool \"%s\" without a description",
                        listed_name.c_str());
                    failed.fetch_add(1);
                    return;
                }
            }

            const auto* descriptors = mcp_contract_compat::contracts();
            if (!descriptors || mcp_contract_compat::contract_count() !=
                    mcp_contract_compat::k_archive_tool_count) {
                log_msg(hf, tag, "FAIL -- generated contract inventory unavailable");
                failed.fetch_add(1);
                return;
            }
            for (std::size_t index = 0;
                 index < mcp_contract_compat::contract_count(); ++index) {
                const auto& descriptor = descriptors[index];
                const std::string name(descriptor.name);
                const auto found = listed_tools.find(name);
                const auto input_schema = mcp_standalone::json::parse(
                    descriptor.input_schema_json.begin(), descriptor.input_schema_json.end());
                const auto output_schema = mcp_standalone::json::parse(
                    descriptor.output_schema_json.begin(), descriptor.output_schema_json.end());
                const auto annotations = mcp_standalone::json::parse(
                    descriptor.annotations_json.begin(), descriptor.annotations_json.end());
                if (found == listed_tools.end() ||
                    found->second.value("read_only", !descriptor.read_only) !=
                        descriptor.read_only ||
                    found->second.value("visibility", std::string()) != "external_visible" ||
                    !found->second.contains("inputSchema") ||
                    found->second["inputSchema"] != input_schema ||
                    !found->second.contains("outputSchema") ||
                    found->second["outputSchema"] != output_schema ||
                    !found->second.contains("annotations") ||
                    found->second["annotations"] != annotations) {
                    log_msg(hf, tag,
                        "FAIL -- tools/list generated contract mismatch tool=%s",
                        name.c_str());
                    failed.fetch_add(1);
                    return;
                }
            }

            mcp_standalone::json call_req = {
                {"jsonrpc", "2.0"},
                {"id", 3},
                {"method", "tools/call"},
                {"params", {
                    {"name", "int_convert"},
                    {"arguments", mcp_standalone::json{
                        {"inputs", mcp_standalone::json{{"text", "42"}}}
                    }}
                }}
            };
            auto call_resp = mcp_standalone::json::parse(mcp_standalone::handle_body(srv, call_req.dump()));
            if (!call_resp.contains("result") ||
                !call_resp["result"].contains("structuredContent") ||
                !call_resp["result"]["structuredContent"].is_object() ||
                call_resp["result"]["structuredContent"].contains("_meta") ||
                !call_resp["result"].contains("_meta") ||
                !call_resp["result"]["_meta"].contains("aida") ||
                !call_resp["result"]["_meta"]["aida"].is_object() ||
                call_resp["result"].value("isError", false)) {
                log_msg(hf, tag,
                    "FAIL -- successful tools/call omitted structuredContent or top-level _meta.aida");
                failed.fetch_add(1);
                return;
            }

            mcp_standalone::json resources_req = {
                {"jsonrpc", "2.0"},
                {"id", 4},
                {"method", "resources/list"},
                {"params", mcp_standalone::json::object()}
            };
            auto resources_resp = mcp_standalone::json::parse(mcp_standalone::handle_body(srv, resources_req.dump()));
            if (!resources_resp.contains("result") ||
                !resources_resp["result"].contains("resources") ||
                !resources_resp["result"]["resources"].is_array()) {
                log_msg(hf, tag, "FAIL -- resources/list response missing result.resources array");
                failed.fetch_add(1);
                return;
            }

            std::set<std::string> resources_seen;
            for (const auto& res : resources_resp["result"]["resources"]) {
                if (res.contains("uri") && res["uri"].is_string()) {
                    const std::string uri = res["uri"].get<std::string>();
                    if (uri.rfind("ida://", 0) == 0) {
                        log_msg(hf, tag, "FAIL -- resources/list exposed excluded URI %s", uri.c_str());
                        failed.fetch_add(1);
                        return;
                    }
                    resources_seen.insert(uri);
                }
            }

            const char* required_resources[] = {
                "standalone://driver-status",
                "standalone://loaded-file"
            };
            for (int i = 0; i < 2; ++i) {
                const char* uri = required_resources[i];
                if (resources_seen.find(uri) == resources_seen.end()) {
                    log_msg(hf, tag, "FAIL -- resources/list missing required uri %s", uri);
                    failed.fetch_add(1);
                    return;
                }
                mcp_standalone::json read_req = {
                    {"jsonrpc", "2.0"},
                    {"id", 5 + i},
                    {"method", "resources/read"},
                    {"params", {{"uri", uri}}}
                };
                auto read_resp = mcp_standalone::json::parse(mcp_standalone::handle_body(srv, read_req.dump()));
                if (!read_resp.contains("result") ||
                    !read_resp["result"].contains("contents") ||
                    !read_resp["result"]["contents"].is_array() ||
                    read_resp["result"]["contents"].empty()) {
                    log_msg(hf, tag, "FAIL -- resources/read response for %s missing result.contents", uri);
                    failed.fetch_add(1);
                    return;
                }
            }

            log_msg(hf, tag, "PASS -- initialize/tools-list/tools-call/resources-list/resources-read JSON-RPC path responded; external_tools=%zu resources=%zu",
                list_resp["result"]["tools"].size(),
                resources_resp["result"]["resources"].size());
            passed.fetch_add(1);
        } catch (const std::exception& ex) {
            log_msg(hf, tag, "FAIL -- JSON-RPC smoke threw: %s", ex.what());
            failed.fetch_add(1);
        }
    }

    void test_tool_get_tool_descriptions(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        (void)skipped;
        const char* tag = "mcp.get_tool_descriptions";
        mcp_standalone::json args;
        args["names"] = mcp_standalone::json::array({"get_tool_descriptions", "sessions_manage", "switch_agent"});
        args["include_schema"] = true;
        g_invoked_tools.insert("get_tool_descriptions");
        auto timed = invoke_tool_bounded(get_server(), "get_tool_descriptions", args, tool_timeout_ms("get_tool_descriptions"));
        auto& ir = timed.result;
        if (timed.timed_out || !ir.found || ir.threw || !ir.success) {
            log_msg(hf, tag, "FAIL -- get_tool_descriptions dispatch failed found=%s threw=%s success=%s timeout=%s err=%s",
                ir.found ? "true" : "false",
                ir.threw ? "true" : "false",
                ir.success ? "true" : "false",
                timed.timed_out ? "true" : "false",
                ir.exception_msg.c_str());
            record_tool_status("get_tool_descriptions", mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return;
        }
        const std::string text_lc = lower_copy(ir.text);
        const bool has_self = text_lc.find("### get_tool_descriptions") != std::string::npos;
        const bool has_sessions_manage = text_lc.find("### sessions_manage") != std::string::npos;
        const bool leaked_internal = text_lc.find("### switch_agent") != std::string::npos;
        const bool has_schema = text_lc.find("`names`") != std::string::npos &&
            text_lc.find("include_schema") != std::string::npos;
        if (has_self && has_sessions_manage && has_schema && !leaked_internal) {
            log_msg(hf, tag, "PASS -- returned detailed schemas for selected tools");
            record_tool_status("get_tool_descriptions", mcp_tool_call_status_t::passed);
            passed.fetch_add(1);
            return;
        }
        log_msg(hf, tag, "FAIL -- response missing expected detail self=%s sessions_manage=%s schema=%s leaked_internal=%s text=%s",
            has_self ? "true" : "false",
            has_sessions_manage ? "true" : "false",
            has_schema ? "true" : "false",
            leaked_internal ? "true" : "false",
            compact_text(ir.text, 900).c_str());
        record_tool_status("get_tool_descriptions", mcp_tool_call_status_t::failed);
        failed.fetch_add(1);
    }

    void test_mcp_coverage_audit(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        const char* tag = "mcp.coverage_audit";
        set_progress_step("mcp finalization: coverage audit");
        auto* srv = get_server();
        if (!srv) {
            (void)skipped;
            log_msg(hf, tag, "FAIL -- no server instance");
            mcp_coverage_audit_snapshot_t snapshot;
            snapshot.audit_started = true;
            snapshot.audit_completed = true;
            snapshot.audit_clean = false;
            snapshot.failed_tools = 1;
            record_mcp_phase_gap("mcp_audit.no_server", "mcp_server", "no server instance");
            store_mcp_audit_snapshot(snapshot);
            failed.fetch_add(1);
            return;
        }

        const auto cq_begin = aida::infra::taskflow_runtime::domain_stats(aida::infra::taskflow_runtime::executor_domain_t::critical);
        log_msg(hf, tag, "BEGIN -- tool_status_records=%zu explicit_invocations=%zu timed_out_records=%zu cq_pending=%zu cq_active=%u cq_started=%llu cq_finished=%llu",
            g_tool_attempt_stats.size(),
            g_invoked_tools.size(),
            copy_timed_out_invocations().size(),
            cq_begin.pending,
            static_cast<unsigned>(cq_begin.active),
            static_cast<unsigned long long>(cq_begin.started),
            static_cast<unsigned long long>(cq_begin.finished));
        const bool timed_out_drain_complete = wait_timed_out_invocation_drain(hf, "coverage audit precheck", 5000);
        const size_t outstanding_timed_out_workers = prune_completed_timed_out_invocations();

        std::set<std::string> registered;
        std::set<std::string> registered_all;
        int registered_total = 0;
        int registered_external = 0;
        int registered_internal = 0;
        int registered_ide_chat = 0;
        int destructive_schema_tools = 0;
        int destructive_schema_exemptions = 0;
        int destructive_schema_exempt_covered = 0;
        int non_ai_audited = 0;
        int covered = 0;
        int attempted = 0;
        int passed_tools = 0;
        int schema_pass_tools = 0;
        int contract_pass_tools = 0;
        int cleanup_contract_pass_tools = 0;
        int state_contract_pass_tools = 0;
        int accepted_pending_tools = 0;
        int guard_pass_tools = 0;
        int security_guard_pass_tools = 0;
        int security_guard_covered = 0;
        int negative_pass_tools = 0;
        int failed_tools = 0;
        int mixed_fail_tools = 0;
        int dependency_blocked_tools = 0;
        int cascade_blocked_tools = 0;
        int skipped_tools = 0;
        int timed_out_tools = 0;
        int no_pass = 0;
        int skipped_ai = 0;
        int missing = 0;
        int empty_result_suspect_tools = 0;
        int unexpected_zero_pass_tools = 0;
        int expected_empty_nonfunctional_tools = 0;
        int diagnostic_fallback_tools = 0;
        int diagnostic_fallback_functional_tools = 0;
        for (const auto& t : srv->get_tools()) {
            if (!registered_all.insert(t.name).second)
                continue;
            if (t.visibility == mcp_standalone::tool_visibility_t::ide_chat_only) {
                ++registered_ide_chat;
                continue;
            }
            ++registered_total;
            if (t.visibility == mcp_standalone::tool_visibility_t::internal_only)
                ++registered_internal;
            else
                ++registered_external;
            if (is_destructive_mcp_tool(t.name))
                ++destructive_schema_tools;
            if (mcp_tool_has_destructive_schema_only_exemption(t.name))
                ++destructive_schema_exemptions;
            if (is_ai_related_mcp_tool(t.name)) {
                ++skipped_ai;
                continue;
            }
            registered.insert(t.name);
            ++non_ai_audited;
            auto stats_it = g_tool_attempt_stats.find(t.name);
            if (stats_it != g_tool_attempt_stats.end() && stats_it->second.attempted > 0) {
                ++attempted;
                const auto& st = stats_it->second;
                if (st.schema_passed > 0)
                    ++schema_pass_tools;
                if (st.contract_passed > 0)
                    ++contract_pass_tools;
                if (st.cleanup_contract_passed > 0)
                    ++cleanup_contract_pass_tools;
                if (st.state_contract_passed > 0)
                    ++state_contract_pass_tools;
                if (st.accepted_pending > 0)
                    ++accepted_pending_tools;
                if (st.guard_passed > 0)
                    ++guard_pass_tools;
                if (st.security_guard_passed > 0)
                    ++security_guard_pass_tools;
                if (st.negative_passed > 0)
                    ++negative_pass_tools;
                const bool destructive_exempt = mcp_tool_has_destructive_schema_only_exemption(t.name);
                const bool safe_external_guard_exempt = mcp_tool_has_safe_external_guard_exemption(t.name);
                const bool nonfunctional_evidence =
                    st.schema_passed > 0 ||
                    st.contract_passed > 0 ||
                    st.cleanup_contract_passed > 0 ||
                    st.state_contract_passed > 0 ||
                    st.accepted_pending > 0 ||
                    st.guard_passed > 0 ||
                    st.security_guard_passed > 0 ||
                    st.negative_passed > 0;
                const bool clean_nonfunctional_contract =
                    st.failed == 0 &&
                    st.timed_out == 0 &&
                    st.skipped == 0 &&
                    st.dependency_blocked == 0 &&
                    st.cascade_blocked == 0;
                const bool destructive_safe_contract_proof =
                    destructive_exempt &&
                    clean_nonfunctional_contract &&
                    (st.schema_passed > 0 || st.contract_passed > 0 || st.guard_passed > 0);
                const bool guard_only_safe_contract_proof =
                    safe_external_guard_exempt &&
                    st.security_guard_passed > 0 &&
                    st.passed == 0;
                const auto expected_reason_it_for_tool = g_mcp_expected_empty_reasons.find(t.name);
                const auto contract_reason_it_for_tool = g_mcp_nonfunctional_contract_reasons.find(t.name);
                std::string state_contract_reason_for_tool;
                if (expected_reason_it_for_tool != g_mcp_expected_empty_reasons.end())
                    state_contract_reason_for_tool = expected_reason_it_for_tool->second;
                if (contract_reason_it_for_tool != g_mcp_nonfunctional_contract_reasons.end()) {
                    if (!state_contract_reason_for_tool.empty())
                        state_contract_reason_for_tool += " ";
                    state_contract_reason_for_tool += contract_reason_it_for_tool->second;
                }
                const std::string state_contract_reason_lc = lower_copy(state_contract_reason_for_tool);
                const auto diagnostic_fallback_it_for_tool = g_mcp_diagnostic_fallback_tools.find(t.name);
                const auto diagnostic_fallback_reason_it_for_tool = g_mcp_diagnostic_fallback_reasons.find(t.name);
                const bool diagnostic_fallback_evidence = diagnostic_fallback_it_for_tool != g_mcp_diagnostic_fallback_tools.end();
                if (diagnostic_fallback_evidence) {
                    ++diagnostic_fallback_tools;
                    if (st.passed > 0)
                        ++diagnostic_fallback_functional_tools;
                }
                const bool seh_x64_state_contract_covered =
                    (t.name == "debugger_get_seh_chain" || t.name == "dbg_get_seh_chain") &&
                    clean_nonfunctional_contract &&
                    st.state_contract_passed > 0 &&
                    st.passed == 0 &&
                    (state_contract_reason_lc.find("x64_empty_chain_proven=1") != std::string::npos ||
                     state_contract_reason_lc.find("seh_x64_empty_chain_state_proven") != std::string::npos);
                const std::string stats_summary = mcp_tool_attempt_stats_summary(st);
                const bool true_mixed_fail = st.passed > 0 && (st.failed > 0 || st.timed_out > 0);
                if (diagnostic_fallback_evidence) {
                    const std::string fallback_reason = diagnostic_fallback_reason_it_for_tool == g_mcp_diagnostic_fallback_reasons.end()
                        ? std::string("diagnostic_fallback_evidence")
                        : diagnostic_fallback_reason_it_for_tool->second;
                    log_msg(hf, tag, "%s -- registered tool \"%s\" diagnostic fallback evidence_class observed functional_pass=%d %s proof=%s",
                        st.passed > 0 ? "DIAGNOSTIC-FALLBACK-FUNCTIONAL-SUSPECT" : "DIAGNOSTIC-FALLBACK-NONFUNCTIONAL",
                        t.name.c_str(),
                        st.passed,
                        stats_summary.c_str(),
                        compact_text(fallback_reason, 700).c_str());
                    record_mcp_phase_gap("mcp_audit.diagnostic_fallback." + mcp_case_id_fragment(t.name),
                        t.name,
                        fallback_reason + " " + stats_summary);
                }
                if (st.dependency_blocked > 0) {
                    ++no_pass;
                    log_msg(hf, tag, "DEPENDENCY-BLOCKED-COVERAGE-INVALID -- registered tool \"%s\" dependency-blocked results cannot satisfy functional coverage %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.dependency_blocked." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (st.cascade_blocked > 0) {
                    ++no_pass;
                    log_msg(hf, tag, "CASCADE-BLOCKED-COVERAGE-INVALID -- registered tool \"%s\" cascade-blocked results cannot satisfy functional coverage %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.cascade_blocked." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (st.passed > 0) {
                    ++covered;
                    ++passed_tools;
                } else if (destructive_safe_contract_proof) {
                    ++covered;
                    ++destructive_schema_exempt_covered;
                    log_msg(hf, tag, "DESTRUCTIVE-SAFE-CONTRACT-COVERED -- registered tool \"%s\" destructive_schema_only=1 functional_pass=0 functional_counted=0 structured_safe_contract=1 %s",
                        t.name.c_str(), stats_summary.c_str());
                } else if (guard_only_safe_contract_proof) {
                    ++covered;
                    ++security_guard_covered;
                    log_msg(hf, tag, "SECURITY-GUARD-COVERED -- registered tool \"%s\" guard_only=1 functional_pass=0 functional_counted=0 structured_safe_contract=1 %s",
                        t.name.c_str(), stats_summary.c_str());
                } else if (seh_x64_state_contract_covered) {
                    ++covered;
                    log_msg(hf, tag, "STATE-CONTRACT-COVERED -- registered tool \"%s\" x64_empty_chain_proven=1 functional_pass=0 functional_counted=0 proof=%s %s",
                        t.name.c_str(),
                        state_contract_reason_for_tool.empty() ? "<empty>" : compact_text(state_contract_reason_for_tool, 700).c_str(),
                        stats_summary.c_str());
                } else if (destructive_exempt && nonfunctional_evidence) {
                    ++no_pass;
                    log_msg(hf, tag, "DESTRUCTIVE-SAFE-CONTRACT-INVALID -- registered tool \"%s\" destructive_schema_only=1 functional_pass=0 structured_safe_contract=0 %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.destructive_contract_invalid." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (safe_external_guard_exempt && (st.security_guard_passed > 0 || st.guard_passed > 0)) {
                    ++no_pass;
                    log_msg(hf, tag, "GUARD-SAFE-CONTRACT-INVALID -- registered tool \"%s\" guard_only=1 functional_pass=0 structured_safe_contract=0 %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.guard_contract_invalid." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (st.cleanup_contract_passed > 0 && st.failed == 0 && st.timed_out == 0) {
                    ++no_pass;
                    log_msg(hf, tag, "CLEANUP-CONTRACT-NONFUNCTIONAL -- registered tool \"%s\" cleanup behavior observed without seeded functional delta %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.cleanup_nonfunctional." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (st.state_contract_passed > 0 && st.failed == 0 && st.timed_out == 0) {
                    ++no_pass;
                    log_msg(hf, tag, "STATE-CONTRACT-NONFUNCTIONAL -- registered tool \"%s\" state contract observed without functional evidence %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.state_nonfunctional." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (st.accepted_pending > 0 && st.failed == 0 && st.timed_out == 0) {
                    ++no_pass;
                    log_msg(hf, tag, "ACCEPTED-PENDING-NONFUNCTIONAL -- registered tool \"%s\" accepted work but did not produce functional proof %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.accepted_pending." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else if (safe_external_guard_exempt && st.guard_passed > 0 && st.failed == 0 && st.timed_out == 0) {
                    ++no_pass;
                    log_msg(hf, tag, "SAFE-GUARD-NONFUNCTIONAL -- registered tool \"%s\" safe_external_guard=1 functional_pass=0 %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.safe_guard_nonfunctional." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                } else {
                    ++no_pass;
                    log_msg(hf, tag, "NO-FUNCTIONAL-PASS -- registered tool \"%s\" destructive_schema_exempt=%d safe_external_guard_exempt=%d %s",
                        t.name.c_str(), destructive_exempt ? 1 : 0, safe_external_guard_exempt ? 1 : 0, stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.no_functional_pass." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                }
                if (true_mixed_fail) {
                    ++mixed_fail_tools;
                    log_msg(hf, tag, "MIXED-FAIL -- registered tool \"%s\" had functional pass evidence and at least one failed or timed-out invocation %s",
                        t.name.c_str(), stats_summary.c_str());
                    record_mcp_phase_gap("mcp_audit.true_mixed_fail." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                }
                if (st.failed > 0 && !guard_only_safe_contract_proof) {
                    ++failed_tools;
                    record_mcp_phase_gap("mcp_audit.failed." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                }
                if (st.dependency_blocked > 0)
                    ++dependency_blocked_tools;
                if (st.cascade_blocked > 0)
                    ++cascade_blocked_tools;
                if (st.skipped > 0) {
                    ++skipped_tools;
                    record_mcp_phase_gap("mcp_audit.skipped." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                }
                if (st.timed_out > 0) {
                    ++timed_out_tools;
                    record_mcp_phase_gap("mcp_audit.timed_out." + mcp_case_id_fragment(t.name),
                        t.name,
                        stats_summary);
                }
            } else if (g_invoked_tools.find(t.name) != g_invoked_tools.end()) {
                ++attempted;
                ++no_pass;
                log_msg(hf, tag, "NO-FUNCTIONAL-PASS -- registered tool \"%s\" was attempted without a recorded terminal status",
                    t.name.c_str());
                record_mcp_phase_gap("mcp_audit.no_terminal_status." + mcp_case_id_fragment(t.name),
                    t.name,
                    "attempted without recorded terminal status");
            } else {
                bool alias_target_attempted = false;
                const std::string alias_target = select_mcp_coverage_alias_target(t.name, registered, &alias_target_attempted);
                if (!alias_target.empty()) {
                    if (alias_target_attempted) {
                        log_msg(hf, tag, "CONSOLIDATED-ALIAS -- registered tool \"%s\" is audited through canonical tool \"%s\" target_attempted=1 direct_terminal=0",
                            t.name.c_str(),
                            alias_target.c_str());
                        continue;
                    }
                    ++missing;
                    log_msg(hf, tag, "MISSING-ALIAS-TARGET -- registered tool \"%s\" maps to canonical tool \"%s\" but the canonical target was not attempted",
                        t.name.c_str(),
                        alias_target.c_str());
                    record_mcp_phase_gap("mcp_audit.alias_target_missing." + mcp_case_id_fragment(t.name),
                        t.name,
                        std::string("registered alias target was not attempted target=") + alias_target);
                    continue;
                }
                ++missing;
                log_msg(hf, tag, "MISSING -- registered tool \"%s\" was not attempted by the full MCP harness",
                    t.name.c_str());
                record_mcp_phase_gap("mcp_audit.missing." + mcp_case_id_fragment(t.name),
                    t.name,
                    "registered audited tool was not attempted by the full MCP harness");
            }
        }

        for (const auto& expected : g_mcp_expected_empty_nonfunctional) {
            if (is_ai_related_mcp_tool(expected.first))
                continue;
            auto stats_it = g_tool_attempt_stats.find(expected.first);
            const auto reason_it = g_mcp_expected_empty_reasons.find(expected.first);
            const int functional_pass = stats_it != g_tool_attempt_stats.end() ? stats_it->second.passed : 0;
            const auto capture_it = g_mcp_functional_capture_reasons.find(expected.first);
            const std::string expected_reason = reason_it == g_mcp_expected_empty_reasons.end() ? std::string() : reason_it->second;
            const std::string expected_reason_lc = lower_copy(expected_reason);
            const std::string expected_tool_lc = lower_copy(expected.first);
            const bool privacy_zero_record =
                expected_reason_lc.find("privacy_webrtc_block_zero_candidate_expected") != std::string::npos ||
                expected_reason_lc.find("zero ice") != std::string::npos ||
                expected_reason_lc.find("ice_candidate_count=0") != std::string::npos;
            const bool privacy_zero_suppressed =
                functional_pass > 0 &&
                privacy_zero_record &&
                (expected_tool_lc == "browser_interaction" ||
                 expected_tool_lc == "browser_lifecycle" ||
                 expected_tool_lc == "browser_navigation" ||
                 expected_tool_lc == "scripts");
            const bool cleanup_expected_suppressed =
                functional_pass > 0 &&
                expected_tool_lc == "burp_param_miner_manage" &&
                expected_reason_lc.find("cleanup") != std::string::npos;
            const bool live_monitor_expected_suppressed =
                functional_pass > 0 &&
                expected_tool_lc == "live_monitor_manage" &&
                capture_it != g_mcp_functional_capture_reasons.end() &&
                (expected_reason_lc.find("pre-stimulus") != std::string::npos ||
                 expected_reason_lc.find("start_contract") != std::string::npos ||
                 expected_reason_lc.find("waiting_for_post_stimulus") != std::string::npos ||
                 expected_reason_lc.find("capture_missing") != std::string::npos);
            const bool seh_x64_expected_suppressed =
                (expected_tool_lc == "debugger_get_seh_chain" || expected_tool_lc == "dbg_get_seh_chain") &&
                stats_it != g_tool_attempt_stats.end() &&
                stats_it->second.state_contract_passed > 0 &&
                stats_it->second.passed == 0 &&
                (expected_reason_lc.find("x64_empty_chain_proven=1") != std::string::npos ||
                 expected_reason_lc.find("seh_x64_empty_chain_state_proven") != std::string::npos);
            const bool destructive_safe_contract_expected =
                mcp_tool_has_destructive_schema_only_exemption(expected.first) &&
                stats_it != g_tool_attempt_stats.end() &&
                stats_it->second.failed == 0 &&
                stats_it->second.timed_out == 0 &&
                stats_it->second.skipped == 0 &&
                stats_it->second.dependency_blocked == 0 &&
                stats_it->second.cascade_blocked == 0 &&
                (stats_it->second.schema_passed > 0 ||
                 stats_it->second.contract_passed > 0 ||
                 stats_it->second.guard_passed > 0 ||
                 stats_it->second.state_contract_passed > 0);
            if ((privacy_zero_suppressed || cleanup_expected_suppressed || live_monitor_expected_suppressed) &&
                capture_it != g_mcp_functional_capture_reasons.end()) {
                log_msg(hf, tag, "EXPECTED-EMPTY-SUPPRESSED -- tool=\"%s\" count=%d functional_pass=%d reason=%s expected_empty_proof=%s functional_capture_proof=%s",
                    expected.first.c_str(),
                    expected.second,
                    functional_pass,
                    live_monitor_expected_suppressed ? "live_monitor_has_independent_capture_proof" :
                        (privacy_zero_suppressed ? "privacy_zero_has_independent_functional_proof" : "cleanup_contract_has_independent_functional_proof"),
                    reason_it == g_mcp_expected_empty_reasons.end() ? "<empty>" : compact_text(reason_it->second, 900).c_str(),
                    compact_text(capture_it->second, 900).c_str());
                continue;
            }
            if (privacy_zero_suppressed || cleanup_expected_suppressed || seh_x64_expected_suppressed || destructive_safe_contract_expected) {
                log_msg(hf, tag, "EXPECTED-EMPTY-SUPPRESSED -- tool=\"%s\" count=%d functional_pass=%d reason=%s expected_empty_proof=%s",
                    expected.first.c_str(),
                    expected.second,
                    functional_pass,
                    privacy_zero_suppressed ? "privacy_zero_has_independent_functional_proof" :
                        (cleanup_expected_suppressed ? "cleanup_contract_has_independent_functional_proof" :
                            (seh_x64_expected_suppressed ? "seh_x64_empty_chain_state_contract_covered" : "destructive_safe_contract_audited_separately")),
                    expected_reason.empty() ? "<empty>" : compact_text(expected_reason, 900).c_str());
                continue;
            }
            ++expected_empty_nonfunctional_tools;
            log_msg(hf, tag, "EXPECTED-EMPTY-NONFUNCTIONAL -- tool=\"%s\" count=%d functional_pass=%d proof=%s",
                expected.first.c_str(),
                expected.second,
                functional_pass,
                expected_reason.empty() ? "<empty>" : compact_text(expected_reason, 900).c_str());
            record_mcp_phase_gap("mcp_audit.expected_empty_nonfunctional." + mcp_case_id_fragment(expected.first),
                expected.first,
                expected_reason.empty() ? "expected empty nonfunctional without independent functional coverage" : expected_reason);
        }

        for (const auto& suspect : g_mcp_zero_output_suspects) {
            if (is_ai_related_mcp_tool(suspect.first))
                continue;
            ++empty_result_suspect_tools;
            auto stats_it = g_tool_attempt_stats.find(suspect.first);
            const int functional_pass = stats_it != g_tool_attempt_stats.end() ? stats_it->second.passed : 0;
            const int failed_records = stats_it != g_tool_attempt_stats.end() ? stats_it->second.failed : 0;
            const auto reason_it = g_mcp_zero_output_reasons.find(suspect.first);
            log_msg(hf, tag, "EMPTY-RESULT-SUSPECT -- tool=\"%s\" count=%d functional_pass=%d failed_records=%d reason=%s",
                suspect.first.c_str(),
                suspect.second,
                functional_pass,
                failed_records,
                reason_it == g_mcp_zero_output_reasons.end() ? "<empty>" : compact_text(reason_it->second, 900).c_str());
            if (functional_pass > 0) {
                ++unexpected_zero_pass_tools;
                log_msg(hf, tag, "EMPTY-RESULT-FALSE-POSITIVE -- tool=\"%s\" had functional pass evidence after unexpected zero-output evidence count=%d functional_pass=%d",
                    suspect.first.c_str(),
                    suspect.second,
                    functional_pass);
            }
            record_mcp_phase_gap("mcp_audit.empty_result_suspect." + mcp_case_id_fragment(suspect.first),
                suspect.first,
                reason_it == g_mcp_zero_output_reasons.end() ? "unexpected zero-output evidence" : reason_it->second);
        }

        int stale = 0;
        for (const auto& attempted : g_invoked_tools) {
            if (registered.find(attempted) == registered.end() && !is_ai_related_mcp_tool(attempted)) {
                ++stale;
                log_msg(hf, tag, "STALE -- explicit MCP test attempted unregistered tool \"%s\"",
                    attempted.c_str());
                record_mcp_phase_gap("mcp_audit.stale." + mcp_case_id_fragment(attempted),
                    attempted,
                    "explicit MCP test attempted unregistered tool");
            }
        }

        for (const auto& rec : copy_timed_out_invocations()) {
            std::string reason = "timed-out worker did not drain seq=" + std::to_string(rec.seq) +
                " timeout_ms=" + std::to_string(rec.timeout_ms) +
                " domain=" + rec.domain;
            if (rec.state) {
                std::lock_guard<std::mutex> lk(rec.state->mutex);
                reason += " handler_entered=" + std::to_string(rec.state->handler_entered ? 1 : 0) +
                    " handler_exited=" + std::to_string(rec.state->handler_exited ? 1 : 0) +
                    " done=" + std::to_string(rec.state->done ? 1 : 0) +
                    " worker_phase=" + (rec.state->worker_phase.empty() ? std::string("<empty>") : rec.state->worker_phase);
            }
            record_mcp_phase_gap("mcp_audit.outstanding_timeout.seq_" + std::to_string(rec.seq) + "." + mcp_case_id_fragment(rec.tool_name),
                rec.tool_name,
                reason);
        }

        const auto raw_case_ledger = copy_mcp_case_ledger();
        const int raw_action_terminal_records = static_cast<int>(raw_case_ledger.size());
        for (std::size_t i = 0; i < raw_case_ledger.size(); ++i) {
            const auto& entry = raw_case_ledger[i];
            const bool audited_registered = registered.find(entry.tool) != registered.end();
            log_msg(hf, tag, "MCP-RAW-CASE-LEDGER -- index=%zu case_id=\"%s\" tool=\"%s\" status=%s audited_registered=%d ordinal=%llu",
                i + 1,
                entry.case_id.c_str(),
                entry.tool.c_str(),
                entry.status_name.c_str(),
                audited_registered ? 1 : 0,
                static_cast<unsigned long long>(entry.ordinal));
        }
        const auto case_ledger = build_mcp_registered_coverage_ledger(registered);
        const int ledger_terminal_records = static_cast<int>(case_ledger.size());
        std::set<std::string> ledger_case_ids;
        std::set<std::string> ledger_registered_tools;
        int ledger_duplicate_case_ids = 0;
        for (std::size_t i = 0; i < case_ledger.size(); ++i) {
            const auto& entry = case_ledger[i];
            const bool audited_registered = registered.find(entry.tool) != registered.end();
            if (audited_registered)
                ledger_registered_tools.insert(entry.tool);
            if (!ledger_case_ids.insert(entry.case_id).second)
                ++ledger_duplicate_case_ids;
            log_msg(hf, tag, "MCP-CASE-LEDGER -- index=%zu case_id=\"%s\" tool=\"%s\" status=%s audited_registered=%d ordinal=%llu synthetic=%d consolidated_alias=%d canonical_tool=\"%s\" reason=%s",
                i + 1,
                entry.case_id.c_str(),
                entry.tool.c_str(),
                entry.status_name.c_str(),
                audited_registered ? 1 : 0,
                static_cast<unsigned long long>(entry.ordinal),
                entry.synthetic ? 1 : 0,
                entry.consolidated_alias ? 1 : 0,
                entry.canonical_tool.empty() ? "<none>" : entry.canonical_tool.c_str(),
                entry.reason.empty() ? "<empty>" : compact_text(entry.reason, 900).c_str());
        }
        int ledger_registered_missing_tools = 0;
        for (const auto& registered_tool : registered) {
            if (ledger_registered_tools.find(registered_tool) == ledger_registered_tools.end()) {
                ++ledger_registered_missing_tools;
                record_mcp_phase_gap("mcp_audit.ledger_missing." + mcp_case_id_fragment(registered_tool),
                    registered_tool,
                    "registered audited tool has no terminal MCP case ledger row");
            }
        }
        if (ledger_duplicate_case_ids != 0) {
            record_mcp_phase_gap("mcp_audit.ledger_duplicate_case_id",
                "mcp_case_ledger",
                "duplicate terminal case ledger ids=" + std::to_string(ledger_duplicate_case_ids));
        }
        const int phase_completed_by_raw_actions = (std::min)(raw_action_terminal_records, k_mcp_planned_tool_tests);
        const int phase_remaining_by_raw_actions = k_mcp_planned_tool_tests > phase_completed_by_raw_actions ? k_mcp_planned_tool_tests - phase_completed_by_raw_actions : 0;
        const int raw_action_extra_terminal_records = raw_action_terminal_records > k_mcp_planned_tool_tests ? raw_action_terminal_records - k_mcp_planned_tool_tests : 0;
        const int phase_extra_terminal_records = 0;
        if (phase_remaining_by_raw_actions != 0) {
            record_mcp_phase_gap("mcp_audit.case_ledger_planned_mismatch",
                "mcp_case_ledger",
                "planned=" + std::to_string(k_mcp_planned_tool_tests) +
                    " raw_action_terminal=" + std::to_string(raw_action_terminal_records) +
                    " phase_terminal=" + std::to_string(phase_completed_by_raw_actions) +
                    " remaining=" + std::to_string(phase_remaining_by_raw_actions) +
                    " raw_action_extra_separate=" + std::to_string(raw_action_extra_terminal_records));
        }
        log_msg(hf, tag, "MCP-CASE-LEDGER-SUMMARY -- planned=%d registered_terminal_records=%d raw_action_records=%d phase_terminal_records=%d phase_remaining=%d phase_extra=%d raw_action_extra_separate=%d registered_terminal_tools=%zu registered_missing_tools=%d duplicate_case_ids=%d",
            k_mcp_planned_tool_tests,
            ledger_terminal_records,
            raw_action_terminal_records,
            phase_completed_by_raw_actions,
            phase_remaining_by_raw_actions,
            phase_extra_terminal_records,
            raw_action_extra_terminal_records,
            ledger_registered_tools.size(),
            ledger_registered_missing_tools,
            ledger_duplicate_case_ids);

        const bool destructive_schema_accounting_ok =
            destructive_schema_exemptions == k_expected_destructive_schema_only_exemptions &&
            destructive_schema_exempt_covered == k_expected_destructive_schema_only_exemptions;
        if (!destructive_schema_accounting_ok) {
            log_msg(hf, tag, "DESTRUCTIVE-SCHEMA-ACCOUNTING-FAIL -- expected=%d exemptions=%d covered=%d dx_hook_manage_schema_exempt=%d",
                k_expected_destructive_schema_only_exemptions,
                destructive_schema_exemptions,
                destructive_schema_exempt_covered,
                0);
            record_mcp_phase_gap("mcp_audit.destructive_schema_accounting",
                "destructive_schema_only",
                "expected six destructive schema-only exemptions but observed exemptions=" +
                    std::to_string(destructive_schema_exemptions) +
                    " covered=" + std::to_string(destructive_schema_exempt_covered));
        }

        const bool audit_clean =
            missing == 0 &&
            stale == 0 &&
            no_pass == 0 &&
            failed_tools == 0 &&
            mixed_fail_tools == 0 &&
            skipped_tools == 0 &&
            timed_out_tools == 0 &&
            dependency_blocked_tools == 0 &&
            cascade_blocked_tools == 0 &&
            expected_empty_nonfunctional_tools == 0 &&
            empty_result_suspect_tools == 0 &&
            unexpected_zero_pass_tools == 0 &&
            diagnostic_fallback_tools == 0 &&
            diagnostic_fallback_functional_tools == 0 &&
            outstanding_timed_out_workers == 0 &&
            timed_out_drain_complete &&
            destructive_schema_accounting_ok &&
            phase_remaining_by_raw_actions == 0 &&
            phase_extra_terminal_records == 0 &&
            ledger_registered_missing_tools == 0 &&
            ledger_duplicate_case_ids == 0;

        mcp_coverage_audit_snapshot_t snapshot;
        snapshot.audit_started = true;
        snapshot.audit_completed = true;
        snapshot.audit_clean = audit_clean;
        snapshot.missing = missing;
        snapshot.stale = stale;
        snapshot.attempted = attempted;
        snapshot.functional_passed_tools = passed_tools;
        snapshot.covered_total = covered;
        snapshot.no_functional_pass = no_pass;
        snapshot.failed_tools = failed_tools;
        snapshot.mixed_fail_tools = mixed_fail_tools;
        snapshot.skipped_tools = skipped_tools;
        snapshot.timed_out_tools = timed_out_tools;
        snapshot.dependency_blocked_tools = dependency_blocked_tools;
        snapshot.cascade_blocked_tools = cascade_blocked_tools;
        snapshot.accepted_pending_tools = accepted_pending_tools;
        snapshot.expected_empty_nonfunctional_tools = expected_empty_nonfunctional_tools;
        snapshot.empty_result_suspect_tools = empty_result_suspect_tools;
        snapshot.unexpected_zero_pass_tools = unexpected_zero_pass_tools;
        snapshot.diagnostic_fallback_tools = diagnostic_fallback_tools;
        snapshot.diagnostic_fallback_functional_tools = diagnostic_fallback_functional_tools;
        snapshot.destructive_schema_exemptions = destructive_schema_exemptions;
        snapshot.destructive_safe_contract_covered = destructive_schema_exempt_covered;
        snapshot.security_guard_covered = security_guard_covered;
        snapshot.outstanding_timed_out_workers = outstanding_timed_out_workers;
        snapshot.timed_out_drain_complete = timed_out_drain_complete;
        snapshot.registered_total = registered_total;
        snapshot.external = registered_external;
        snapshot.internal = registered_internal;
        snapshot.ide_chat_only = registered_ide_chat;
        snapshot.ai_excluded = skipped_ai;
        snapshot.non_ai_audited = non_ai_audited;
        snapshot.phase_completed = phase_completed_by_raw_actions;
        snapshot.phase_remaining = phase_remaining_by_raw_actions;
        snapshot.phase_extra_terminal_records = phase_extra_terminal_records;
        snapshot.ledger_terminal_records = ledger_terminal_records;
        snapshot.raw_action_terminal_records = raw_action_terminal_records;
        snapshot.ledger_registered_terminal_tools = static_cast<int>(ledger_registered_tools.size());
        snapshot.ledger_registered_missing_tools = ledger_registered_missing_tools;
        snapshot.ledger_duplicate_case_ids = ledger_duplicate_case_ids;
        store_mcp_audit_snapshot(snapshot);

        log_msg(hf, tag, "DIAG -- registry total=%d external=%d internal=%d ide_chat_only=%d ai_excluded=%d non_ai_audited=%d destructive_tools=%d destructive_schema_exemptions=%d destructive_safe_contract_covered=%d security_guard_covered=%d schema_pass_tools=%d contract_pass_tools=%d cleanup_contract_pass_tools=%d state_contract_pass_tools=%d accepted_pending_tools=%d guard_pass_tools=%d security_guard_pass_tools=%d negative_pass_tools=%d dependency_blocked_tools=%d cascade_blocked_tools=%d expected_empty_nonfunctional_tools=%d empty_result_suspect_tools=%d unexpected_zero_pass_tools=%d diagnostic_fallback_tools=%d diagnostic_fallback_functional_tools=%d outstanding_timed_out_workers=%zu timed_out_drain_complete=%d explicit_invocations=%zu raw_action_records=%d raw_action_extra_separate=%d ledger_terminal_records=%d ledger_registered_terminal_tools=%d ledger_registered_missing_tools=%d ledger_duplicate_case_ids=%d phase_completed=%d phase_remaining=%d phase_extra=%d strict_safe_contract_proof=1 destructive_schema_expected=%d destructive_schema_ok=%d",
            registered_total,
            registered_external,
            registered_internal,
            registered_ide_chat,
            skipped_ai,
            non_ai_audited,
            destructive_schema_tools,
            destructive_schema_exemptions,
            destructive_schema_exempt_covered,
            security_guard_covered,
            schema_pass_tools,
            contract_pass_tools,
            cleanup_contract_pass_tools,
            state_contract_pass_tools,
            accepted_pending_tools,
            guard_pass_tools,
            security_guard_pass_tools,
            negative_pass_tools,
            dependency_blocked_tools,
            cascade_blocked_tools,
            expected_empty_nonfunctional_tools,
            empty_result_suspect_tools,
            unexpected_zero_pass_tools,
            diagnostic_fallback_tools,
            diagnostic_fallback_functional_tools,
            outstanding_timed_out_workers,
            timed_out_drain_complete ? 1 : 0,
            g_invoked_tools.size(),
            raw_action_terminal_records,
            raw_action_extra_terminal_records,
            ledger_terminal_records,
            static_cast<int>(ledger_registered_tools.size()),
            ledger_registered_missing_tools,
            ledger_duplicate_case_ids,
            phase_completed_by_raw_actions,
            phase_remaining_by_raw_actions,
            phase_extra_terminal_records,
            k_expected_destructive_schema_only_exemptions,
            destructive_schema_accounting_ok ? 1 : 0);

        if (audit_clean) {
            log_msg(hf, tag, "PASS -- attempted=%d functional_passed_tools=%d destructive_safe_contract_covered=%d security_guard_covered=%d covered_total=%d no_functional_pass=%d failed_tools=%d mixed_fail_tools=%d skipped_tools=%d timed_out_tools=%d dependency_blocked_tools=%d cascade_blocked_tools=%d accepted_pending_tools=%d empty_result_suspect_tools=%d unexpected_zero_pass_tools=%d expected_empty_nonfunctional_tools=%d diagnostic_fallback_tools=%d diagnostic_fallback_functional_tools=%d outstanding_timed_out_workers=%zu registered_total=%d external=%d internal=%d ide_chat_only=%d ai_excluded=%d non_ai_audited=%d destructive_schema_exemptions=%d strict_safe_contract_proof=1",
                attempted, passed_tools, destructive_schema_exempt_covered, security_guard_covered, covered, no_pass, failed_tools, mixed_fail_tools, skipped_tools, timed_out_tools, dependency_blocked_tools, cascade_blocked_tools, accepted_pending_tools, empty_result_suspect_tools, unexpected_zero_pass_tools, expected_empty_nonfunctional_tools, diagnostic_fallback_tools, diagnostic_fallback_functional_tools, outstanding_timed_out_workers,
                registered_total, registered_external, registered_internal, registered_ide_chat, skipped_ai, non_ai_audited, destructive_schema_exemptions);
            passed.fetch_add(1);
        } else {
            log_msg(hf, tag, "FAIL -- missing=%d stale=%d attempted=%d functional_passed_tools=%d destructive_safe_contract_covered=%d security_guard_covered=%d covered_total=%d no_functional_pass=%d failed_tools=%d mixed_fail_tools=%d skipped_tools=%d timed_out_tools=%d dependency_blocked_tools=%d cascade_blocked_tools=%d accepted_pending_tools=%d empty_result_suspect_tools=%d unexpected_zero_pass_tools=%d expected_empty_nonfunctional_tools=%d diagnostic_fallback_tools=%d diagnostic_fallback_functional_tools=%d outstanding_timed_out_workers=%zu timed_out_drain_complete=%d registered_total=%d external=%d internal=%d ide_chat_only=%d ai_excluded=%d non_ai_audited=%d destructive_schema_exemptions=%d destructive_schema_expected=%d destructive_schema_ok=%d strict_functional_coverage=1 strict_safe_contract_proof=1",
                missing, stale, attempted, passed_tools, destructive_schema_exempt_covered, security_guard_covered, covered, no_pass, failed_tools, mixed_fail_tools, skipped_tools, timed_out_tools, dependency_blocked_tools, cascade_blocked_tools, accepted_pending_tools, empty_result_suspect_tools, unexpected_zero_pass_tools, expected_empty_nonfunctional_tools, diagnostic_fallback_tools, diagnostic_fallback_functional_tools, outstanding_timed_out_workers, timed_out_drain_complete ? 1 : 0,
                registered_total, registered_external, registered_internal, registered_ide_chat, skipped_ai, non_ai_audited, destructive_schema_exemptions, k_expected_destructive_schema_only_exemptions, destructive_schema_accounting_ok ? 1 : 0);
            failed.fetch_add(1);
        }
        const auto cq_end = aida::infra::taskflow_runtime::domain_stats(aida::infra::taskflow_runtime::executor_domain_t::critical);
        log_msg(hf, tag, "END -- missing=%d stale=%d no_functional_pass=%d functional_passed_tools=%d destructive_safe_contract_covered=%d security_guard_covered=%d failed_tools=%d mixed_fail_tools=%d dependency_blocked_tools=%d cascade_blocked_tools=%d empty_result_suspect_tools=%d unexpected_zero_pass_tools=%d expected_empty_nonfunctional_tools=%d diagnostic_fallback_tools=%d diagnostic_fallback_functional_tools=%d timed_out_tools=%d outstanding_timed_out_workers=%zu schema_pass_tools=%d contract_pass_tools=%d cleanup_contract_pass_tools=%d state_contract_pass_tools=%d accepted_pending_tools=%d guard_pass_tools=%d security_guard_pass_tools=%d negative_pass_tools=%d strict_safe_contract_proof=1 pass=%d fail=%d skip=%d cq_pending=%zu cq_active=%u cq_started=%llu cq_finished=%llu",
            missing,
            stale,
            no_pass,
            passed_tools,
            destructive_schema_exempt_covered,
            security_guard_covered,
            failed_tools,
            mixed_fail_tools,
            dependency_blocked_tools,
            cascade_blocked_tools,
            empty_result_suspect_tools,
            unexpected_zero_pass_tools,
            expected_empty_nonfunctional_tools,
            diagnostic_fallback_tools,
            diagnostic_fallback_functional_tools,
            timed_out_tools,
            outstanding_timed_out_workers,
            schema_pass_tools,
            contract_pass_tools,
            cleanup_contract_pass_tools,
            state_contract_pass_tools,
            accepted_pending_tools,
            guard_pass_tools,
            security_guard_pass_tools,
            negative_pass_tools,
            passed.load(std::memory_order_acquire),
            failed.load(std::memory_order_acquire),
            skipped.load(std::memory_order_acquire),
            cq_end.pending,
            static_cast<unsigned>(cq_end.active),
            static_cast<unsigned long long>(cq_end.started),
            static_cast<unsigned long long>(cq_end.finished));
    }




