    void test_tool_network_stream_track(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        const DWORD fixture_pid = GetCurrentProcessId();
        mcp_standalone::json clear_args;
        clear_args["operation"] = "clear";
        invoke_tool_bounded(get_server(), "network_stream_track", clear_args, tool_timeout_ms("network_stream_track"));
        mcp_standalone::json start_args;
        start_args["operation"] = "start";
        start_args["pid"] = fixture_pid;
        auto started = invoke_tool_bounded(get_server(), "network_stream_track", start_args, tool_timeout_ms("network_stream_track"));
        log_msg(hf, "mcp.network_stream_track", "STREAM-FIXTURE -- tracker start timed_out=%d found=%d threw=%d success=%d elapsed_ms=%lld",
            started.timed_out ? 1 : 0,
            started.result.found ? 1 : 0,
            started.result.threw ? 1 : 0,
            started.result.success ? 1 : 0,
            started.elapsed_ms);
        if (started.timed_out || !started.result.found || started.result.threw || !started.result.success) {
            record_tool_status("network_stream_track", started.timed_out ? mcp_tool_call_status_t::timed_out : mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return;
        }
        const std::string fixture_path = "/aida-network-stream-track-fixture";
        const auto payload = mcp_http_fixture_request_payload(fixture_path.c_str());
        if (!seed_network_parse_capture(hf, "mcp.network_stream_track", payload)) {
            mcp_standalone::json stop_args;
            stop_args["operation"] = "stop";
            invoke_tool_bounded(get_server(), "network_stream_track", stop_args, tool_timeout_ms("network_stream_track"));
            record_fixture_failed_tool("network_stream_track", failed);
            return;
        }
        const uint16_t fixture_port = g_burp_http_fixture ? g_burp_http_fixture->port : 0;
        log_msg(hf, "mcp.network_stream_track", "STREAM-FIXTURE -- fixture pid=%lu port=%u path=%s payload_bytes=%zu",
            static_cast<unsigned long>(fixture_pid),
            static_cast<unsigned>(fixture_port),
            fixture_path.c_str(),
            payload.size());
        Sleep(500);
        auto packets = driver_bridge::get_captured_packets(64);
        size_t fed = 0;
        size_t fixture_polled = 0;
        size_t unmatched_tcp = 0;
        uint64_t fed_bytes = 0;
        std::string first_unmatched_tuple = "<none>";
        auto packet_contains_fixture = [&](const driver_bridge::captured_packet_t& pkt) {
            return !pkt.payload.empty() &&
                std::search(pkt.payload.begin(), pkt.payload.end(), fixture_path.begin(), fixture_path.end()) != pkt.payload.end();
        };
        auto packet_tuple = [](const driver_bridge::captured_packet_t& pkt) {
            std::ostringstream oss;
            oss << "pid=" << pkt.pid
                << " proto=" << pkt.protocol
                << " dir=" << pkt.direction
                << " local_port=" << pkt.local_port
                << " remote_port=" << pkt.remote_port
                << " bytes=" << pkt.payload.size();
            return oss.str();
        };
        for (const auto& pkt : packets) {
            if (pkt.protocol != 6 || (pkt.pid != fixture_pid && pkt.pid != 0))
                continue;
            const bool fixture_match =
                (fixture_port != 0 && (pkt.local_port == fixture_port || pkt.remote_port == fixture_port)) ||
                packet_contains_fixture(pkt);
            if (fixture_match) {
                network_view::g_stream_tracker.feed(pkt);
                ++fed;
                ++fixture_polled;
                fed_bytes += pkt.payload.size();
            } else {
                ++unmatched_tcp;
                if (first_unmatched_tuple == "<none>")
                    first_unmatched_tuple = packet_tuple(pkt);
            }
        }
        log_msg(hf, "mcp.network_stream_track", "STREAM-FIXTURE -- manual_feed packets=%zu bytes=%llu fixture_polled=%zu total_polled=%zu unmatched_tcp=%zu first_unmatched=%s",
            fed,
            static_cast<unsigned long long>(fed_bytes),
            fixture_polled,
            packets.size(),
            unmatched_tcp,
            first_unmatched_tuple.c_str());
        mcp_standalone::json args;
        args["operation"] = "get_all";
        test_tool_call_with_followup(hf, "mcp.network_stream_track", get_server(), "network_stream_track", args, passed, failed, skipped,
            mcp_tool_call_status_t::functional_pass, "fixture_stream_correlation",
            [hf, fixture_pid, fixture_port, fixture_path, fed, fed_bytes, total_polled = packets.size()](const invoke_result_t& ir, std::string& proof) {
                const auto streams_it = ir.data.is_object() ? ir.data.find("streams") : ir.data.end();
                if (streams_it == ir.data.end() || !streams_it->is_array() || streams_it->empty()) {
                    proof = "streams missing_or_empty fixture_pid=" + std::to_string(fixture_pid) +
                        " fixture_port=" + std::to_string(fixture_port) +
                        " manual_fed=" + std::to_string(fed) +
                        " total_polled=" + std::to_string(total_polled);
                    return false;
                }
                size_t matched_streams = 0;
                uint64_t matched_bytes = 0;
                uint64_t matched_packets = 0;
                std::string first_unmatched = "<none>";
                for (const auto& stream : *streams_it) {
                    uint64_t src_port = 0;
                    uint64_t dst_port = 0;
                    uint64_t total_bytes = 0;
                    uint64_t total_packets = 0;
                    uint64_t proto = 0;
                    std::string src_ip;
                    std::string dst_ip;
                    std::string rendered_payload;
                    payload_u64_field(stream, "src_port", src_port);
                    payload_u64_field(stream, "dst_port", dst_port);
                    payload_u64_field(stream, "total_bytes", total_bytes);
                    payload_u64_field(stream, "total_packets", total_packets);
                    payload_u64_field(stream, "proto", proto);
                    payload_string_field(stream, "src_ip", src_ip);
                    payload_string_field(stream, "dst_ip", dst_ip);
                    payload_string_field(stream, "payload", rendered_payload);
                    const bool port_match = fixture_port != 0 && (src_port == fixture_port || dst_port == fixture_port);
                    const bool payload_match = rendered_payload.find(fixture_path) != std::string::npos;
                    if (port_match || payload_match) {
                        ++matched_streams;
                        matched_bytes += total_bytes;
                        matched_packets += total_packets;
                    } else if (first_unmatched == "<none>") {
                        std::ostringstream oss;
                        oss << src_ip << ":" << src_port
                            << "->" << dst_ip << ":" << dst_port
                            << " proto=" << proto
                            << " bytes=" << total_bytes
                            << " packets=" << total_packets;
                        first_unmatched = oss.str();
                    }
                }
                log_msg(hf, "mcp.network_stream_track", "STREAM-FIXTURE -- fixture_pid=%lu fixture_port=%u manual_fed=%zu manual_bytes=%llu total_polled=%zu returned_streams=%zu matched_streams=%zu matched_bytes=%llu matched_packets=%llu first_unmatched=%s",
                    static_cast<unsigned long>(fixture_pid),
                    static_cast<unsigned>(fixture_port),
                    fed,
                    static_cast<unsigned long long>(fed_bytes),
                    total_polled,
                    streams_it->size(),
                    matched_streams,
                    static_cast<unsigned long long>(matched_bytes),
                    static_cast<unsigned long long>(matched_packets),
                    first_unmatched.c_str());
                if (matched_streams == 0 || matched_bytes == 0 || matched_packets == 0) {
                    proof = "no fixture-correlated stream evidence fixture_pid=" + std::to_string(fixture_pid) +
                        " fixture_port=" + std::to_string(fixture_port) +
                        " returned_streams=" + std::to_string(streams_it->size()) +
                        " matched_streams=" + std::to_string(matched_streams) +
                        " matched_bytes=" + std::to_string(matched_bytes) +
                        " matched_packets=" + std::to_string(matched_packets) +
                        " manual_fed=" + std::to_string(fed) +
                        " total_polled=" + std::to_string(total_polled) +
                        " first_unmatched=" + first_unmatched;
                    return false;
                }
                proof = "fixture stream correlated fixture_pid=" + std::to_string(fixture_pid) +
                    " fixture_port=" + std::to_string(fixture_port) +
                    " matched_streams=" + std::to_string(matched_streams) +
                    " matched_bytes=" + std::to_string(matched_bytes) +
                    " matched_packets=" + std::to_string(matched_packets);
                return true;
            });
        driver_bridge::stop_capture();
        mcp_standalone::json stop_args;
        stop_args["operation"] = "stop";
        auto stopped = invoke_tool_bounded(get_server(), "network_stream_track", stop_args, tool_timeout_ms("network_stream_track"));
        log_msg(hf, "mcp.network_stream_track", "STREAM-FIXTURE -- tracker stop timed_out=%d success=%d elapsed_ms=%lld",
            stopped.timed_out ? 1 : 0,
            stopped.result.success ? 1 : 0,
            stopped.elapsed_ms);
    }

    void test_tool_network_pg_sniff(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        uint64_t pg_addr = 0;
        std::vector<uint8_t> marker(4096, 0);
        const std::string marker_text = "AIDA_NETWORK_PG_SNIFF_DIRECT_FIXTURE";
        std::copy(marker_text.begin(), marker_text.end(), marker.begin());
        const uint64_t install_size = static_cast<uint64_t>(marker.size());
        if (!ensure_mcp_private_bytes(hf, "mcp.network_pg_sniff", pg_addr, marker.size(), marker)) {
            record_fixture_failed_tool("network_pg_sniff", failed);
            return;
        }
        const uint32_t pid = g_mcp_target_pid != 0 ? g_mcp_target_pid : driver_bridge::attached_pid();
        if (pid == 0 || (driver_bridge::attached_pid() != pid && !restore_mcp_target(hf, "mcp.network_pg_sniff"))) {
            log_msg(hf, "mcp.network_pg_sniff", "FIXTURE-INVALID -- dedicated page-guard target unavailable pid=%u active_pid=%u addr=0x%016llX size=%llu status=\"%s\" last_error=\"%s\"",
                pid,
                driver_bridge::attached_pid(),
                static_cast<unsigned long long>(pg_addr),
                static_cast<unsigned long long>(install_size),
                driver_bridge::status().c_str(),
                driver_bridge::last_error().c_str());
            if (pg_addr != 0)
                driver_bridge::free_memory(pg_addr);
            record_fixture_failed_tool("network_pg_sniff", failed);
            return;
        }
        driver_bridge::memory_region_t region{};
        const bool query_ok = driver_bridge::query_memory_for(pid, pg_addr, region);
        const bool region_offset_ok = query_ok && pg_addr >= region.base && (pg_addr - region.base) < region.size;
        const uint64_t region_offset = region_offset_ok ? (pg_addr - region.base) : 0;
        const bool region_covers = region_offset_ok && install_size <= (region.size - region_offset);
        const bool committed = query_ok && region.state == MEM_COMMIT;
        const bool readable = query_ok && (region.protect & PAGE_NOACCESS) == 0;
        std::vector<uint8_t> readback;
        const bool read_ok = driver_bridge::read_memory_for(pid, pg_addr, marker_text.size(), readback);
        const bool marker_ok = read_ok && readback.size() >= marker_text.size() &&
            std::equal(marker.begin(), marker.begin() + marker_text.size(), readback.begin());
        log_msg(hf, "mcp.network_pg_sniff", "PRECHECK-REGION -- pid=%u active_pid=%u addr=0x%016llX size=%llu page_offset=0x%03llX query_ok=%d covers=%d state=0x%08X protect=0x%08X type=0x%08X base=0x%016llX region_size=%llu status=\"%s\" last_error=\"%s\"",
            pid,
            driver_bridge::attached_pid(),
            static_cast<unsigned long long>(pg_addr),
            static_cast<unsigned long long>(install_size),
            static_cast<unsigned long long>(pg_addr & 0xFFFULL),
            query_ok ? 1 : 0,
            region_covers ? 1 : 0,
            query_ok ? region.state : 0,
            query_ok ? region.protect : 0,
            query_ok ? region.type : 0,
            static_cast<unsigned long long>(query_ok ? region.base : 0),
            static_cast<unsigned long long>(query_ok ? region.size : 0),
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str());
        log_msg(hf, "mcp.network_pg_sniff", "PRECHECK-READBACK -- read_ok=%d read_size=%zu marker_ok=%d marker=[%s]",
            read_ok ? 1 : 0,
            readback.size(),
            marker_ok ? 1 : 0,
            hex_preview(readback).c_str());
        std::string fixture_reason;
        if (pg_addr == 0)
            fixture_reason = "fixture_addr=0";
        else if (!query_ok)
            fixture_reason = "query_memory_failed";
        else if (!region_covers)
            fixture_reason = "region_does_not_cover_guard_page";
        else if (!committed)
            fixture_reason = "region_not_committed";
        else if (!readable)
            fixture_reason = "region_not_readable";
        else if (!marker_ok)
            fixture_reason = "fixture_marker_readback_mismatch";
        if (!fixture_reason.empty()) {
            log_msg(hf, "mcp.network_pg_sniff", "FIXTURE-INVALID -- reason=%s pid=%u active_pid=%u addr=0x%016llX size=%llu query_ok=%d read_ok=%d marker_ok=%d status=\"%s\" last_error=\"%s\"",
                fixture_reason.c_str(),
                pid,
                driver_bridge::attached_pid(),
                static_cast<unsigned long long>(pg_addr),
                static_cast<unsigned long long>(install_size),
                query_ok ? 1 : 0,
                read_ok ? 1 : 0,
                marker_ok ? 1 : 0,
                driver_bridge::status().c_str(),
                driver_bridge::last_error().c_str());
            if (pg_addr != 0)
                driver_bridge::free_memory(pg_addr);
            record_fixture_failed_tool("network_pg_sniff", failed);
            return;
        }
        mcp_standalone::json install_args;
        install_args["operation"] = "install";
        install_args["pid"] = pid;
        install_args["address"] = hex_u64(pg_addr);
        install_args["size"] = install_size;
        install_args["max_records_per_drain"] = 16;
        uint64_t session_id = 0;
        auto pg_contract_call = [&](const char* phase,
                                    const mcp_standalone::json& call_args,
                                    const std::function<bool(const invoke_result_t&, std::string&)>& validator) -> bool {
            (void)skipped;
            const char* tool_name = "network_pg_sniff";
            g_invoked_tools.insert(tool_name);
            const int seq = g_mcp_tool_sequence.fetch_add(1, std::memory_order_acq_rel) + 1;
            char step[256];
            _snprintf_s(step, sizeof(step), _TRUNCATE, "mcp network_pg_sniff #%d: %s", seq, phase ? phase : "<null>");
            set_progress_step(step);
            log_msg(hf, "mcp.network_pg_sniff", "DISPATCH -- phase=%s seq=%d pid=%u active_pid=%u addr=0x%016llX size=%llu args=%s",
                phase ? phase : "<null>",
                seq,
                pid,
                driver_bridge::attached_pid(),
                static_cast<unsigned long long>(pg_addr),
                static_cast<unsigned long long>(install_size),
                compact_json(call_args, 900).c_str());
            auto timed = invoke_tool_bounded(get_server(), tool_name, call_args, tool_timeout_ms(tool_name), hf, "mcp.network_pg_sniff", seq);
            const invoke_result_t& ir = timed.result;
            log_mcp_result_detail(timed.timed_out ? "timeout" : phase, seq, tool_name, call_args, ir, timed.elapsed_ms, "");
            if (timed.timed_out || !ir.found || ir.threw || !ir.success) {
                log_msg(hf, "mcp.network_pg_sniff", "PRODUCT-FAIL -- phase=%s after valid fixture found=%d threw=%d success=%d timeout=%d elapsed_ms=%lld text=%s data=%s err=%s",
                    phase ? phase : "<null>",
                    ir.found ? 1 : 0,
                    ir.threw ? 1 : 0,
                    ir.success ? 1 : 0,
                    timed.timed_out ? 1 : 0,
                    timed.elapsed_ms,
                    compact_text(ir.text, 700).c_str(),
                    compact_json(ir.data, 900).c_str(),
                    compact_text(ir.exception_msg.empty() ? ir.text : ir.exception_msg, 700).c_str());
                record_tool_status(tool_name, timed.timed_out ? mcp_tool_call_status_t::timed_out : mcp_tool_call_status_t::failed);
                failed.fetch_add(1);
                return false;
            }
            std::string proof;
            if (!validator || !validator(ir, proof) || proof.empty()) {
                log_msg(hf, "mcp.network_pg_sniff", "FAIL -- phase=%s contract proof failed reason=%s text=%s data=%s",
                    phase ? phase : "<null>",
                    proof.empty() ? "<empty>" : compact_text(proof, 700).c_str(),
                    compact_text(ir.text, 700).c_str(),
                    compact_json(ir.data, 900).c_str());
                record_tool_status(tool_name, mcp_tool_call_status_t::failed);
                failed.fetch_add(1);
                return false;
            }
            log_msg(hf, "mcp.network_pg_sniff", "CONTRACT-PASS -- phase=%s proof=%s functional_capture_coverage=0",
                phase ? phase : "<null>",
                compact_text(proof, 900).c_str());
            record_tool_status(tool_name, mcp_tool_call_status_t::contract_pass);
            return true;
        };
        const bool install_ok = pg_contract_call("install", install_args,
            [&](const invoke_result_t& ir, std::string& proof) {
                uint64_t returned_pid = 0;
                uint64_t returned_size = 0;
                uint64_t returned_addr = 0;
                const bool has_session = payload_u64_field(ir.data, "session_id", session_id);
                const bool has_pid = payload_u64_field(ir.data, "pid", returned_pid);
                const bool has_size = payload_u64_field(ir.data, "size", returned_size);
                const bool has_addr = json_u64_field(ir.data, "address", returned_addr);
                if (!has_session || session_id == 0 || !has_pid || returned_pid != pid ||
                    !has_size || returned_size != install_size ||
                    !has_addr || returned_addr != pg_addr) {
                    proof = "install response missing session_id/pid/address/size contract fields";
                    return false;
                }
                proof = "install returned session_id=" + std::to_string(session_id) +
                    " pid=" + std::to_string(returned_pid) +
                    " address=" + hex_u64(returned_addr) +
                    " size=" + std::to_string(returned_size);
                return true;
            });
        if (!install_ok) {
            if (session_id != 0) {
                mcp_standalone::json cleanup_args;
                cleanup_args["operation"] = "uninstall";
                cleanup_args["session_id"] = session_id;
                pg_contract_call("uninstall_after_install_failure", cleanup_args,
                    [](const invoke_result_t& ir, std::string& proof) {
                        if (!payload_text_contains(ir, "uninstalled")) {
                            proof = "cleanup uninstall text did not confirm uninstalled";
                            return false;
                        }
                        proof = "cleanup uninstall text confirmed uninstalled";
                        return true;
                    });
            }
            if (pg_addr != 0)
                driver_bridge::free_memory(pg_addr);
            return;
        }
        uint64_t trigger_fn = resolve_remote_export("ntdll.dll", "RtlComputeCrc32");
        const char* trigger_kind = "RtlComputeCrc32";
        if (trigger_fn == 0) {
            trigger_fn = resolve_remote_export("ntdll.dll", "RtlCompareMemory");
            trigger_kind = "RtlCompareMemory";
        }
        uint64_t trigger_result = 0;
        if (trigger_fn != 0) {
            trigger_result = std::strcmp(trigger_kind, "RtlCompareMemory") == 0
                ? page_guard_engine::remote_thread_call(pid, trigger_fn, pg_addr, pg_addr, marker_text.size(), 0, 3000, "network_pg_sniff_RtlCompareMemory_fixture")
                : page_guard_engine::remote_thread_call(pid, trigger_fn, 0, pg_addr, marker_text.size(), 0, 3000, "network_pg_sniff_RtlComputeCrc32_fixture");
        }
        log_msg(hf, "mcp.network_pg_sniff", "TRIGGER -- session_id=%llu pid=%u addr=0x%016llX size=%zu trigger_kind=%s trigger_fn=0x%016llX trigger_result=0x%016llX status=\"%s\" last_error=\"%s\"",
            static_cast<unsigned long long>(session_id),
            pid,
            static_cast<unsigned long long>(pg_addr),
            marker_text.size(),
            trigger_kind,
            static_cast<unsigned long long>(trigger_fn),
            static_cast<unsigned long long>(trigger_result),
            driver_bridge::status().c_str(),
            driver_bridge::last_error().c_str());
        sidecar_capture_coverage_t direct_capture_coverage;
        std::string direct_capture_aggregate;
        auto pg_capture_poll = [&](DWORD timeout_ms) -> bool {
            const char* tool_name = "network_pg_sniff";
            const DWORD start = GetTickCount();
            int attempts = 0;
            mcp_standalone::json capture_args;
            capture_args["operation"] = "get_captures";
            capture_args["session_id"] = session_id;
            for (;;) {
                ++attempts;
                g_invoked_tools.insert(tool_name);
                const int seq = g_mcp_tool_sequence.fetch_add(1, std::memory_order_acq_rel) + 1;
                set_progress_step("mcp network_pg_sniff get_captures");
                log_msg(hf, "mcp.network_pg_sniff", "DISPATCH -- phase=get_captures seq=%d attempt=%d session_id=%llu pid=%u addr=0x%016llX args=%s",
                    seq,
                    attempts,
                    static_cast<unsigned long long>(session_id),
                    pid,
                    static_cast<unsigned long long>(pg_addr),
                    compact_json(capture_args, 900).c_str());
                auto timed = invoke_tool_bounded(get_server(), tool_name, capture_args, 10000, hf, "mcp.network_pg_sniff", seq);
                const invoke_result_t& ir = timed.result;
                log_mcp_result_detail(timed.timed_out ? "timeout" : "get_captures", seq, tool_name, capture_args, ir, timed.elapsed_ms, "");
                if (!timed.timed_out && ir.found && !ir.threw && ir.success) {
                    direct_capture_aggregate += ir.text;
                    direct_capture_aggregate += compact_json(ir.data, 3000);
                    sidecar_capture_coverage_t delta = marker_coverage_from_result(ir, marker_text);
                    direct_capture_coverage.captures += delta.captures;
                    direct_capture_coverage.iterations.insert(delta.iterations.begin(), delta.iterations.end());
                    log_msg(hf, "mcp.network_pg_sniff", "CAPTURE-POLL -- attempt=%d captures=%zu total_captures=%zu iterations=%s data=%s",
                        attempts,
                        delta.captures,
                        direct_capture_coverage.captures,
                        iteration_coverage_summary(direct_capture_coverage.iterations).c_str(),
                        compact_json(ir.data, 1200).c_str());
                    if (direct_capture_coverage.captures > 0) {
                        log_msg(hf, "mcp.network_pg_sniff", "FUNCTIONAL-PASS -- phase=get_captures session_id=%llu marker=%s captures=%zu iterations=%s trigger_kind=%s trigger_result=0x%016llX",
                            static_cast<unsigned long long>(session_id),
                            marker_text.c_str(),
                            direct_capture_coverage.captures,
                            iteration_coverage_summary(direct_capture_coverage.iterations).c_str(),
                            trigger_kind,
                            static_cast<unsigned long long>(trigger_result));
                        record_tool_status(tool_name, mcp_tool_call_status_t::functional_pass);
                        return true;
                    }
                } else {
                    direct_capture_aggregate += compact_text(ir.text, 900);
                    direct_capture_aggregate += compact_json(ir.data, 1200);
                    log_msg(hf, "mcp.network_pg_sniff", "CAPTURE-POLL-MISS -- attempt=%d timed_out=%d found=%d threw=%d success=%d elapsed_ms=%lld text=%s data=%s",
                        attempts,
                        timed.timed_out ? 1 : 0,
                        ir.found ? 1 : 0,
                        ir.threw ? 1 : 0,
                        ir.success ? 1 : 0,
                        timed.elapsed_ms,
                        compact_text(ir.text, 700).c_str(),
                        compact_json(ir.data, 900).c_str());
                }
                if (GetTickCount() - start >= timeout_ms)
                    break;
                Sleep(125);
            }
            log_msg(hf, "mcp.network_pg_sniff", "FAIL -- get_captures did not return guarded-page marker session_id=%llu marker=%s captures=%zu trigger_kind=%s trigger_fn=0x%016llX trigger_result=0x%016llX aggregate=%s",
                static_cast<unsigned long long>(session_id),
                marker_text.c_str(),
                direct_capture_coverage.captures,
                trigger_kind,
                static_cast<unsigned long long>(trigger_fn),
                static_cast<unsigned long long>(trigger_result),
                compact_text(direct_capture_aggregate, 1400).c_str());
            record_tool_status(tool_name, mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
            return false;
        };
        bool capture_ok = false;
        if (trigger_fn == 0) {
            log_msg(hf, "mcp.network_pg_sniff", "FAIL -- no safe ntdll guarded-page trigger export resolved session_id=%llu pid=%u",
                static_cast<unsigned long long>(session_id),
                pid);
            record_tool_status("network_pg_sniff", mcp_tool_call_status_t::failed);
            failed.fetch_add(1);
        } else {
            Sleep(100);
            capture_ok = pg_capture_poll(5000);
        }
        mcp_standalone::json list_args;
        list_args["operation"] = "list_sessions";
        const bool list_ok = pg_contract_call("list_sessions", list_args,
            [&](const invoke_result_t& ir, std::string& proof) {
                const auto* sessions = ir.data.is_object() ? find_payload_key_recursive(ir.data, "sessions") : nullptr;
                if (!sessions || !sessions->is_array()) {
                    proof = "list_sessions response missing sessions array";
                    return false;
                }
                bool found_session = false;
                for (const auto& item : *sessions) {
                    uint64_t listed_id = 0;
                    if ((payload_u64_field(item, "session_id", listed_id) || payload_u64_field(item, "id", listed_id)) &&
                        listed_id == session_id) {
                        found_session = true;
                        break;
                    }
                }
                if (!found_session) {
                    proof = "list_sessions did not include installed session_id=" + std::to_string(session_id);
                    return false;
                }
                proof = "list_sessions included installed session_id=" + std::to_string(session_id);
                return true;
            });
        mcp_standalone::json uninstall_args;
        uninstall_args["operation"] = "uninstall";
        uninstall_args["session_id"] = session_id;
        const bool uninstall_ok = pg_contract_call("uninstall", uninstall_args,
            [](const invoke_result_t& ir, std::string& proof) {
                if (!payload_text_contains(ir, "uninstalled")) {
                    proof = "uninstall text did not confirm uninstalled";
                    return false;
                }
                proof = "uninstall text confirmed uninstalled";
                return true;
            });
        bool freed = false;
        if (pg_addr != 0)
            freed = driver_bridge::free_memory(pg_addr);
        log_msg(hf, "mcp.network_pg_sniff", "CLEANUP -- session_id=%llu list_ok=%d capture_ok=%d uninstall_ok=%d freed=%d addr=0x%016llX functional_capture_coverage=%zu",
            static_cast<unsigned long long>(session_id),
            list_ok ? 1 : 0,
            capture_ok ? 1 : 0,
            uninstall_ok ? 1 : 0,
            freed ? 1 : 0,
            static_cast<unsigned long long>(pg_addr),
            direct_capture_coverage.captures);
    }

    void test_network_pg_sniff_payload_serialization(HANDLE hf, std::atomic<int>& passed, std::atomic<int>& failed, std::atomic<int>& skipped) {
        (void)skipped;
        const char* tag = "mcp.network_pg_sniff.payload_serialization";

        page_guard_engine::pg_capture_record_t rec;
        rec.metadata.timestamp = 1234;
        rec.metadata.fault_addr = 0x1004;
        rec.metadata.rip = 0x2000;
        rec.metadata.ctx_rdx = 0x1004;
        rec.metadata.exception_code = STATUS_GUARD_PAGE_VIOLATION;
        rec.metadata.access_type = 0;
        rec.payload_addr = 0x1004;
        rec.payload_offset = 4;
        rec.payload_read = true;
        rec.payload_source = "rdx";
        rec.payload = {'P', 'O', 'S', 'T', ' ', '/', 'l', 'a', 'b'};
        rec.payload_size = static_cast<uint32_t>(rec.payload.size());
        rec.payload_truncated = false;

        mcp_standalone::json out;
        page_guard_engine::serialize_payload_fields(out, rec);

        const bool ok = out.value("payload_available", false)
            && out.value("payload_size", 0u) == rec.payload_size
            && out.value("payload_preview_size", 0u) == rec.payload_size
            && out.value("payload_addr", std::string()) == "0x1004"
            && out.value("payload_offset", 0ull) == 4ull
            && out.value("payload_source", std::string()) == "rdx"
            && out.value("hex_preview", std::string()).find("50 4F 53 54") != std::string::npos
            && out.value("plaintext_preview", std::string()).find("POST /lab") != std::string::npos;

        if (!ok) {
            log_msg(hf, tag, "FAIL -- page guard capture serialized without payload preview: %s",
                compact_json(out, 800).c_str());
            failed.fetch_add(1);
            return;
        }

        log_msg(hf, tag, "PASS");
        passed.fetch_add(1);
    }

